const samples = [{"word": "階段", "reading": "かいだん", "image": "media/stairs-transparent.webp", "audio": "media/genki2_wd_ed9e2d8f86c2a50c.mp3", "doc": "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><base href=\"media/\"><style>/* ===== BASE / LIGHT MODE ===== */\n.card {\n  font-family: 'SF Pro Display', 'SF Pro Text', -apple-system, BlinkMacSystemFont,\n               'Hiragino Sans', 'Hiragino Kaku Gothic ProN', system-ui, sans-serif;\n  text-align: center;\n  padding: 24px 20px;\n  line-height: 1.6;\n  background: #ffffff;\n  color: #1a1a1a;\n  max-width: 600px;\n  margin: 0 auto;\n}\n.front-word {\n  font-size: 46px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n  letter-spacing: 0.02em;\n}\n.front-english {\n  font-size: 34px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n}\n.reading {\n  font-size: 26px;\n  color: #d63964;\n  margin: 8px 0;\n  font-weight: 500;\n}\n.meaning {\n  font-size: 22px;\n  color: #1a5276;\n  margin: 8px 0;\n  font-weight: 600;\n}\n.pos-tag {\n  display: inline-block;\n  background-color: #2c3e50;\n  color: #fff;\n  padding: 4px 14px;\n  border-radius: 14px;\n  font-size: 13px;\n  margin: 6px 0;\n  letter-spacing: 0.03em;\n}\n.example {\n  margin: 18px 0 8px;\n  padding: 14px 16px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #d63964;\n}\n.example-ja {\n  font-size: 19px;\n  color: #222;\n  margin-bottom: 6px;\n  line-height: 1.7;\n}\n.example-ja ruby rt {\n  line-height: 1;\n  font-size: 0.55em;\n  color: #888;\n  font-weight: 400;\n}\n.example-en {\n  font-size: 15px;\n  color: #555;\n  font-style: italic;\n  line-height: 1.45;\n}\n.divider {\n  border: none;\n  border-top: 1px solid #e0e0e0;\n  margin: 16px 0;\n}\n.hint {\n  font-size: 14px;\n  color: #999;\n  margin-top: 12px;\n  letter-spacing: 0.02em;\n}\n.audio {\n  margin: 8px 0;\n}\n\n/* --- Example card: even out top/bottom (furigana rides in the 1.7 line-height leading; hidden <audio> wrapper added 8px) --- */\n.example { padding-top: 10px; padding-bottom: 12px; }\n.example .example-ja { margin-bottom: 0; }\n.example .audio.example-audio { margin: 0; }\n\n/* --- Kanji breakdown (always open, matches .example card, blue accent) --- */\n.kanji-breakdown {\n  margin: 14px 0 8px;\n  padding: 14px 16px 12px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #1fa77c;\n}\n.kanji-breakdown .kb-content {\n  font-size: 15px;\n  line-height: 1.9;\n  color: #444;\n}\n\n/* ===== DARK MODE: Anki .nightMode class ===== */\n.nightMode .card,\n.nightMode.card {\n  background: #1e1e1e;\n  color: #e0e0e0;\n}\n.nightMode .front-word { color: #f0f0f0; }\n.nightMode .front-english { color: #f0f0f0; }\n.nightMode .reading { color: #f0826e; }\n.nightMode .meaning { color: #6cb4ee; }\n.nightMode .pos-tag { background-color: #3a3f4b; color: #ccc; }\n.nightMode .example { background: #2a2a2a; border-left-color: #f0826e; }\n.nightMode .example-ja { color: #ddd; }\n.nightMode .example-ja ruby rt { color: #aaa; }\n.nightMode .example-en { color: #b0b0b0; }\n.nightMode .divider { border-top-color: #3a3a3a; }\n.nightMode .hint { color: #777; }\n.nightMode .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n.nightMode .kanji-breakdown .kb-content { color: #bbb; }\n\n/* ===== DARK MODE: prefers-color-scheme ===== */\n@media (prefers-color-scheme: dark) {\n  .card { background: #1e1e1e; color: #e0e0e0; }\n  .front-word { color: #f0f0f0; }\n  .front-english { color: #f0f0f0; }\n  .reading { color: #f0826e; }\n  .meaning { color: #6cb4ee; }\n  .pos-tag { background-color: #3a3f4b; color: #ccc; }\n  .example { background: #2a2a2a; border-left-color: #f0826e; }\n  .example-ja { color: #ddd; }\n  .example-ja ruby rt { color: #aaa; }\n  .example-en { color: #b0b0b0; }\n  .divider { border-top-color: #3a3a3a; }\n  .hint { color: #777; }\n  .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n  .kanji-breakdown .kb-content { color: #bbb; }\n}\n\n\n/* --- Audio replay button (matches kanji-breakdown pill) --- */\n.audio.player {\n  margin-top: 14px;\n}\n\n.replay-button {\n  display: flex;\n  justify-content: center;\n  align-items: center; \n  margin: 12px auto;\n  padding: 8px 18px;\n  min-width: 44px;\n  min-height: 44px;\n  box-sizing: border-box;\n  background: #F0F8EA;\n  border: 1px solid #C2E9C3;\n  border-radius: 8px;\n  color: #3E8C40;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n  transition: background 0.15s;\n  text-decoration: none;\n  line-height: 1;\n  text-align: center;\n}\n.replay-button svg {\n  width: 20px;\n  height: 20px;\n  vertical-align: middle;\n  fill: currentColor;\n}\n.replay-button svg circle {\n  fill: none;\n  stroke: none;\n}\n.replay-button svg path {\n  fill: currentColor;\n  stroke: none;\n}\n.replay-button:hover { background: #F0F8EA; }\n.replay-button:active { background: #C2E1C8; }\n\n.nightMode .replay-button {\n  background: #2B3A2A;\n  border-color: #3A503D;\n  color: #73EA8B;\n}\n.nightMode .replay-button:hover { background: #2B3A2A; }\n.nightMode .replay-button:active { background: #273827; }\n\n@media (prefers-color-scheme: dark) {\n  .replay-button {\n    background: #334633;\n    border-color: #3A503D;\n    color: #73EA8B;\n  }\n  .replay-button:hover { background: #2B3A2A; }\n  .replay-button:active { background: #334633; }\n}\n\n\n/* --- Example sentence: tap the Japanese text to play the sentence audio --- */\n.example .example-ja.tap-play-ex {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.example .example-ja.tap-play-ex:active { opacity: 0.55; }\n\n/* --- Word audio: hidden auto-generated button; tap the reading to replay --- */\n.word-audio-hidden { display: none; }\n.reading.tap-play {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.reading.tap-play:active { opacity: 0.55; }\n\n\n/* --- kanji breakdown (k-brk) --- */\n.k-brk { padding: 0; margin: 0; font-family: -apple-system, \"Hiragino Sans\", sans-serif; }\n.k-brk + .k-brk { border-top: 1px solid rgba(128,128,128,0.13); margin-top: 14px; padding-top: 14px; }\n.k-brk .k-mean { font-weight: 500; margin-bottom: 8px; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; }\n.k-brk .k-head .k-char { margin-right: 0; }\n.k-brk .k-stats { display: flex; gap: 18px; align-items: flex-start; margin-left: auto; }\n.k-brk .k-stat { display: flex; flex-direction: column; align-items: center; line-height: 1.25; }\n.k-brk .k-stat-v { font-weight: 700; font-size: 1em; color: #222; line-height: 1.2; height: 1.2em; display: block; }\n.k-brk .k-stat-l { margin-top: 3px; line-height: 1; font-size: 0.48em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.nightMode .k-brk .k-stat-v { color: #ddd; }\n.k-brk .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-meta { font-size: 0.9em; color: #888; }\n.k-brk .k-radical, .k-brk .k-components, .k-brk .k-mean { font-size: 0.95em; margin-top: 3px; }\n.nightMode .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); } .k-brk .k-meta { color: #aaa; } .k-brk .k-stat-v { color: #ddd; } }\n\n/* --- kanji breakdown enhancements (readings) --- */\n.k-brk { line-height: 1.7; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; margin-bottom: 6px; line-height: 1.1; }\n.k-brk .k-head .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-head .k-meta { font-size: 0.9em; color: #888; vertical-align: middle; }\n.k-brk .k-mean, .k-brk .k-reading, .k-brk .k-radical, .k-brk .k-components { margin-top: 1px; line-height: 1.45; }\n.k-brk .k-reading { font-size: 0.95em; }\n.k-brk .k-label { display: inline-block; min-width: 2.6em; color: #666; font-weight: 600; font-size: 0.85em; margin-right: 4px; letter-spacing: 0.02em; }\n.nightMode .k-brk .k-head .k-meta { color: #aaa; }\n.nightMode .k-brk .k-label { color: #bbb; }\n@media (prefers-color-scheme: dark) {\n  .k-brk .k-head .k-meta { color: #aaa; }\n  .k-brk .k-label { color: #bbb; }\n}\n\n/* --- compact kanji entries: no components line, On/Kun readings inline --- */\n.k-brk .k-components { display: none; }\n.k-brk .k-reading { display: inline; word-break: keep-all; }\n.k-brk .k-reading + .k-reading { margin-left: 14px; }\n.k-brk .k-reading .k-label { min-width: 0; }\n.k-brk .k-reading + .k-radical { margin-top: 3px; }\n.k-brk .k-reading .k-r { white-space: nowrap; }\n\n/* --- tight vertical rhythm for kanji entries --- */\n.k-brk { line-height: 1.45; }\n.k-brk .k-head { margin-bottom: 4px; }\n.k-brk .k-mean { margin-bottom: 2px; }\n.k-brk .k-reading + .k-radical { margin-top: 1px; }\n.k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kanji-breakdown .kb-content { line-height: 1.5; }\n\n/* --- Nihongo deep-link styling (assertive) --- */\n.k-brk a, .k-brk .k-link { color: #1f665b !important; text-decoration: underline dotted !important; text-underline-offset: 2px; text-decoration-thickness: 1.5px; padding-bottom: 1px; }\n.k-brk .k-head a, .k-brk .k-head .k-link { text-decoration: none !important; padding-bottom: 0; }\n.k-brk .k-head .k-char { color: inherit; }\n.k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #222 !important; border-bottom: 2px dotted #1f665b !important; padding-bottom: 2px; }\n.k-brk a:active, .k-brk .k-link:active { background: rgba(31, 102, 91, 0.15); }\n.k-brk .k-head a:active .k-char, .k-brk .k-head .k-link:active .k-char { background: rgba(31, 102, 91, 0.15); }\n.nightMode .k-brk a, .nightMode .k-brk .k-link { color: #63c2b1 !important; }\n.nightMode .k-brk .k-head a .k-char, .nightMode .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n@media (prefers-color-scheme: dark) {\n  .k-brk a, .k-brk .k-link { color: #63c2b1 !important; }\n  .k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n}\n\n/* --- POS pill tap target (wraps .pos-tag in Nihongo word link) --- */\n.pos-tag-link { text-decoration: none; color: inherit; display: inline-block; }\n.pos-tag-link:active .pos-tag { opacity: 0.7; }\n\n/* === v2: stroke-order layout (Sep 2026) === */\n/* --- word block: furigana over the word, meaning below; whole block taps to play word audio --- */\n.word-block { position: relative; z-index: 1; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.word-block:active { opacity: 0.55; }\n/* the back word keeps the front word's exact box (margin 24px/16px, line-height 1.6) so it does not move on flip;\n   furigana hangs above the glyphs out of flow, in the leading + top margin */\n.front-word-ruby { position: relative; margin: 24px 0 -10px; line-height: 1.6; }\n.front-word-ruby .fw-base, .front-word-ruby .fk { position: relative; display: inline-block; line-height: 1; }\n.front-word-ruby .fw-read, .front-word-ruby .fr { position: absolute; left: 50%; bottom: 100%; transform: translateX(-50%); margin-bottom: 3px; font-size: 0.4em; font-weight: 500; color: #d63964; line-height: 1.2; letter-spacing: 0.02em; white-space: nowrap; }\n.word-block .meaning { margin-bottom: 0; }\n.word-block .meaning { margin-top: 4px; }\n.card.prod .front-english { margin-bottom: 0; }\n.card.prod .front-word-ruby { margin-top: 14px; }\n\n/* --- word info: part of speech + Nihongo word link; fades up behind the meaning --- */\n.wordinfo { position: relative; margin: -48px 0 0; padding: 62px 16px 10px; background: linear-gradient(to bottom, rgba(245,245,245,0) 0%, #f5f5f5 70%); border-radius: 10px; text-align: left; display: flex; align-items: center; justify-content: space-between; gap: 12px; overflow: hidden; }\n.card.prod .wordinfo { margin-top: -30px; padding-top: 44px; }\n.wordinfo-pos { font-size: 14px; font-weight: 600; color: #8c8c8c; letter-spacing: 0.01em; }\n.card a.wordinfo-nih { font-weight: 800; font-size: 20px; line-height: 1; color: #8c8c8c; text-decoration: none; padding: 0 0 2px; border-bottom: 2px dotted #8c8c8c; flex: none; -webkit-tap-highlight-color: transparent; }\n.card a.wordinfo-nih:active { background: rgba(0,0,0,0.08); }\n\n/* --- example card: the whole card taps to play the sentence --- */\n.example { margin-top: 12px; }\n.kanji-breakdown { margin-top: 12px; }\n.example.tap-play-ex { cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.example.tap-play-ex:active { opacity: 0.55; }\n.example .audio.example-audio { display: none; margin: 0; }\n\n/* --- example list (.ex-v2 is added by the template script): one .ex-item per sentence, split like the kanji entries.\n   The card itself has no padding - each item carries it, so the whole row (edge to edge) is the tap target --- */\n.example.ex-v2 { padding: 0; overflow: hidden; }\n.ex-v2 .ex-item { position: relative; padding: 10px 16px 12px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.ex-v2 .ex-item + .ex-item::before { content: \"\"; position: absolute; top: 0; left: 16px; right: 16px; border-top: 1px solid rgba(128,128,128,0.13); }\n.ex-v2 .ex-item:active { opacity: 0.55; }\n.ex-v2 .ex-item audio { display: none; }\n/* no-JS fallback: the separator stored in the fields still reads as a rule */\n.example hr.ex-sep { border: none; border-top: 1px solid rgba(128,128,128,0.13); margin: 8px 0; }\n.nightMode .ex-v2 .ex-item + .ex-item::before, .nightMode .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .ex-v2 .ex-item + .ex-item::before, .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); } }\n\n/* --- kanji entries (re-laid out by the template script; .kb-v2 is added once that has run) --- */\n.kb-v2 .k-brk { line-height: 1.45; }\n.kb-v2 .k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kb-v2 .k-head2 { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 5px; }\n.kb-v2 .k-readings { flex: 1 1 auto; min-width: 0; display: block; font-size: 0.95em; line-height: 1.4; }\n.kb-v2 .k-reading2 { display: flex; align-items: baseline; gap: 6px; color: #222; font-size: 1.02em; line-height: 1.5; }\n.kb-v2 .k-lab { flex: none; min-width: 2.4em; font-size: 0.68em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.kb-v2 .k-vals { color: #222; }\n.kb-v2 .k-r { white-space: nowrap; }\n.kb-v2 .k-mean2 { font-weight: 500; font-size: 1em; color: #222; line-height: 1.35; margin: 0; }\n.kb-v2 .k-stats2 { float: right; display: flex; flex-direction: column; align-items: flex-end; gap: 7px; margin-left: 12px; min-width: 2.2em; }\n.kb-v2 .k-sv { font-weight: 700; font-size: 0.8em; color: #8c8c8c; line-height: 1; letter-spacing: 0.02em; white-space: nowrap; }\n.kb-v2 .k-unit { font-size: 0.9em; font-weight: 600; margin-left: 1px; }\n.kb-v2 .k-brk a.k-nih { font-weight: 800; font-size: 1.35em; line-height: 1; color: #1f665b !important; text-decoration: none !important; padding: 0 0 2px; margin: -2px 0 2px; border-bottom: 2px dotted #1f665b; -webkit-tap-highlight-color: transparent; }\n.kb-v2 .k-brk a.k-nih:active { background: rgba(31,102,91,0.15); }\n\n/* --- on/kun readings tap to play their clip (class added by the template script); dotted underline = tappable --- */\n.kb-v2 .k-r.k-r-tap { cursor: pointer; text-decoration: underline dotted #a9a9a9; text-decoration-thickness: 1.5px; text-underline-offset: 4px; padding: 5px 2px; margin: 0 -2px; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.kb-v2 .k-r.k-r-tap:active { opacity: 0.55; }\n.kb-v2 .k-r.k-r-tap.playing { color: #1f665b; text-decoration-color: #1f665b; }\n.nightMode .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; }\n.nightMode .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; }\n@media (prefers-color-scheme: dark) { .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; } .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; } }\n\n/* --- every tap target: no double-tap zoom / 300 ms click delay on iOS --- */\n.word-block, .ex-v2 .ex-item, .kb-v2 .k-box, .kb-v2 .k-r.k-r-tap, .kb-v2 .k-head2, .card a.wordinfo-nih, .kb-v2 .k-brk a.k-nih { touch-action: manipulation; }\n\n/* --- the kanji grid box --- */\n.kb-v2 .k-box { position: relative; flex: none; width: 66px; height: 66px; box-sizing: border-box; border: 1.5px dotted #d2d2d2; border-radius: 4px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; --k-ink: #1f1f1f; --k-ghost: #bdbdbd; --k-grid: #c4c4c4; --k-dot: #49c248; }\n.kb-v2 .k-box:active { background: rgba(31,102,91,0.06); }\n.kb-v2 .k-fallback { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 40px; line-height: 1; color: #1f1f1f; }\n.kb-v2 .k-box.has-svg .k-fallback { display: none; }\n.kb-v2 .k-svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }\n.kb-v2 .k-grid line { stroke: var(--k-grid); stroke-width: 1.2; stroke-dasharray: 2 3; vector-effect: non-scaling-stroke; }\n.kb-v2 .k-ghost path { fill: none; stroke: var(--k-ghost); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; opacity: 0; transition: opacity 0.15s; }\n.kb-v2 .k-box.animating .k-ghost path { opacity: 1; }\n.kb-v2 .k-ink path { fill: none; stroke: var(--k-ink); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; }\n.kb-v2 .k-dot { fill: var(--k-dot); opacity: 0; transition: opacity 0.25s; }\n.kb-v2 .k-box.animating .k-dot, .kb-v2 .k-box.done .k-dot { opacity: 1; }\n.kb-v2 .k-play { position: absolute; right: -8px; bottom: -8px; width: 18px; height: 18px; border-radius: 50%; background: #efefef; color: #5a5a5a; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 0 2px #f5f5f5; cursor: pointer; z-index: 1; }\n.kb-v2 .k-play svg { width: 12px; height: 12px; margin-left: 2px; }\n.kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #dcdcdc; }\n.kb-v2 .k-box.animating .k-play { opacity: 0.55; }\n\n/* --- tap guard, answer side only (templates/tap_guard.js): taps on the card never reach AnkiMobile's tap zones.\n   The shield is a transparent full-screen layer behind the card, so the empty space around a short card is covered too --- */\n.tap-shield { position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 0; background: transparent; -webkit-tap-highlight-color: transparent; }\n.card[data-notap] { position: relative; z-index: 1; -webkit-tap-highlight-color: transparent; }\n\n/* --- narrow screens (iPhone): trim the side margins; wider screens keep max-width 600 + 20px padding --- */\n@media (max-width: 480px) {\n  body { margin-left: 0; margin-right: 0; }\n  .card { padding: 14px 12px 24px; }\n}\n\n/* dark (Anki .nightMode) */\n.nightMode .front-word-ruby .fw-read, .nightMode .front-word-ruby .fr { color: #f0826e; }\n.nightMode .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n.nightMode .wordinfo-pos { color: #8f8f8f; }\n.nightMode .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n.nightMode .kb-v2 .k-reading2, .nightMode .kb-v2 .k-vals { color: #e6e6e6; }\n.nightMode .kb-v2 .k-lab { color: #8a8a8a; }\n.nightMode .kb-v2 .k-mean2 { color: #e6e6e6; }\n.nightMode .kb-v2 .k-sv { color: #8f8f8f; }\n.nightMode .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n.nightMode .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n.nightMode .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n.nightMode .kb-v2 .k-fallback { color: #f2f2f2; }\n.nightMode .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n.nightMode .kb-v2 .k-box:active .k-play, .nightMode .kb-v2 .k-play:active { background: #4a4a4a; }\n\n/* dark (system) */\n@media (prefers-color-scheme: dark) {\n  .front-word-ruby .fw-read, .front-word-ruby .fr { color: #f0826e; }\n  .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n  .wordinfo-pos { color: #8f8f8f; }\n  .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n  .kb-v2 .k-reading2, .kb-v2 .k-vals { color: #e6e6e6; }\n  .kb-v2 .k-lab { color: #8a8a8a; }\n  .kb-v2 .k-mean2 { color: #e6e6e6; }\n  .kb-v2 .k-sv { color: #8f8f8f; }\n  .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n  .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n  .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n  .kb-v2 .k-fallback { color: #f2f2f2; }\n  .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n  .kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #4a4a4a; }\n}\n\n/* Answer-only compact reveal. Fronts and unillustrated cards keep their layout. */\n/* Anki can paint inserted HTML before evaluating its template scripts.\n   Suppress that intermediate layout, but automatically show it after 700ms\n   even if scripts fail. Never depend on JavaScript to make a card readable. */\n.card[data-notap]:has(.vocab-visual):not(.visual-ready) {\n  animation: visual-prepare-fallback 700ms step-end both;\n}\n@keyframes visual-prepare-fallback { from { opacity: 0; } to { opacity: 1; } }\n.vocab-visual { margin: 0; text-align: center; }\n.card.has-vocab-visual > .vocab-visual {\n  margin: -24px 0 0;\n  /* Reserve the final banner height; animate the artwork, not a clipping mask. */\n  overflow: visible;\n}\n.vocab-visual img {\n  display: block;\n  width: 100%;\n  max-width: 480px;\n  height: auto;\n  aspect-ratio: 3 / 1;\n  object-fit: contain;\n  box-sizing: border-box;\n  padding: 4% 6%;\n  margin: 0 auto;\n  border-radius: 0;\n  transform-origin: center center;\n\n}\n.card.visual-ready .vocab-visual img {\n  animation: visual-entrance 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.has-vocab-visual .front-word-ruby {\n  font-size: 32px;\n  line-height: 1.35;\n  /* Furigana occupies the gap; image padding already supplies breathing room. */\n  margin: 14px 0 0;\n  text-align: center;\n  transform-origin: center center;\n\n}\n.card.has-vocab-visual .meaning { font-size: 18px; line-height: 1.35; margin: 2px 0 0; }\n/* Keep the shared light/dark gradient behind the compact meaning and POS. */\n.card.has-vocab-visual .wordinfo { margin: -32px 0 0; padding: 38px 16px 10px; }\n.card.has-vocab-visual.prod .front-english { font-size: 22px; line-height: 1.3; margin: 6px 0 0; }\n.card.has-vocab-visual.prod .front-word-ruby { margin-top: 16px; }\n.card.has-vocab-visual .example { margin-top: 6px; }\n/* One moving answer block preserves every internal spacing relationship. */\n.visual-content { display: flow-root; }\n.card.visual-ready .visual-content {\n  animation: visual-content-slide 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready:not(.prod) .front-word-ruby {\n  animation: visual-word 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready .meaning,\n.card.visual-ready .wordinfo,\n.card.visual-ready .example,\n.card.visual-ready .kanji-breakdown,\n.card.visual-ready .fw-read,\n.card.visual-ready .fr {\n  animation: visual-details 400ms ease-out 100ms both;\n}\n.card.visual-ready.prod .front-english {\n  animation: visual-english 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n@keyframes visual-english { from { font-size: 34px; line-height: 1.6; color: var(--visual-cue-start, #111); } to { font-size: 22px; line-height: 1.3; color: var(--visual-cue-end, #8c8c8c); } }\n@keyframes visual-details { from { opacity: 0; } to { opacity: 1; } }\n@keyframes visual-content-slide {\n  from { transform: translateY(var(--visual-content-start, -100px)); }\n  to { transform: translateY(0); }\n}\n@keyframes visual-entrance {\n  from { opacity: 0; transform: translateY(-100%) scale(.94); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n@keyframes visual-word { from { transform: scale(1.4375); } to { transform: scale(1); } }\n@media (max-width: 480px) {\n  .card.has-vocab-visual > .vocab-visual { margin: -14px 0 0; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .card.has-vocab-visual > .vocab-visual,\n  .card.has-vocab-visual .vocab-visual img,\n  .card.visual-ready .visual-content,\n  .card.has-vocab-visual .fr,\n  .card.has-vocab-visual .fw-read,\n  .card.visual-ready:not(.prod) .front-word-ruby,\n  .card.visual-ready.prod .front-english,\n  .card.has-vocab-visual .meaning,\n  .card.has-vocab-visual .wordinfo,\n  .card.has-vocab-visual .example,\n  .card.has-vocab-visual .kanji-breakdown,\n  .card.has-vocab-visual.prod .front-english { animation: none; }\n}\n\n/* De-emphasize the English cue only after revealing a Production answer. */\n.card.prod:has(.wordinfo) .front-english { color: #8c8c8c; }\n.nightMode .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n}\n\n/* Carry the question color through the shrink instead of swapping it on reveal. */\n.nightMode .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n}\n.card.visual-ready.prod .word-block { animation: visual-details 400ms ease-out 100ms both; }\n@media (prefers-reduced-motion: reduce) {\n  .card.visual-ready.prod .word-block { animation: none; }\n}\n\nhtml,body{margin:0;padding:0;background:transparent}.card{padding-top:0;padding-bottom:16px;display:flow-root}.tap-shield{display:none}.word-block{cursor:pointer}\n</style></head><body><script src=\"_kanji_strokes.js\"></script>\n<div class=\"tap-shield tappable\" onclick=\"void 0\"></div>\n<div class=\"card tappable has-vocab-visual\" data-notap onclick=\"void 0\">\n<div class=\"word-block tap-play\" onclick=\"event.stopPropagation();var b=this.parentNode.querySelector('.word-audio-hidden a');if(b)b.click();\">\n<div class=\"front-word front-word-ruby\"><span class=\"fw-base\">階段</span><span class=\"fw-read\">かいだん</span></div>\n<div class=\"meaning\">stairs</div>\n</div>\n<div class=\"word-audio-hidden\"><a href=\"#\" onclick=\"event.preventDefault();this.nextElementSibling.currentTime=0;this.nextElementSibling.play()\">Play</a><audio src=\"genki2_wd_ed9e2d8f86c2a50c.mp3\"></audio></div>\n<div class=\"wordinfo\">\n<div class=\"wordinfo-pos\">Noun</div>\n<a class=\"wordinfo-nih\" href=\"https://nihongo-app.com/dictionary/word/階段\">語</a>\n</div>\n<div class=\"example tap-play-ex\" onclick=\"event.stopPropagation();var a=this.querySelector('audio');if(a){a.currentTime=0;a.play();}\">\n<div class=\"example-ja\"><ruby>階段<rt>かいだん</rt></ruby>で <ruby>二階<rt>にかい</rt></ruby>に <ruby>上<rt>あ</rt></ruby>がりました。<hr class=\"ex-sep\">エレベーターを <ruby>使<rt>つか</rt></ruby>わないで、 <ruby>階段<rt>かいだん</rt></ruby>を <ruby>上<rt>のぼ</rt></ruby>ることにしています。</div>\n<div class=\"example-en\">I went up to the second floor by the stairs.<hr class=\"ex-sep\">I make it a rule to climb the stairs instead of using the elevator.</div>\n<div class=\"audio example-audio\"><audio src=\"genki2-5edf295731df695d05078de9.mp3\" preload=\"none\"></audio><audio src=\"genki2-2191a49f93d62c032b408dc5.mp3\" preload=\"none\"></audio></div>\n</div>\n\n<div class=\"kanji-breakdown\">\n<div class=\"kb-content\"><div class=\"k-brk\">\n  <div class=\"k-head\"><a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji/階\"><span class=\"k-char\">階</span></a><span class=\"k-stats\"><span class=\"k-stat\"><span class=\"k-stat-v\">12</span><span class=\"k-stat-l\">Strokes</span></span><span class=\"k-stat\"><span class=\"k-stat-v\">N2</span><span class=\"k-stat-l\">JLPT</span></span></span></div>\n  <div class=\"k-mean\">storey, stair, counter for storeys of a building</div>\n  <div class=\"k-reading\"><span class=\"k-label\">On:</span> <span class=\"k-r\">カイ</span></div>\n  <div class=\"k-reading\"><span class=\"k-label\">Kun:</span> <span class=\"k-r\">きざはし</span></div>\n  <div class=\"k-radical\"><span class=\"k-label\">Radical:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/阜\">阜</a> (oka, mound)</div>\n  <div class=\"k-components\"><span class=\"k-label\">Components:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/白\">白</a> white, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/比\">比</a> compare, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/⻖\">⻖</a></div>\n</div>\n<div class=\"k-brk\">\n  <div class=\"k-head\"><a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji/段\"><span class=\"k-char\">段</span></a><span class=\"k-stats\"><span class=\"k-stat\"><span class=\"k-stat-v\">9</span><span class=\"k-stat-l\">Strokes</span></span><span class=\"k-stat\"><span class=\"k-stat-v\">N2</span><span class=\"k-stat-l\">JLPT</span></span></span></div>\n  <div class=\"k-mean\">grade, steps, stairs</div>\n  <div class=\"k-reading\"><span class=\"k-label\">On:</span> <span class=\"k-r\">ダン</span>, <span class=\"k-r\">タン</span></div>\n  <div class=\"k-radical\"><span class=\"k-label\">Radical:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/殳\">殳</a> (hokotsukuri, weapon)</div>\n  <div class=\"k-components\"><span class=\"k-label\">Components:</span> ｜, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/殳\">殳</a> pike, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/几\">几</a> table, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/又\">又</a> or again</div>\n</div></div>\n</div>\n\n<span class=\"visual-key\" hidden>階段|かいだん</span>\n<span class=\"dictionary-key\" hidden>階段|かいだん|stairs</span>\n<script>\n(function(){\n  var NS = 'http://www.w3.org/2000/svg';\n  var KANJI_RE = /[㐀-鿿豈-﫿々]/;\n  function el(tag, attrs){ var e = document.createElementNS(NS, tag); for (var k in attrs) e.setAttribute(k, attrs[k]); return e; }\n  function txt(n){ return n ? (n.textContent || '').replace(/\\s+/g, ' ').trim() : ''; }\n  function stop(e){ e.stopPropagation(); }\n  function guard(node){ node.addEventListener('click', stop, false); node.addEventListener('touchend', stop, false); }\n  /* run fn on a tap. iOS drops the click after a touch that stops a momentum scroll or that it takes for a double-tap,\n     so on touch devices we act on touchend of an unmoved touch and suppress the synthetic click; mouse/desktop use click */\n  function tap(node, fn){\n    var sx = 0, sy = 0, moved = true, handled = false;\n    node.addEventListener('touchstart', function(e){ var t = e.touches[0]; if (!t || e.touches.length > 1) { moved = true; return; } sx = t.clientX; sy = t.clientY; moved = false; handled = false; }, {passive: true});\n    node.addEventListener('touchmove', function(e){ var t = e.touches[0]; if (!t || Math.abs(t.clientX - sx) > 12 || Math.abs(t.clientY - sy) > 12) moved = true; }, {passive: true});\n    node.addEventListener('touchend', function(e){ if (moved) return; moved = true; handled = true; if (e.cancelable) e.preventDefault(); fn(); }, {passive: false});\n    node.addEventListener('touchcancel', function(){ moved = true; }, {passive: true});\n    node.addEventListener('click', function(){ if (handled) { handled = false; return; } fn(); }, false);\n  }\n  // scope everything to the card this script lives in (falls back to the last card on the page)\n  var root = null, cs = document.currentScript;\n  if (cs && cs.closest) root = cs.closest('.card');\n  if (!root) { var cards = document.querySelectorAll('.card'); root = cards.length ? cards[cards.length - 1] : document; }\n\n  /* ---- align a kana reading to the kanji runs of a word: お願いします + おねがいします -> お<ruby>願<rt>ねが</rt></ruby>います ---- */\n  function toHira(s){ return s.replace(/[ァ-ヶ]/g, function(c){ return String.fromCharCode(c.charCodeAt(0) - 0x60); }); }\n  function isKanji(c){ return KANJI_RE.test(c); }\n  function isKana(c){ return /[ぁ-ゟ゠-ヿ]/.test(c); }\n  function esc(s){ return s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&'); }\n  function alignFurigana(word, reading){\n    reading = (reading || '').replace(/\\s+/g, '');\n    if (word.indexOf('(') < 0) reading = reading.replace(/[（(][^)）]*[)）]/g, '');\n    if (word.indexOf('/') < 0 && reading.indexOf('/') >= 0) reading = reading.split('/')[0];\n    var hira = toHira(reading);\n    // split the word into runs: kanji / kana / other\n    var runs = [], i, c, t, cur = null;\n    for (i = 0; i < word.length; i++) {\n      c = word.charAt(i); t = isKanji(c) ? 'k' : (isKana(c) ? 'a' : 'o');\n      if (c === '々' && cur && cur.t === 'k') t = 'k';\n      if (cur && cur.t === t) cur.s += c; else { cur = {t:t, s:c}; runs.push(cur); }\n    }\n    var kanjiRuns = 0; for (i = 0; i < runs.length; i++) if (runs[i].t === 'k') kanjiRuns++;\n    if (!kanjiRuns) return null;\n    var pat = '^';\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') pat += '(.+?)';\n      else if (runs[i].t === 'a') pat += esc(toHira(runs[i].s));\n      else pat += '(?:' + esc(runs[i].s) + ')?';\n    }\n    pat += '$';\n    var m = hira.match(new RegExp(pat));\n    if (!m) return null;\n    var out = [], gi = 1, pos = 0;\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') {\n        // take the kana slice from the original reading (keeps katakana if it was katakana)\n        var idx = hira.indexOf(m[gi], pos); if (idx < 0) return null;\n        out.push({kanji: runs[i].s, kana: reading.substr(idx, m[gi].length)});\n        pos = idx + m[gi].length; gi++;\n      } else { out.push({text: runs[i].s}); if (runs[i].t === 'a') pos += runs[i].s.length; }\n    }\n    return out;\n  }\n  function fk(kanji, kana){\n    var s = document.createElement('span'); s.className = 'fk'; s.appendChild(document.createTextNode(kanji));\n    var r = document.createElement('span'); r.className = 'fr'; r.textContent = kana; s.appendChild(r);\n    return s;\n  }\n  function renderFurigana(container, word, reading){\n    var parts = alignFurigana(word, reading);\n    if (!parts) return false;\n    while (container.firstChild) container.removeChild(container.firstChild);\n    for (var i = 0; i < parts.length; i++) {\n      if (parts[i].kanji) container.appendChild(fk(parts[i].kanji, parts[i].kana));\n      else container.appendChild(document.createTextNode(parts[i].text));\n    }\n    return true;\n  }\n  function renderWhole(container, word, reading){\n    while (container.firstChild) container.removeChild(container.firstChild);\n    if (reading) container.appendChild(fk(word, reading)); else container.appendChild(document.createTextNode(word));\n  }\n\n  /* ---- 1. furigana over the word: only over the kanji, hung above the glyphs so the word sits exactly where it does on the front ---- */\n  var fw = root.querySelector('.front-word-ruby');\n  if (fw) {\n    var baseEl = fw.querySelector('.fw-base'), readEl = fw.querySelector('.fw-read');\n    var base = txt(baseEl), reading = txt(readEl);\n    if (!KANJI_RE.test(base) || reading === base || !reading) renderWhole(fw, base, '');\n    else if (!renderFurigana(fw, base, reading)) renderWhole(fw, base, reading);\n  }\n\n  /* ---- 2. audio tap targets must never reach the card's tap gestures ---- */\n  var taps = root.querySelectorAll('.tap-play, .tap-play-ex, .wordinfo-nih');\n  for (var i = 0; i < taps.length; i++) guard(taps[i]);\n\n  /* ---- 2b. example sentences: the fields may hold two sentences separated by <hr class=\"ex-sep\">.\n     Re-lay them out as list items (.ex-item = Japanese + English + its own clip); the WHOLE item,\n     padding included, is the tap target, and nothing inside the red card ever reaches Anki's tap gestures ---- */\n  var ex = root.querySelector('.example');\n  if (ex && !ex.classList.contains('ex-v2')) {\n    var splitAtHr = function(node){\n      var groups = [[]]; if (!node) return groups;\n      var n = node.firstChild;\n      while (n) { var nx = n.nextSibling; if (n.nodeType === 1 && n.tagName === 'HR') groups.push([]); else groups[groups.length - 1].push(n); n = nx; }\n      return groups;\n    };\n    var jaG = splitAtHr(ex.querySelector('.example-ja')), enG = splitAtHr(ex.querySelector('.example-en'));\n    var auds = ex.querySelectorAll('audio'), items = [], g, k;\n    for (g = 0; g < jaG.length; g++) {\n      var item = document.createElement('div'); item.className = 'ex-item'; item.setAttribute('role', 'button');\n      var ja = document.createElement('div'); ja.className = 'example-ja';\n      for (k = 0; k < jaG[g].length; k++) ja.appendChild(jaG[g][k]);\n      item.appendChild(ja);\n      if (enG[g]) { var en = document.createElement('div'); en.className = 'example-en'; for (k = 0; k < enG[g].length; k++) en.appendChild(enG[g][k]); item.appendChild(en); }\n      if (auds[g]) item.appendChild(auds[g]);\n      items.push(item);\n    }\n    while (ex.firstChild) ex.removeChild(ex.firstChild);\n    ex.removeAttribute('onclick'); ex.onclick = null;\n    ex.classList.remove('tap-play-ex'); ex.classList.add('ex-v2');\n    var playItem = function(item){\n      var all = ex.querySelectorAll('audio'), mine = item.querySelector('audio');\n      for (var a = 0; a < all.length; a++) if (all[a] !== mine) { try { all[a].pause(); all[a].currentTime = 0; } catch (e) {} }\n      if (mine) { try { mine.currentTime = 0; } catch (e) {} var pr = mine.play(); if (pr && pr.catch) pr.catch(function(){}); }\n    };\n    for (g = 0; g < items.length; g++) {\n      ex.appendChild(items[g]); guard(items[g]);\n      (function(it){ tap(it, function(){ playItem(it); }); })(items[g]);\n    }\n  }\n\n  /* ---- 3. re-lay out each kanji breakdown entry (field markup stays unchanged) ---- */\n  var kb = root.querySelector('.kanji-breakdown');\n  if (kb && !kb.classList.contains('kb-v2')) {\n    var brks = kb.querySelectorAll('.k-brk');\n    for (var b = 0; b < brks.length; b++) relayout(brks[b]);\n    kb.classList.add('kb-v2');\n\n    /* ---- 3b. tappable on/kun readings: each .k-r plays `_kr_<hex of the hiragana reading>.mp3`\n       (a _-prefixed template media file; okurigana marks, dots and hyphens are dropped, katakana -> hiragana).\n       The whole head row swallows taps so a near miss never flips the card. ---- */\n    var krAudio = null;\n    var krFile = function(t){\n      var sp = toHira(t.replace(/[-.()（）\\s‐－]/g, '')), hex = '';\n      if (!sp || !/^[ぁ-ゖー]+$/.test(sp)) return null;\n      for (var i = 0; i < sp.length; i++) hex += ('0000' + sp.charCodeAt(i).toString(16)).slice(-4);\n      return '_kr_' + hex + '.mp3';\n    };\n    var playKr = function(node, file){\n      if (!krAudio) { krAudio = document.createElement('audio'); krAudio.setAttribute('preload', 'none'); krAudio.style.display = 'none'; root.appendChild(krAudio); }\n      var others = root.querySelectorAll('.example audio');\n      for (var o = 0; o < others.length; o++) { try { others[o].pause(); } catch (e) {} }\n      var on = kb.querySelectorAll('.k-r.playing'); for (var q = 0; q < on.length; q++) on[q].classList.remove('playing');\n      node.classList.add('playing'); setTimeout(function(){ node.classList.remove('playing'); }, 700);\n      try { krAudio.pause(); krAudio.src = file; krAudio.currentTime = 0; } catch (e) {}\n      var pr = krAudio.play(); if (pr && pr.catch) pr.catch(function(){});\n    };\n    var krs = kb.querySelectorAll('.k-r');\n    for (var r2 = 0; r2 < krs.length; r2++) (function(node){\n      var file = krFile(txt(node)); if (!file) return;\n      node.classList.add('k-r-tap'); node.setAttribute('role', 'button');\n      guard(node); tap(node, function(){ playKr(node, file); });\n    })(krs[r2]);\n    var heads = kb.querySelectorAll('.k-head2'); for (var h2 = 0; h2 < heads.length; h2++) guard(heads[h2]);\n  }\n\n  function relayout(brk){\n    var ch = txt(brk.querySelector('.k-char'));\n    if (!ch) return;\n    var link = brk.querySelector('.k-head a');\n    var href = (link && link.getAttribute('href')) || ('https://nihongo-app.com/dictionary/kanji/' + ch);\n    var strokes = '', jlpt = '';\n    var stats = brk.querySelectorAll('.k-stat');\n    for (var s = 0; s < stats.length; s++) {\n      var lab = txt(stats[s].querySelector('.k-stat-l')).toLowerCase(), v = txt(stats[s].querySelector('.k-stat-v'));\n      if (lab.indexOf('stroke') === 0) strokes = v; else if (lab.indexOf('jlpt') === 0) jlpt = v;\n    }\n    var meanText = txt(brk.querySelector('.k-mean'));\n    var readings = brk.querySelectorAll('.k-reading');\n\n    var head = document.createElement('div'); head.className = 'k-head2';\n    var box = document.createElement('div'); box.className = 'k-box'; box.setAttribute('data-kanji', ch); box.setAttribute('role', 'button');\n    var fb = document.createElement('span'); fb.className = 'k-fallback'; fb.textContent = ch; box.appendChild(fb);\n    var play = document.createElement('span'); play.className = 'k-play';\n    play.innerHTML = '<svg viewBox=\"0 0 12 12\"><path d=\"M3.6 2.2 L10 6 L3.6 9.8 Z\" fill=\"currentColor\"/></svg>';\n    box.appendChild(play);\n    head.appendChild(box);\n\n    var col = document.createElement('div'); col.className = 'k-readings';\n    var st = document.createElement('span'); st.className = 'k-stats2';\n    var nih = document.createElement('a'); nih.className = 'k-nih'; nih.href = href; nih.textContent = '語'; st.appendChild(nih);\n    if (strokes) { var sv = document.createElement('span'); sv.className = 'k-sv'; sv.innerHTML = strokes + '<span class=\"k-unit\">画</span>'; st.appendChild(sv); }\n    if (jlpt) { var jv = document.createElement('span'); jv.className = 'k-sv'; jv.textContent = jlpt; st.appendChild(jv); }\n    col.appendChild(st);\n    for (var r = 0; r < readings.length; r++) {\n      var src = readings[r], label = src.querySelector('.k-label');\n      var row = document.createElement('div'); row.className = 'k-reading2';\n      var lab2 = document.createElement('span'); lab2.className = 'k-lab'; lab2.textContent = txt(label).replace(/:$/, ''); row.appendChild(lab2);\n      var vals = document.createElement('span'); vals.className = 'k-vals';\n      var n = src.firstChild;\n      while (n) { var next = n.nextSibling; if (n !== label) vals.appendChild(n); n = next; }\n      row.appendChild(vals); col.appendChild(row);\n    }\n    head.appendChild(col);\n\n    var mean = document.createElement('div'); mean.className = 'k-mean2'; mean.textContent = meanText;\n\n    while (brk.firstChild) brk.removeChild(brk.firstChild);\n    brk.appendChild(head); brk.appendChild(mean);\n    guard(box); guard(nih);\n    tap(box, function(){ animate(box); });\n  }\n\n  /* ---- 4. stroke-order boxes (KanjiVG paths from _kanji_strokes.js) ---- */\n  function buildBox(box){\n    var strokes = window.KANJI_STROKES[box.getAttribute('data-kanji')];\n    if (!strokes || !strokes.length) return;\n    var svg = el('svg', {viewBox:'-7 -7 123 123', 'class':'k-svg', 'aria-hidden':'true'});\n    var grid = el('g', {'class':'k-grid'});\n    grid.appendChild(el('line', {x1:54.5, y1:-5, x2:54.5, y2:114}));\n    grid.appendChild(el('line', {x1:-5, y1:54.5, x2:114, y2:54.5}));\n    svg.appendChild(grid);\n    var ghost = el('g', {'class':'k-ghost'}), ink = el('g', {'class':'k-ink'}), paths = [];\n    for (var i = 0; i < strokes.length; i++) {\n      ghost.appendChild(el('path', {d:strokes[i]}));\n      var p = el('path', {d:strokes[i]}); ink.appendChild(p); paths.push(p);\n    }\n    svg.appendChild(ghost); svg.appendChild(ink);\n    var dot = el('circle', {'class':'k-dot', r:5.2, cx:-20, cy:-20});\n    svg.appendChild(dot);\n    box.insertBefore(svg, box.firstChild);\n    box.classList.add('has-svg');\n    box._k = {paths:paths, dot:dot, raf:0, timer:0};\n  }\n  function cancel(box){\n    var s = box._k; if (!s) return;\n    if (s.raf) cancelAnimationFrame(s.raf); s.raf = 0;\n    if (s.timer) clearTimeout(s.timer); s.timer = 0;\n    box.classList.remove('animating'); box.classList.remove('done');\n  }\n  function animate(box){\n    if (!box._k && window.KANJI_STROKES) buildBox(box);   // asset arrived after this box was laid out\n    var s = box._k; if (!s) return;\n    cancel(box);\n    var lens = [], i, p;\n    for (i = 0; i < s.paths.length; i++) { lens.push(s.paths[i].getTotalLength()); }\n    for (i = 0; i < s.paths.length; i++) { p = s.paths[i]; p.style.strokeDasharray = lens[i] + ' ' + lens[i]; p.style.strokeDashoffset = lens[i]; }\n    box.classList.add('animating');\n    var idx = 0, t0 = 0, GAP = 70;\n    function dur(len){ return Math.max(170, 90 + len * 4.6); }\n    function ease(t){ return 1 - Math.pow(1 - t, 1.5); }\n    function step(ts){\n      if (!t0) t0 = ts;\n      var q = s.paths[idx], len = lens[idx], t = Math.min(1, (ts - t0) / dur(len)), e = ease(t);\n      q.style.strokeDashoffset = len * (1 - e);\n      var pt = q.getPointAtLength(len * e);\n      s.dot.setAttribute('cx', pt.x); s.dot.setAttribute('cy', pt.y);\n      if (t < 1) { s.raf = requestAnimationFrame(step); return; }\n      idx++; t0 = 0;\n      if (idx < s.paths.length) {\n        s.timer = setTimeout(function(){ s.timer = 0; s.raf = requestAnimationFrame(step); }, GAP);\n      } else {\n        box.classList.remove('animating'); box.classList.add('done');\n        s.timer = setTimeout(function(){ s.timer = 0; box.classList.remove('done'); }, 650);\n      }\n    }\n    var p0 = s.paths[0].getPointAtLength(0); s.dot.setAttribute('cx', p0.x); s.dot.setAttribute('cy', p0.y);\n    s.raf = requestAnimationFrame(step);\n  }\n  var tries = 0;\n  function fill(){\n    if (window.KANJI_STROKES) {\n      var boxes = root.querySelectorAll('.k-box:not(.has-svg)');\n      for (var i = 0; i < boxes.length; i++) buildBox(boxes[i]);\n    } else if (tries++ < 150) { setTimeout(fill, tries < 20 ? 50 : 200); }   // external asset may still be loading (waits up to ~27 s)\n  }\n  fill();\n  // if the asset script is still in flight, fill as soon as it lands (covers WebViews that load it asynchronously)\n  var ks = document.querySelectorAll('script[src*=\"_kanji_strokes\"]');\n  for (var si = 0; si < ks.length; si++) ks[si].addEventListener('load', fill, false);\n})();\n\n</script>\n<script>\n\n</script>\n</div>\n</body></html>"}, {"word": "財布", "reading": "さいふ", "image": "media/vocab-87eb6fcbc6b9.webp", "audio": "media/n5_wd_2fb44a8342b35048.mp3", "doc": "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><base href=\"media/\"><style>/* ===== BASE / LIGHT MODE ===== */\n.card {\n  font-family: 'SF Pro Display', 'SF Pro Text', -apple-system, BlinkMacSystemFont,\n               'Hiragino Sans', 'Hiragino Kaku Gothic ProN', system-ui, sans-serif;\n  text-align: center;\n  padding: 24px 20px;\n  line-height: 1.6;\n  background: #ffffff;\n  color: #1a1a1a;\n  max-width: 600px;\n  margin: 0 auto;\n}\n.front-word {\n  font-size: 46px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n  letter-spacing: 0.02em;\n}\n.front-english {\n  font-size: 34px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n}\n.reading {\n  font-size: 26px;\n  color: #d63964;\n  margin: 8px 0;\n  font-weight: 500;\n}\n.meaning {\n  font-size: 22px;\n  color: #1a5276;\n  margin: 8px 0;\n  font-weight: 600;\n}\n.pos-tag {\n  display: inline-block;\n  background-color: #2c3e50;\n  color: #fff;\n  padding: 4px 14px;\n  border-radius: 14px;\n  font-size: 13px;\n  margin: 6px 0;\n  letter-spacing: 0.03em;\n}\n.example {\n  margin: 18px 0 8px;\n  padding: 14px 16px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #d63964;\n}\n.example-ja {\n  font-size: 19px;\n  color: #222;\n  margin-bottom: 6px;\n  line-height: 1.7;\n}\n.example-ja ruby rt {\n  line-height: 1;\n  font-size: 0.55em;\n  color: #888;\n  font-weight: 400;\n}\n.example-en {\n  font-size: 15px;\n  color: #555;\n  font-style: italic;\n  line-height: 1.45;\n}\n.divider {\n  border: none;\n  border-top: 1px solid #e0e0e0;\n  margin: 16px 0;\n}\n.hint {\n  font-size: 14px;\n  color: #999;\n  margin-top: 12px;\n  letter-spacing: 0.02em;\n}\n.audio {\n  margin: 8px 0;\n}\n\n/* --- Example card: even out top/bottom (furigana rides in the 1.7 line-height leading; hidden <audio> wrapper added 8px) --- */\n.example { padding-top: 10px; padding-bottom: 12px; }\n.example .example-ja { margin-bottom: 0; }\n.example .audio.example-audio { margin: 0; }\n\n/* --- Kanji breakdown (always open, matches .example card, blue accent) --- */\n.kanji-breakdown {\n  margin: 14px 0 8px;\n  padding: 14px 16px 12px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #1fa77c;\n}\n.kanji-breakdown .kb-content {\n  font-size: 15px;\n  line-height: 1.9;\n  color: #444;\n}\n\n/* ===== DARK MODE: Anki .nightMode class ===== */\n.nightMode .card,\n.nightMode.card {\n  background: #1e1e1e;\n  color: #e0e0e0;\n}\n.nightMode .front-word { color: #f0f0f0; }\n.nightMode .front-english { color: #f0f0f0; }\n.nightMode .reading { color: #f0826e; }\n.nightMode .meaning { color: #6cb4ee; }\n.nightMode .pos-tag { background-color: #3a3f4b; color: #ccc; }\n.nightMode .example { background: #2a2a2a; border-left-color: #f0826e; }\n.nightMode .example-ja { color: #ddd; }\n.nightMode .example-ja ruby rt { color: #aaa; }\n.nightMode .example-en { color: #b0b0b0; }\n.nightMode .divider { border-top-color: #3a3a3a; }\n.nightMode .hint { color: #777; }\n.nightMode .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n.nightMode .kanji-breakdown .kb-content { color: #bbb; }\n\n/* ===== DARK MODE: prefers-color-scheme ===== */\n@media (prefers-color-scheme: dark) {\n  .card { background: #1e1e1e; color: #e0e0e0; }\n  .front-word { color: #f0f0f0; }\n  .front-english { color: #f0f0f0; }\n  .reading { color: #f0826e; }\n  .meaning { color: #6cb4ee; }\n  .pos-tag { background-color: #3a3f4b; color: #ccc; }\n  .example { background: #2a2a2a; border-left-color: #f0826e; }\n  .example-ja { color: #ddd; }\n  .example-ja ruby rt { color: #aaa; }\n  .example-en { color: #b0b0b0; }\n  .divider { border-top-color: #3a3a3a; }\n  .hint { color: #777; }\n  .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n  .kanji-breakdown .kb-content { color: #bbb; }\n}\n\n\n/* --- Audio replay button (matches kanji-breakdown pill) --- */\n.audio.player {\n  margin-top: 14px;\n}\n\n.replay-button {\n  display: flex;\n  justify-content: center;\n  align-items: center; \n  margin: 12px auto;\n  padding: 8px 18px;\n  min-width: 44px;\n  min-height: 44px;\n  box-sizing: border-box;\n  background: #F0F8EA;\n  border: 1px solid #C2E9C3;\n  border-radius: 8px;\n  color: #3E8C40;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n  transition: background 0.15s;\n  text-decoration: none;\n  line-height: 1;\n  text-align: center;\n}\n.replay-button svg {\n  width: 20px;\n  height: 20px;\n  vertical-align: middle;\n  fill: currentColor;\n}\n.replay-button svg circle {\n  fill: none;\n  stroke: none;\n}\n.replay-button svg path {\n  fill: currentColor;\n  stroke: none;\n}\n.replay-button:hover { background: #F0F8EA; }\n.replay-button:active { background: #C2E1C8; }\n\n.nightMode .replay-button {\n  background: #2B3A2A;\n  border-color: #3A503D;\n  color: #73EA8B;\n}\n.nightMode .replay-button:hover { background: #2B3A2A; }\n.nightMode .replay-button:active { background: #273827; }\n\n@media (prefers-color-scheme: dark) {\n  .replay-button {\n    background: #334633;\n    border-color: #3A503D;\n    color: #73EA8B;\n  }\n  .replay-button:hover { background: #2B3A2A; }\n  .replay-button:active { background: #334633; }\n}\n\n\n/* --- Example sentence: tap the Japanese text to play the sentence audio --- */\n.example .example-ja.tap-play-ex {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.example .example-ja.tap-play-ex:active { opacity: 0.55; }\n\n/* --- Word audio: hidden auto-generated button; tap the reading to replay --- */\n.word-audio-hidden { display: none; }\n.reading.tap-play {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.reading.tap-play:active { opacity: 0.55; }\n\n\n/* --- kanji breakdown (k-brk) --- */\n.k-brk { padding: 0; margin: 0; font-family: -apple-system, \"Hiragino Sans\", sans-serif; }\n.k-brk + .k-brk { border-top: 1px solid rgba(128,128,128,0.13); margin-top: 14px; padding-top: 14px; }\n.k-brk .k-mean { font-weight: 500; margin-bottom: 8px; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; }\n.k-brk .k-head .k-char { margin-right: 0; }\n.k-brk .k-stats { display: flex; gap: 18px; align-items: flex-start; margin-left: auto; }\n.k-brk .k-stat { display: flex; flex-direction: column; align-items: center; line-height: 1.25; }\n.k-brk .k-stat-v { font-weight: 700; font-size: 1em; color: #222; line-height: 1.2; height: 1.2em; display: block; }\n.k-brk .k-stat-l { margin-top: 3px; line-height: 1; font-size: 0.48em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.nightMode .k-brk .k-stat-v { color: #ddd; }\n.k-brk .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-meta { font-size: 0.9em; color: #888; }\n.k-brk .k-radical, .k-brk .k-components, .k-brk .k-mean { font-size: 0.95em; margin-top: 3px; }\n.nightMode .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); } .k-brk .k-meta { color: #aaa; } .k-brk .k-stat-v { color: #ddd; } }\n\n/* --- kanji breakdown enhancements (readings) --- */\n.k-brk { line-height: 1.7; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; margin-bottom: 6px; line-height: 1.1; }\n.k-brk .k-head .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-head .k-meta { font-size: 0.9em; color: #888; vertical-align: middle; }\n.k-brk .k-mean, .k-brk .k-reading, .k-brk .k-radical, .k-brk .k-components { margin-top: 1px; line-height: 1.45; }\n.k-brk .k-reading { font-size: 0.95em; }\n.k-brk .k-label { display: inline-block; min-width: 2.6em; color: #666; font-weight: 600; font-size: 0.85em; margin-right: 4px; letter-spacing: 0.02em; }\n.nightMode .k-brk .k-head .k-meta { color: #aaa; }\n.nightMode .k-brk .k-label { color: #bbb; }\n@media (prefers-color-scheme: dark) {\n  .k-brk .k-head .k-meta { color: #aaa; }\n  .k-brk .k-label { color: #bbb; }\n}\n\n/* --- compact kanji entries: no components line, On/Kun readings inline --- */\n.k-brk .k-components { display: none; }\n.k-brk .k-reading { display: inline; word-break: keep-all; }\n.k-brk .k-reading + .k-reading { margin-left: 14px; }\n.k-brk .k-reading .k-label { min-width: 0; }\n.k-brk .k-reading + .k-radical { margin-top: 3px; }\n.k-brk .k-reading .k-r { white-space: nowrap; }\n\n/* --- tight vertical rhythm for kanji entries --- */\n.k-brk { line-height: 1.45; }\n.k-brk .k-head { margin-bottom: 4px; }\n.k-brk .k-mean { margin-bottom: 2px; }\n.k-brk .k-reading + .k-radical { margin-top: 1px; }\n.k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kanji-breakdown .kb-content { line-height: 1.5; }\n\n/* --- Nihongo deep-link styling (assertive) --- */\n.k-brk a, .k-brk .k-link { color: #1f665b !important; text-decoration: underline dotted !important; text-underline-offset: 2px; text-decoration-thickness: 1.5px; padding-bottom: 1px; }\n.k-brk .k-head a, .k-brk .k-head .k-link { text-decoration: none !important; padding-bottom: 0; }\n.k-brk .k-head .k-char { color: inherit; }\n.k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #222 !important; border-bottom: 2px dotted #1f665b !important; padding-bottom: 2px; }\n.k-brk a:active, .k-brk .k-link:active { background: rgba(31, 102, 91, 0.15); }\n.k-brk .k-head a:active .k-char, .k-brk .k-head .k-link:active .k-char { background: rgba(31, 102, 91, 0.15); }\n.nightMode .k-brk a, .nightMode .k-brk .k-link { color: #63c2b1 !important; }\n.nightMode .k-brk .k-head a .k-char, .nightMode .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n@media (prefers-color-scheme: dark) {\n  .k-brk a, .k-brk .k-link { color: #63c2b1 !important; }\n  .k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n}\n\n/* --- POS pill tap target (wraps .pos-tag in Nihongo word link) --- */\n.pos-tag-link { text-decoration: none; color: inherit; display: inline-block; }\n.pos-tag-link:active .pos-tag { opacity: 0.7; }\n\n/* === v2: stroke-order layout (Sep 2026) === */\n/* --- word block: furigana over the word, meaning below; whole block taps to play word audio --- */\n.word-block { position: relative; z-index: 1; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.word-block:active { opacity: 0.55; }\n/* the back word keeps the front word's exact box (margin 24px/16px, line-height 1.6) so it does not move on flip;\n   furigana hangs above the glyphs out of flow, in the leading + top margin */\n.front-word-ruby { position: relative; margin: 24px 0 -10px; line-height: 1.6; }\n.front-word-ruby .fw-base, .front-word-ruby .fk { position: relative; display: inline-block; line-height: 1; }\n.front-word-ruby .fw-read, .front-word-ruby .fr { position: absolute; left: 50%; bottom: 100%; transform: translateX(-50%); margin-bottom: 3px; font-size: 0.4em; font-weight: 500; color: #d63964; line-height: 1.2; letter-spacing: 0.02em; white-space: nowrap; }\n.word-block .meaning { margin-bottom: 0; }\n.word-block .meaning { margin-top: 4px; }\n.card.prod .front-english { margin-bottom: 0; }\n.card.prod .front-word-ruby { margin-top: 14px; }\n\n/* --- word info: part of speech + Nihongo word link; fades up behind the meaning --- */\n.wordinfo { position: relative; margin: -48px 0 0; padding: 62px 16px 10px; background: linear-gradient(to bottom, rgba(245,245,245,0) 0%, #f5f5f5 70%); border-radius: 10px; text-align: left; display: flex; align-items: center; justify-content: space-between; gap: 12px; overflow: hidden; }\n.card.prod .wordinfo { margin-top: -30px; padding-top: 44px; }\n.wordinfo-pos { font-size: 14px; font-weight: 600; color: #8c8c8c; letter-spacing: 0.01em; }\n.card a.wordinfo-nih { font-weight: 800; font-size: 20px; line-height: 1; color: #8c8c8c; text-decoration: none; padding: 0 0 2px; border-bottom: 2px dotted #8c8c8c; flex: none; -webkit-tap-highlight-color: transparent; }\n.card a.wordinfo-nih:active { background: rgba(0,0,0,0.08); }\n\n/* --- example card: the whole card taps to play the sentence --- */\n.example { margin-top: 12px; }\n.kanji-breakdown { margin-top: 12px; }\n.example.tap-play-ex { cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.example.tap-play-ex:active { opacity: 0.55; }\n.example .audio.example-audio { display: none; margin: 0; }\n\n/* --- example list (.ex-v2 is added by the template script): one .ex-item per sentence, split like the kanji entries.\n   The card itself has no padding - each item carries it, so the whole row (edge to edge) is the tap target --- */\n.example.ex-v2 { padding: 0; overflow: hidden; }\n.ex-v2 .ex-item { position: relative; padding: 10px 16px 12px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.ex-v2 .ex-item + .ex-item::before { content: \"\"; position: absolute; top: 0; left: 16px; right: 16px; border-top: 1px solid rgba(128,128,128,0.13); }\n.ex-v2 .ex-item:active { opacity: 0.55; }\n.ex-v2 .ex-item audio { display: none; }\n/* no-JS fallback: the separator stored in the fields still reads as a rule */\n.example hr.ex-sep { border: none; border-top: 1px solid rgba(128,128,128,0.13); margin: 8px 0; }\n.nightMode .ex-v2 .ex-item + .ex-item::before, .nightMode .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .ex-v2 .ex-item + .ex-item::before, .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); } }\n\n/* --- kanji entries (re-laid out by the template script; .kb-v2 is added once that has run) --- */\n.kb-v2 .k-brk { line-height: 1.45; }\n.kb-v2 .k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kb-v2 .k-head2 { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 5px; }\n.kb-v2 .k-readings { flex: 1 1 auto; min-width: 0; display: block; font-size: 0.95em; line-height: 1.4; }\n.kb-v2 .k-reading2 { display: flex; align-items: baseline; gap: 6px; color: #222; font-size: 1.02em; line-height: 1.5; }\n.kb-v2 .k-lab { flex: none; min-width: 2.4em; font-size: 0.68em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.kb-v2 .k-vals { color: #222; }\n.kb-v2 .k-r { white-space: nowrap; }\n.kb-v2 .k-mean2 { font-weight: 500; font-size: 1em; color: #222; line-height: 1.35; margin: 0; }\n.kb-v2 .k-stats2 { float: right; display: flex; flex-direction: column; align-items: flex-end; gap: 7px; margin-left: 12px; min-width: 2.2em; }\n.kb-v2 .k-sv { font-weight: 700; font-size: 0.8em; color: #8c8c8c; line-height: 1; letter-spacing: 0.02em; white-space: nowrap; }\n.kb-v2 .k-unit { font-size: 0.9em; font-weight: 600; margin-left: 1px; }\n.kb-v2 .k-brk a.k-nih { font-weight: 800; font-size: 1.35em; line-height: 1; color: #1f665b !important; text-decoration: none !important; padding: 0 0 2px; margin: -2px 0 2px; border-bottom: 2px dotted #1f665b; -webkit-tap-highlight-color: transparent; }\n.kb-v2 .k-brk a.k-nih:active { background: rgba(31,102,91,0.15); }\n\n/* --- on/kun readings tap to play their clip (class added by the template script); dotted underline = tappable --- */\n.kb-v2 .k-r.k-r-tap { cursor: pointer; text-decoration: underline dotted #a9a9a9; text-decoration-thickness: 1.5px; text-underline-offset: 4px; padding: 5px 2px; margin: 0 -2px; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.kb-v2 .k-r.k-r-tap:active { opacity: 0.55; }\n.kb-v2 .k-r.k-r-tap.playing { color: #1f665b; text-decoration-color: #1f665b; }\n.nightMode .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; }\n.nightMode .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; }\n@media (prefers-color-scheme: dark) { .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; } .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; } }\n\n/* --- every tap target: no double-tap zoom / 300 ms click delay on iOS --- */\n.word-block, .ex-v2 .ex-item, .kb-v2 .k-box, .kb-v2 .k-r.k-r-tap, .kb-v2 .k-head2, .card a.wordinfo-nih, .kb-v2 .k-brk a.k-nih { touch-action: manipulation; }\n\n/* --- the kanji grid box --- */\n.kb-v2 .k-box { position: relative; flex: none; width: 66px; height: 66px; box-sizing: border-box; border: 1.5px dotted #d2d2d2; border-radius: 4px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; --k-ink: #1f1f1f; --k-ghost: #bdbdbd; --k-grid: #c4c4c4; --k-dot: #49c248; }\n.kb-v2 .k-box:active { background: rgba(31,102,91,0.06); }\n.kb-v2 .k-fallback { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 40px; line-height: 1; color: #1f1f1f; }\n.kb-v2 .k-box.has-svg .k-fallback { display: none; }\n.kb-v2 .k-svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }\n.kb-v2 .k-grid line { stroke: var(--k-grid); stroke-width: 1.2; stroke-dasharray: 2 3; vector-effect: non-scaling-stroke; }\n.kb-v2 .k-ghost path { fill: none; stroke: var(--k-ghost); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; opacity: 0; transition: opacity 0.15s; }\n.kb-v2 .k-box.animating .k-ghost path { opacity: 1; }\n.kb-v2 .k-ink path { fill: none; stroke: var(--k-ink); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; }\n.kb-v2 .k-dot { fill: var(--k-dot); opacity: 0; transition: opacity 0.25s; }\n.kb-v2 .k-box.animating .k-dot, .kb-v2 .k-box.done .k-dot { opacity: 1; }\n.kb-v2 .k-play { position: absolute; right: -8px; bottom: -8px; width: 18px; height: 18px; border-radius: 50%; background: #efefef; color: #5a5a5a; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 0 2px #f5f5f5; cursor: pointer; z-index: 1; }\n.kb-v2 .k-play svg { width: 12px; height: 12px; margin-left: 2px; }\n.kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #dcdcdc; }\n.kb-v2 .k-box.animating .k-play { opacity: 0.55; }\n\n/* --- tap guard, answer side only (templates/tap_guard.js): taps on the card never reach AnkiMobile's tap zones.\n   The shield is a transparent full-screen layer behind the card, so the empty space around a short card is covered too --- */\n.tap-shield { position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 0; background: transparent; -webkit-tap-highlight-color: transparent; }\n.card[data-notap] { position: relative; z-index: 1; -webkit-tap-highlight-color: transparent; }\n\n/* --- narrow screens (iPhone): trim the side margins; wider screens keep max-width 600 + 20px padding --- */\n@media (max-width: 480px) {\n  body { margin-left: 0; margin-right: 0; }\n  .card { padding: 14px 12px 24px; }\n}\n\n/* dark (Anki .nightMode) */\n.nightMode .front-word-ruby .fw-read, .nightMode .front-word-ruby .fr { color: #f0826e; }\n.nightMode .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n.nightMode .wordinfo-pos { color: #8f8f8f; }\n.nightMode .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n.nightMode .kb-v2 .k-reading2, .nightMode .kb-v2 .k-vals { color: #e6e6e6; }\n.nightMode .kb-v2 .k-lab { color: #8a8a8a; }\n.nightMode .kb-v2 .k-mean2 { color: #e6e6e6; }\n.nightMode .kb-v2 .k-sv { color: #8f8f8f; }\n.nightMode .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n.nightMode .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n.nightMode .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n.nightMode .kb-v2 .k-fallback { color: #f2f2f2; }\n.nightMode .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n.nightMode .kb-v2 .k-box:active .k-play, .nightMode .kb-v2 .k-play:active { background: #4a4a4a; }\n\n/* dark (system) */\n@media (prefers-color-scheme: dark) {\n  .front-word-ruby .fw-read, .front-word-ruby .fr { color: #f0826e; }\n  .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n  .wordinfo-pos { color: #8f8f8f; }\n  .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n  .kb-v2 .k-reading2, .kb-v2 .k-vals { color: #e6e6e6; }\n  .kb-v2 .k-lab { color: #8a8a8a; }\n  .kb-v2 .k-mean2 { color: #e6e6e6; }\n  .kb-v2 .k-sv { color: #8f8f8f; }\n  .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n  .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n  .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n  .kb-v2 .k-fallback { color: #f2f2f2; }\n  .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n  .kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #4a4a4a; }\n}\n\n/* Answer-only compact reveal. Fronts and unillustrated cards keep their layout. */\n/* Anki can paint inserted HTML before evaluating its template scripts.\n   Suppress that intermediate layout, but automatically show it after 700ms\n   even if scripts fail. Never depend on JavaScript to make a card readable. */\n.card[data-notap]:has(.vocab-visual):not(.visual-ready) {\n  animation: visual-prepare-fallback 700ms step-end both;\n}\n@keyframes visual-prepare-fallback { from { opacity: 0; } to { opacity: 1; } }\n.vocab-visual { margin: 0; text-align: center; }\n.card.has-vocab-visual > .vocab-visual {\n  margin: -24px 0 0;\n  /* Reserve the final banner height; animate the artwork, not a clipping mask. */\n  overflow: visible;\n}\n.vocab-visual img {\n  display: block;\n  width: 100%;\n  max-width: 480px;\n  height: auto;\n  aspect-ratio: 3 / 1;\n  object-fit: contain;\n  box-sizing: border-box;\n  padding: 4% 6%;\n  margin: 0 auto;\n  border-radius: 0;\n  transform-origin: center center;\n\n}\n.card.visual-ready .vocab-visual img {\n  animation: visual-entrance 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.has-vocab-visual .front-word-ruby {\n  font-size: 32px;\n  line-height: 1.35;\n  /* Furigana occupies the gap; image padding already supplies breathing room. */\n  margin: 14px 0 0;\n  text-align: center;\n  transform-origin: center center;\n\n}\n.card.has-vocab-visual .meaning { font-size: 18px; line-height: 1.35; margin: 2px 0 0; }\n/* Keep the shared light/dark gradient behind the compact meaning and POS. */\n.card.has-vocab-visual .wordinfo { margin: -32px 0 0; padding: 38px 16px 10px; }\n.card.has-vocab-visual.prod .front-english { font-size: 22px; line-height: 1.3; margin: 6px 0 0; }\n.card.has-vocab-visual.prod .front-word-ruby { margin-top: 16px; }\n.card.has-vocab-visual .example { margin-top: 6px; }\n/* One moving answer block preserves every internal spacing relationship. */\n.visual-content { display: flow-root; }\n.card.visual-ready .visual-content {\n  animation: visual-content-slide 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready:not(.prod) .front-word-ruby {\n  animation: visual-word 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready .meaning,\n.card.visual-ready .wordinfo,\n.card.visual-ready .example,\n.card.visual-ready .kanji-breakdown,\n.card.visual-ready .fw-read,\n.card.visual-ready .fr {\n  animation: visual-details 400ms ease-out 100ms both;\n}\n.card.visual-ready.prod .front-english {\n  animation: visual-english 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n@keyframes visual-english { from { font-size: 34px; line-height: 1.6; color: var(--visual-cue-start, #111); } to { font-size: 22px; line-height: 1.3; color: var(--visual-cue-end, #8c8c8c); } }\n@keyframes visual-details { from { opacity: 0; } to { opacity: 1; } }\n@keyframes visual-content-slide {\n  from { transform: translateY(var(--visual-content-start, -100px)); }\n  to { transform: translateY(0); }\n}\n@keyframes visual-entrance {\n  from { opacity: 0; transform: translateY(-100%) scale(.94); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n@keyframes visual-word { from { transform: scale(1.4375); } to { transform: scale(1); } }\n@media (max-width: 480px) {\n  .card.has-vocab-visual > .vocab-visual { margin: -14px 0 0; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .card.has-vocab-visual > .vocab-visual,\n  .card.has-vocab-visual .vocab-visual img,\n  .card.visual-ready .visual-content,\n  .card.has-vocab-visual .fr,\n  .card.has-vocab-visual .fw-read,\n  .card.visual-ready:not(.prod) .front-word-ruby,\n  .card.visual-ready.prod .front-english,\n  .card.has-vocab-visual .meaning,\n  .card.has-vocab-visual .wordinfo,\n  .card.has-vocab-visual .example,\n  .card.has-vocab-visual .kanji-breakdown,\n  .card.has-vocab-visual.prod .front-english { animation: none; }\n}\n\n/* De-emphasize the English cue only after revealing a Production answer. */\n.card.prod:has(.wordinfo) .front-english { color: #8c8c8c; }\n.nightMode .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n}\n\n/* Carry the question color through the shrink instead of swapping it on reveal. */\n.nightMode .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n}\n.card.visual-ready.prod .word-block { animation: visual-details 400ms ease-out 100ms both; }\n@media (prefers-reduced-motion: reduce) {\n  .card.visual-ready.prod .word-block { animation: none; }\n}\n\nhtml,body{margin:0;padding:0;background:transparent}.card{padding-top:0;padding-bottom:16px;display:flow-root}.tap-shield{display:none}.word-block{cursor:pointer}\n</style></head><body><script src=\"_kanji_strokes.js\"></script>\n<div class=\"tap-shield tappable\" onclick=\"void 0\"></div>\n<div class=\"card tappable has-vocab-visual\" data-notap onclick=\"void 0\">\n<div class=\"word-block tap-play\" onclick=\"event.stopPropagation();var b=this.parentNode.querySelector('.word-audio-hidden a');if(b)b.click();\">\n<div class=\"front-word front-word-ruby\"><span class=\"fw-base\">財布</span><span class=\"fw-read\">さいふ</span></div>\n<div class=\"meaning\">wallet</div>\n</div>\n<div class=\"word-audio-hidden\"><a href=\"#\" onclick=\"event.preventDefault();this.nextElementSibling.currentTime=0;this.nextElementSibling.play()\">Play</a><audio src=\"n5_wd_2fb44a8342b35048.mp3\"></audio></div>\n<div class=\"wordinfo\">\n<div class=\"wordinfo-pos\">Noun</div>\n<a class=\"wordinfo-nih\" href=\"https://nihongo-app.com/dictionary/word/財布\">語</a>\n</div>\n<div class=\"example tap-play-ex\" onclick=\"event.stopPropagation();var a=this.querySelector('audio');if(a){a.currentTime=0;a.play();}\">\n<div class=\"example-ja\"><ruby>財布<rt>さいふ</rt></ruby>を <ruby>忘<rt>わす</rt></ruby>れました。<hr class=\"ex-sep\"><ruby>誕生日<rt>たんじょうび</rt></ruby>に <ruby>父<rt>ちち</rt></ruby>から <ruby>財布<rt>さいふ</rt></ruby>をもらいました。</div>\n<div class=\"example-en\">I forgot my wallet.<hr class=\"ex-sep\">I got a wallet from my father for my birthday.</div>\n<div class=\"audio example-audio\"><audio src=\"n5_ex_ee773c6e29ca07f4.mp3\" preload=\"none\"></audio><audio src=\"n5_ex_6b5dcec49e0e8117.mp3\" preload=\"none\"></audio></div>\n</div>\n\n<div class=\"kanji-breakdown\">\n<div class=\"kb-content\"><div class=\"k-brk\">\n  <div class=\"k-head\"><a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji/財\"><span class=\"k-char\">財</span></a><span class=\"k-stats\"><span class=\"k-stat\"><span class=\"k-stat-v\">10</span><span class=\"k-stat-l\">Strokes</span></span><span class=\"k-stat\"><span class=\"k-stat-v\">N2</span><span class=\"k-stat-l\">JLPT</span></span></span></div>\n  <div class=\"k-mean\">property, money, wealth</div>\n  <div class=\"k-reading\"><span class=\"k-label\">On:</span> <span class=\"k-r\">ザイ</span>, <span class=\"k-r\">サイ</span>, <span class=\"k-r\">ゾク</span></div>\n  <div class=\"k-reading\"><span class=\"k-label\">Kun:</span> <span class=\"k-r\">たから</span></div>\n  <div class=\"k-radical\"><span class=\"k-label\">Radical:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/貝\">貝</a> (kai, shell)</div>\n  <div class=\"k-components\"><span class=\"k-label\">Components:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/一\">一</a> one, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/貝\">貝</a> shellfish, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/目\">目</a> eye, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/亅\">亅</a> feathered stick</div>\n</div>\n<div class=\"k-brk\">\n  <div class=\"k-head\"><a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji/布\"><span class=\"k-char\">布</span></a><span class=\"k-stats\"><span class=\"k-stat\"><span class=\"k-stat-v\">5</span><span class=\"k-stat-l\">Strokes</span></span><span class=\"k-stat\"><span class=\"k-stat-v\">N2</span><span class=\"k-stat-l\">JLPT</span></span></span></div>\n  <div class=\"k-mean\">linen, cloth, spread</div>\n  <div class=\"k-reading\"><span class=\"k-label\">On:</span> <span class=\"k-r\">フ</span>, <span class=\"k-r\">ホ</span></div>\n  <div class=\"k-reading\"><span class=\"k-label\">Kun:</span> <span class=\"k-r\">ぬの</span>, <span class=\"k-r\">し(く)</span>, <span class=\"k-r\">きれ</span></div>\n  <div class=\"k-radical\"><span class=\"k-label\">Radical:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/巾\">巾</a> (haba, turban)</div>\n  <div class=\"k-components\"><span class=\"k-label\">Components:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/一\">一</a> one, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/巾\">巾</a> towel</div>\n</div></div>\n</div>\n\n<span class=\"visual-key\" hidden>財布|さいふ</span>\n<span class=\"dictionary-key\" hidden>財布|さいふ|wallet</span>\n<script>\n(function(){\n  var NS = 'http://www.w3.org/2000/svg';\n  var KANJI_RE = /[㐀-鿿豈-﫿々]/;\n  function el(tag, attrs){ var e = document.createElementNS(NS, tag); for (var k in attrs) e.setAttribute(k, attrs[k]); return e; }\n  function txt(n){ return n ? (n.textContent || '').replace(/\\s+/g, ' ').trim() : ''; }\n  function stop(e){ e.stopPropagation(); }\n  function guard(node){ node.addEventListener('click', stop, false); node.addEventListener('touchend', stop, false); }\n  /* run fn on a tap. iOS drops the click after a touch that stops a momentum scroll or that it takes for a double-tap,\n     so on touch devices we act on touchend of an unmoved touch and suppress the synthetic click; mouse/desktop use click */\n  function tap(node, fn){\n    var sx = 0, sy = 0, moved = true, handled = false;\n    node.addEventListener('touchstart', function(e){ var t = e.touches[0]; if (!t || e.touches.length > 1) { moved = true; return; } sx = t.clientX; sy = t.clientY; moved = false; handled = false; }, {passive: true});\n    node.addEventListener('touchmove', function(e){ var t = e.touches[0]; if (!t || Math.abs(t.clientX - sx) > 12 || Math.abs(t.clientY - sy) > 12) moved = true; }, {passive: true});\n    node.addEventListener('touchend', function(e){ if (moved) return; moved = true; handled = true; if (e.cancelable) e.preventDefault(); fn(); }, {passive: false});\n    node.addEventListener('touchcancel', function(){ moved = true; }, {passive: true});\n    node.addEventListener('click', function(){ if (handled) { handled = false; return; } fn(); }, false);\n  }\n  // scope everything to the card this script lives in (falls back to the last card on the page)\n  var root = null, cs = document.currentScript;\n  if (cs && cs.closest) root = cs.closest('.card');\n  if (!root) { var cards = document.querySelectorAll('.card'); root = cards.length ? cards[cards.length - 1] : document; }\n\n  /* ---- align a kana reading to the kanji runs of a word: お願いします + おねがいします -> お<ruby>願<rt>ねが</rt></ruby>います ---- */\n  function toHira(s){ return s.replace(/[ァ-ヶ]/g, function(c){ return String.fromCharCode(c.charCodeAt(0) - 0x60); }); }\n  function isKanji(c){ return KANJI_RE.test(c); }\n  function isKana(c){ return /[ぁ-ゟ゠-ヿ]/.test(c); }\n  function esc(s){ return s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&'); }\n  function alignFurigana(word, reading){\n    reading = (reading || '').replace(/\\s+/g, '');\n    if (word.indexOf('(') < 0) reading = reading.replace(/[（(][^)）]*[)）]/g, '');\n    if (word.indexOf('/') < 0 && reading.indexOf('/') >= 0) reading = reading.split('/')[0];\n    var hira = toHira(reading);\n    // split the word into runs: kanji / kana / other\n    var runs = [], i, c, t, cur = null;\n    for (i = 0; i < word.length; i++) {\n      c = word.charAt(i); t = isKanji(c) ? 'k' : (isKana(c) ? 'a' : 'o');\n      if (c === '々' && cur && cur.t === 'k') t = 'k';\n      if (cur && cur.t === t) cur.s += c; else { cur = {t:t, s:c}; runs.push(cur); }\n    }\n    var kanjiRuns = 0; for (i = 0; i < runs.length; i++) if (runs[i].t === 'k') kanjiRuns++;\n    if (!kanjiRuns) return null;\n    var pat = '^';\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') pat += '(.+?)';\n      else if (runs[i].t === 'a') pat += esc(toHira(runs[i].s));\n      else pat += '(?:' + esc(runs[i].s) + ')?';\n    }\n    pat += '$';\n    var m = hira.match(new RegExp(pat));\n    if (!m) return null;\n    var out = [], gi = 1, pos = 0;\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') {\n        // take the kana slice from the original reading (keeps katakana if it was katakana)\n        var idx = hira.indexOf(m[gi], pos); if (idx < 0) return null;\n        out.push({kanji: runs[i].s, kana: reading.substr(idx, m[gi].length)});\n        pos = idx + m[gi].length; gi++;\n      } else { out.push({text: runs[i].s}); if (runs[i].t === 'a') pos += runs[i].s.length; }\n    }\n    return out;\n  }\n  function fk(kanji, kana){\n    var s = document.createElement('span'); s.className = 'fk'; s.appendChild(document.createTextNode(kanji));\n    var r = document.createElement('span'); r.className = 'fr'; r.textContent = kana; s.appendChild(r);\n    return s;\n  }\n  function renderFurigana(container, word, reading){\n    var parts = alignFurigana(word, reading);\n    if (!parts) return false;\n    while (container.firstChild) container.removeChild(container.firstChild);\n    for (var i = 0; i < parts.length; i++) {\n      if (parts[i].kanji) container.appendChild(fk(parts[i].kanji, parts[i].kana));\n      else container.appendChild(document.createTextNode(parts[i].text));\n    }\n    return true;\n  }\n  function renderWhole(container, word, reading){\n    while (container.firstChild) container.removeChild(container.firstChild);\n    if (reading) container.appendChild(fk(word, reading)); else container.appendChild(document.createTextNode(word));\n  }\n\n  /* ---- 1. furigana over the word: only over the kanji, hung above the glyphs so the word sits exactly where it does on the front ---- */\n  var fw = root.querySelector('.front-word-ruby');\n  if (fw) {\n    var baseEl = fw.querySelector('.fw-base'), readEl = fw.querySelector('.fw-read');\n    var base = txt(baseEl), reading = txt(readEl);\n    if (!KANJI_RE.test(base) || reading === base || !reading) renderWhole(fw, base, '');\n    else if (!renderFurigana(fw, base, reading)) renderWhole(fw, base, reading);\n  }\n\n  /* ---- 2. audio tap targets must never reach the card's tap gestures ---- */\n  var taps = root.querySelectorAll('.tap-play, .tap-play-ex, .wordinfo-nih');\n  for (var i = 0; i < taps.length; i++) guard(taps[i]);\n\n  /* ---- 2b. example sentences: the fields may hold two sentences separated by <hr class=\"ex-sep\">.\n     Re-lay them out as list items (.ex-item = Japanese + English + its own clip); the WHOLE item,\n     padding included, is the tap target, and nothing inside the red card ever reaches Anki's tap gestures ---- */\n  var ex = root.querySelector('.example');\n  if (ex && !ex.classList.contains('ex-v2')) {\n    var splitAtHr = function(node){\n      var groups = [[]]; if (!node) return groups;\n      var n = node.firstChild;\n      while (n) { var nx = n.nextSibling; if (n.nodeType === 1 && n.tagName === 'HR') groups.push([]); else groups[groups.length - 1].push(n); n = nx; }\n      return groups;\n    };\n    var jaG = splitAtHr(ex.querySelector('.example-ja')), enG = splitAtHr(ex.querySelector('.example-en'));\n    var auds = ex.querySelectorAll('audio'), items = [], g, k;\n    for (g = 0; g < jaG.length; g++) {\n      var item = document.createElement('div'); item.className = 'ex-item'; item.setAttribute('role', 'button');\n      var ja = document.createElement('div'); ja.className = 'example-ja';\n      for (k = 0; k < jaG[g].length; k++) ja.appendChild(jaG[g][k]);\n      item.appendChild(ja);\n      if (enG[g]) { var en = document.createElement('div'); en.className = 'example-en'; for (k = 0; k < enG[g].length; k++) en.appendChild(enG[g][k]); item.appendChild(en); }\n      if (auds[g]) item.appendChild(auds[g]);\n      items.push(item);\n    }\n    while (ex.firstChild) ex.removeChild(ex.firstChild);\n    ex.removeAttribute('onclick'); ex.onclick = null;\n    ex.classList.remove('tap-play-ex'); ex.classList.add('ex-v2');\n    var playItem = function(item){\n      var all = ex.querySelectorAll('audio'), mine = item.querySelector('audio');\n      for (var a = 0; a < all.length; a++) if (all[a] !== mine) { try { all[a].pause(); all[a].currentTime = 0; } catch (e) {} }\n      if (mine) { try { mine.currentTime = 0; } catch (e) {} var pr = mine.play(); if (pr && pr.catch) pr.catch(function(){}); }\n    };\n    for (g = 0; g < items.length; g++) {\n      ex.appendChild(items[g]); guard(items[g]);\n      (function(it){ tap(it, function(){ playItem(it); }); })(items[g]);\n    }\n  }\n\n  /* ---- 3. re-lay out each kanji breakdown entry (field markup stays unchanged) ---- */\n  var kb = root.querySelector('.kanji-breakdown');\n  if (kb && !kb.classList.contains('kb-v2')) {\n    var brks = kb.querySelectorAll('.k-brk');\n    for (var b = 0; b < brks.length; b++) relayout(brks[b]);\n    kb.classList.add('kb-v2');\n\n    /* ---- 3b. tappable on/kun readings: each .k-r plays `_kr_<hex of the hiragana reading>.mp3`\n       (a _-prefixed template media file; okurigana marks, dots and hyphens are dropped, katakana -> hiragana).\n       The whole head row swallows taps so a near miss never flips the card. ---- */\n    var krAudio = null;\n    var krFile = function(t){\n      var sp = toHira(t.replace(/[-.()（）\\s‐－]/g, '')), hex = '';\n      if (!sp || !/^[ぁ-ゖー]+$/.test(sp)) return null;\n      for (var i = 0; i < sp.length; i++) hex += ('0000' + sp.charCodeAt(i).toString(16)).slice(-4);\n      return '_kr_' + hex + '.mp3';\n    };\n    var playKr = function(node, file){\n      if (!krAudio) { krAudio = document.createElement('audio'); krAudio.setAttribute('preload', 'none'); krAudio.style.display = 'none'; root.appendChild(krAudio); }\n      var others = root.querySelectorAll('.example audio');\n      for (var o = 0; o < others.length; o++) { try { others[o].pause(); } catch (e) {} }\n      var on = kb.querySelectorAll('.k-r.playing'); for (var q = 0; q < on.length; q++) on[q].classList.remove('playing');\n      node.classList.add('playing'); setTimeout(function(){ node.classList.remove('playing'); }, 700);\n      try { krAudio.pause(); krAudio.src = file; krAudio.currentTime = 0; } catch (e) {}\n      var pr = krAudio.play(); if (pr && pr.catch) pr.catch(function(){});\n    };\n    var krs = kb.querySelectorAll('.k-r');\n    for (var r2 = 0; r2 < krs.length; r2++) (function(node){\n      var file = krFile(txt(node)); if (!file) return;\n      node.classList.add('k-r-tap'); node.setAttribute('role', 'button');\n      guard(node); tap(node, function(){ playKr(node, file); });\n    })(krs[r2]);\n    var heads = kb.querySelectorAll('.k-head2'); for (var h2 = 0; h2 < heads.length; h2++) guard(heads[h2]);\n  }\n\n  function relayout(brk){\n    var ch = txt(brk.querySelector('.k-char'));\n    if (!ch) return;\n    var link = brk.querySelector('.k-head a');\n    var href = (link && link.getAttribute('href')) || ('https://nihongo-app.com/dictionary/kanji/' + ch);\n    var strokes = '', jlpt = '';\n    var stats = brk.querySelectorAll('.k-stat');\n    for (var s = 0; s < stats.length; s++) {\n      var lab = txt(stats[s].querySelector('.k-stat-l')).toLowerCase(), v = txt(stats[s].querySelector('.k-stat-v'));\n      if (lab.indexOf('stroke') === 0) strokes = v; else if (lab.indexOf('jlpt') === 0) jlpt = v;\n    }\n    var meanText = txt(brk.querySelector('.k-mean'));\n    var readings = brk.querySelectorAll('.k-reading');\n\n    var head = document.createElement('div'); head.className = 'k-head2';\n    var box = document.createElement('div'); box.className = 'k-box'; box.setAttribute('data-kanji', ch); box.setAttribute('role', 'button');\n    var fb = document.createElement('span'); fb.className = 'k-fallback'; fb.textContent = ch; box.appendChild(fb);\n    var play = document.createElement('span'); play.className = 'k-play';\n    play.innerHTML = '<svg viewBox=\"0 0 12 12\"><path d=\"M3.6 2.2 L10 6 L3.6 9.8 Z\" fill=\"currentColor\"/></svg>';\n    box.appendChild(play);\n    head.appendChild(box);\n\n    var col = document.createElement('div'); col.className = 'k-readings';\n    var st = document.createElement('span'); st.className = 'k-stats2';\n    var nih = document.createElement('a'); nih.className = 'k-nih'; nih.href = href; nih.textContent = '語'; st.appendChild(nih);\n    if (strokes) { var sv = document.createElement('span'); sv.className = 'k-sv'; sv.innerHTML = strokes + '<span class=\"k-unit\">画</span>'; st.appendChild(sv); }\n    if (jlpt) { var jv = document.createElement('span'); jv.className = 'k-sv'; jv.textContent = jlpt; st.appendChild(jv); }\n    col.appendChild(st);\n    for (var r = 0; r < readings.length; r++) {\n      var src = readings[r], label = src.querySelector('.k-label');\n      var row = document.createElement('div'); row.className = 'k-reading2';\n      var lab2 = document.createElement('span'); lab2.className = 'k-lab'; lab2.textContent = txt(label).replace(/:$/, ''); row.appendChild(lab2);\n      var vals = document.createElement('span'); vals.className = 'k-vals';\n      var n = src.firstChild;\n      while (n) { var next = n.nextSibling; if (n !== label) vals.appendChild(n); n = next; }\n      row.appendChild(vals); col.appendChild(row);\n    }\n    head.appendChild(col);\n\n    var mean = document.createElement('div'); mean.className = 'k-mean2'; mean.textContent = meanText;\n\n    while (brk.firstChild) brk.removeChild(brk.firstChild);\n    brk.appendChild(head); brk.appendChild(mean);\n    guard(box); guard(nih);\n    tap(box, function(){ animate(box); });\n  }\n\n  /* ---- 4. stroke-order boxes (KanjiVG paths from _kanji_strokes.js) ---- */\n  function buildBox(box){\n    var strokes = window.KANJI_STROKES[box.getAttribute('data-kanji')];\n    if (!strokes || !strokes.length) return;\n    var svg = el('svg', {viewBox:'-7 -7 123 123', 'class':'k-svg', 'aria-hidden':'true'});\n    var grid = el('g', {'class':'k-grid'});\n    grid.appendChild(el('line', {x1:54.5, y1:-5, x2:54.5, y2:114}));\n    grid.appendChild(el('line', {x1:-5, y1:54.5, x2:114, y2:54.5}));\n    svg.appendChild(grid);\n    var ghost = el('g', {'class':'k-ghost'}), ink = el('g', {'class':'k-ink'}), paths = [];\n    for (var i = 0; i < strokes.length; i++) {\n      ghost.appendChild(el('path', {d:strokes[i]}));\n      var p = el('path', {d:strokes[i]}); ink.appendChild(p); paths.push(p);\n    }\n    svg.appendChild(ghost); svg.appendChild(ink);\n    var dot = el('circle', {'class':'k-dot', r:5.2, cx:-20, cy:-20});\n    svg.appendChild(dot);\n    box.insertBefore(svg, box.firstChild);\n    box.classList.add('has-svg');\n    box._k = {paths:paths, dot:dot, raf:0, timer:0};\n  }\n  function cancel(box){\n    var s = box._k; if (!s) return;\n    if (s.raf) cancelAnimationFrame(s.raf); s.raf = 0;\n    if (s.timer) clearTimeout(s.timer); s.timer = 0;\n    box.classList.remove('animating'); box.classList.remove('done');\n  }\n  function animate(box){\n    if (!box._k && window.KANJI_STROKES) buildBox(box);   // asset arrived after this box was laid out\n    var s = box._k; if (!s) return;\n    cancel(box);\n    var lens = [], i, p;\n    for (i = 0; i < s.paths.length; i++) { lens.push(s.paths[i].getTotalLength()); }\n    for (i = 0; i < s.paths.length; i++) { p = s.paths[i]; p.style.strokeDasharray = lens[i] + ' ' + lens[i]; p.style.strokeDashoffset = lens[i]; }\n    box.classList.add('animating');\n    var idx = 0, t0 = 0, GAP = 70;\n    function dur(len){ return Math.max(170, 90 + len * 4.6); }\n    function ease(t){ return 1 - Math.pow(1 - t, 1.5); }\n    function step(ts){\n      if (!t0) t0 = ts;\n      var q = s.paths[idx], len = lens[idx], t = Math.min(1, (ts - t0) / dur(len)), e = ease(t);\n      q.style.strokeDashoffset = len * (1 - e);\n      var pt = q.getPointAtLength(len * e);\n      s.dot.setAttribute('cx', pt.x); s.dot.setAttribute('cy', pt.y);\n      if (t < 1) { s.raf = requestAnimationFrame(step); return; }\n      idx++; t0 = 0;\n      if (idx < s.paths.length) {\n        s.timer = setTimeout(function(){ s.timer = 0; s.raf = requestAnimationFrame(step); }, GAP);\n      } else {\n        box.classList.remove('animating'); box.classList.add('done');\n        s.timer = setTimeout(function(){ s.timer = 0; box.classList.remove('done'); }, 650);\n      }\n    }\n    var p0 = s.paths[0].getPointAtLength(0); s.dot.setAttribute('cx', p0.x); s.dot.setAttribute('cy', p0.y);\n    s.raf = requestAnimationFrame(step);\n  }\n  var tries = 0;\n  function fill(){\n    if (window.KANJI_STROKES) {\n      var boxes = root.querySelectorAll('.k-box:not(.has-svg)');\n      for (var i = 0; i < boxes.length; i++) buildBox(boxes[i]);\n    } else if (tries++ < 150) { setTimeout(fill, tries < 20 ? 50 : 200); }   // external asset may still be loading (waits up to ~27 s)\n  }\n  fill();\n  // if the asset script is still in flight, fill as soon as it lands (covers WebViews that load it asynchronously)\n  var ks = document.querySelectorAll('script[src*=\"_kanji_strokes\"]');\n  for (var si = 0; si < ks.length; si++) ks[si].addEventListener('load', fill, false);\n})();\n\n</script>\n<script>\n\n</script>\n</div>\n</body></html>"}, {"word": "傘", "reading": "かさ", "image": "media/vocab-aa9951036541.webp", "audio": "media/n5_wd_1a11e425423d0929.mp3", "doc": "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><base href=\"media/\"><style>/* ===== BASE / LIGHT MODE ===== */\n.card {\n  font-family: 'SF Pro Display', 'SF Pro Text', -apple-system, BlinkMacSystemFont,\n               'Hiragino Sans', 'Hiragino Kaku Gothic ProN', system-ui, sans-serif;\n  text-align: center;\n  padding: 24px 20px;\n  line-height: 1.6;\n  background: #ffffff;\n  color: #1a1a1a;\n  max-width: 600px;\n  margin: 0 auto;\n}\n.front-word {\n  font-size: 46px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n  letter-spacing: 0.02em;\n}\n.front-english {\n  font-size: 34px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n}\n.reading {\n  font-size: 26px;\n  color: #d63964;\n  margin: 8px 0;\n  font-weight: 500;\n}\n.meaning {\n  font-size: 22px;\n  color: #1a5276;\n  margin: 8px 0;\n  font-weight: 600;\n}\n.pos-tag {\n  display: inline-block;\n  background-color: #2c3e50;\n  color: #fff;\n  padding: 4px 14px;\n  border-radius: 14px;\n  font-size: 13px;\n  margin: 6px 0;\n  letter-spacing: 0.03em;\n}\n.example {\n  margin: 18px 0 8px;\n  padding: 14px 16px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #d63964;\n}\n.example-ja {\n  font-size: 19px;\n  color: #222;\n  margin-bottom: 6px;\n  line-height: 1.7;\n}\n.example-ja ruby rt {\n  line-height: 1;\n  font-size: 0.55em;\n  color: #888;\n  font-weight: 400;\n}\n.example-en {\n  font-size: 15px;\n  color: #555;\n  font-style: italic;\n  line-height: 1.45;\n}\n.divider {\n  border: none;\n  border-top: 1px solid #e0e0e0;\n  margin: 16px 0;\n}\n.hint {\n  font-size: 14px;\n  color: #999;\n  margin-top: 12px;\n  letter-spacing: 0.02em;\n}\n.audio {\n  margin: 8px 0;\n}\n\n/* --- Example card: even out top/bottom (furigana rides in the 1.7 line-height leading; hidden <audio> wrapper added 8px) --- */\n.example { padding-top: 10px; padding-bottom: 12px; }\n.example .example-ja { margin-bottom: 0; }\n.example .audio.example-audio { margin: 0; }\n\n/* --- Kanji breakdown (always open, matches .example card, blue accent) --- */\n.kanji-breakdown {\n  margin: 14px 0 8px;\n  padding: 14px 16px 12px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #1fa77c;\n}\n.kanji-breakdown .kb-content {\n  font-size: 15px;\n  line-height: 1.9;\n  color: #444;\n}\n\n/* ===== DARK MODE: Anki .nightMode class ===== */\n.nightMode .card,\n.nightMode.card {\n  background: #1e1e1e;\n  color: #e0e0e0;\n}\n.nightMode .front-word { color: #f0f0f0; }\n.nightMode .front-english { color: #f0f0f0; }\n.nightMode .reading { color: #f0826e; }\n.nightMode .meaning { color: #6cb4ee; }\n.nightMode .pos-tag { background-color: #3a3f4b; color: #ccc; }\n.nightMode .example { background: #2a2a2a; border-left-color: #f0826e; }\n.nightMode .example-ja { color: #ddd; }\n.nightMode .example-ja ruby rt { color: #aaa; }\n.nightMode .example-en { color: #b0b0b0; }\n.nightMode .divider { border-top-color: #3a3a3a; }\n.nightMode .hint { color: #777; }\n.nightMode .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n.nightMode .kanji-breakdown .kb-content { color: #bbb; }\n\n/* ===== DARK MODE: prefers-color-scheme ===== */\n@media (prefers-color-scheme: dark) {\n  .card { background: #1e1e1e; color: #e0e0e0; }\n  .front-word { color: #f0f0f0; }\n  .front-english { color: #f0f0f0; }\n  .reading { color: #f0826e; }\n  .meaning { color: #6cb4ee; }\n  .pos-tag { background-color: #3a3f4b; color: #ccc; }\n  .example { background: #2a2a2a; border-left-color: #f0826e; }\n  .example-ja { color: #ddd; }\n  .example-ja ruby rt { color: #aaa; }\n  .example-en { color: #b0b0b0; }\n  .divider { border-top-color: #3a3a3a; }\n  .hint { color: #777; }\n  .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n  .kanji-breakdown .kb-content { color: #bbb; }\n}\n\n\n/* --- Audio replay button (matches kanji-breakdown pill) --- */\n.audio.player {\n  margin-top: 14px;\n}\n\n.replay-button {\n  display: flex;\n  justify-content: center;\n  align-items: center; \n  margin: 12px auto;\n  padding: 8px 18px;\n  min-width: 44px;\n  min-height: 44px;\n  box-sizing: border-box;\n  background: #F0F8EA;\n  border: 1px solid #C2E9C3;\n  border-radius: 8px;\n  color: #3E8C40;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n  transition: background 0.15s;\n  text-decoration: none;\n  line-height: 1;\n  text-align: center;\n}\n.replay-button svg {\n  width: 20px;\n  height: 20px;\n  vertical-align: middle;\n  fill: currentColor;\n}\n.replay-button svg circle {\n  fill: none;\n  stroke: none;\n}\n.replay-button svg path {\n  fill: currentColor;\n  stroke: none;\n}\n.replay-button:hover { background: #F0F8EA; }\n.replay-button:active { background: #C2E1C8; }\n\n.nightMode .replay-button {\n  background: #2B3A2A;\n  border-color: #3A503D;\n  color: #73EA8B;\n}\n.nightMode .replay-button:hover { background: #2B3A2A; }\n.nightMode .replay-button:active { background: #273827; }\n\n@media (prefers-color-scheme: dark) {\n  .replay-button {\n    background: #334633;\n    border-color: #3A503D;\n    color: #73EA8B;\n  }\n  .replay-button:hover { background: #2B3A2A; }\n  .replay-button:active { background: #334633; }\n}\n\n\n/* --- Example sentence: tap the Japanese text to play the sentence audio --- */\n.example .example-ja.tap-play-ex {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.example .example-ja.tap-play-ex:active { opacity: 0.55; }\n\n/* --- Word audio: hidden auto-generated button; tap the reading to replay --- */\n.word-audio-hidden { display: none; }\n.reading.tap-play {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.reading.tap-play:active { opacity: 0.55; }\n\n\n/* --- kanji breakdown (k-brk) --- */\n.k-brk { padding: 0; margin: 0; font-family: -apple-system, \"Hiragino Sans\", sans-serif; }\n.k-brk + .k-brk { border-top: 1px solid rgba(128,128,128,0.13); margin-top: 14px; padding-top: 14px; }\n.k-brk .k-mean { font-weight: 500; margin-bottom: 8px; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; }\n.k-brk .k-head .k-char { margin-right: 0; }\n.k-brk .k-stats { display: flex; gap: 18px; align-items: flex-start; margin-left: auto; }\n.k-brk .k-stat { display: flex; flex-direction: column; align-items: center; line-height: 1.25; }\n.k-brk .k-stat-v { font-weight: 700; font-size: 1em; color: #222; line-height: 1.2; height: 1.2em; display: block; }\n.k-brk .k-stat-l { margin-top: 3px; line-height: 1; font-size: 0.48em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.nightMode .k-brk .k-stat-v { color: #ddd; }\n.k-brk .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-meta { font-size: 0.9em; color: #888; }\n.k-brk .k-radical, .k-brk .k-components, .k-brk .k-mean { font-size: 0.95em; margin-top: 3px; }\n.nightMode .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); } .k-brk .k-meta { color: #aaa; } .k-brk .k-stat-v { color: #ddd; } }\n\n/* --- kanji breakdown enhancements (readings) --- */\n.k-brk { line-height: 1.7; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; margin-bottom: 6px; line-height: 1.1; }\n.k-brk .k-head .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-head .k-meta { font-size: 0.9em; color: #888; vertical-align: middle; }\n.k-brk .k-mean, .k-brk .k-reading, .k-brk .k-radical, .k-brk .k-components { margin-top: 1px; line-height: 1.45; }\n.k-brk .k-reading { font-size: 0.95em; }\n.k-brk .k-label { display: inline-block; min-width: 2.6em; color: #666; font-weight: 600; font-size: 0.85em; margin-right: 4px; letter-spacing: 0.02em; }\n.nightMode .k-brk .k-head .k-meta { color: #aaa; }\n.nightMode .k-brk .k-label { color: #bbb; }\n@media (prefers-color-scheme: dark) {\n  .k-brk .k-head .k-meta { color: #aaa; }\n  .k-brk .k-label { color: #bbb; }\n}\n\n/* --- compact kanji entries: no components line, On/Kun readings inline --- */\n.k-brk .k-components { display: none; }\n.k-brk .k-reading { display: inline; word-break: keep-all; }\n.k-brk .k-reading + .k-reading { margin-left: 14px; }\n.k-brk .k-reading .k-label { min-width: 0; }\n.k-brk .k-reading + .k-radical { margin-top: 3px; }\n.k-brk .k-reading .k-r { white-space: nowrap; }\n\n/* --- tight vertical rhythm for kanji entries --- */\n.k-brk { line-height: 1.45; }\n.k-brk .k-head { margin-bottom: 4px; }\n.k-brk .k-mean { margin-bottom: 2px; }\n.k-brk .k-reading + .k-radical { margin-top: 1px; }\n.k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kanji-breakdown .kb-content { line-height: 1.5; }\n\n/* --- Nihongo deep-link styling (assertive) --- */\n.k-brk a, .k-brk .k-link { color: #1f665b !important; text-decoration: underline dotted !important; text-underline-offset: 2px; text-decoration-thickness: 1.5px; padding-bottom: 1px; }\n.k-brk .k-head a, .k-brk .k-head .k-link { text-decoration: none !important; padding-bottom: 0; }\n.k-brk .k-head .k-char { color: inherit; }\n.k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #222 !important; border-bottom: 2px dotted #1f665b !important; padding-bottom: 2px; }\n.k-brk a:active, .k-brk .k-link:active { background: rgba(31, 102, 91, 0.15); }\n.k-brk .k-head a:active .k-char, .k-brk .k-head .k-link:active .k-char { background: rgba(31, 102, 91, 0.15); }\n.nightMode .k-brk a, .nightMode .k-brk .k-link { color: #63c2b1 !important; }\n.nightMode .k-brk .k-head a .k-char, .nightMode .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n@media (prefers-color-scheme: dark) {\n  .k-brk a, .k-brk .k-link { color: #63c2b1 !important; }\n  .k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n}\n\n/* --- POS pill tap target (wraps .pos-tag in Nihongo word link) --- */\n.pos-tag-link { text-decoration: none; color: inherit; display: inline-block; }\n.pos-tag-link:active .pos-tag { opacity: 0.7; }\n\n/* === v2: stroke-order layout (Sep 2026) === */\n/* --- word block: furigana over the word, meaning below; whole block taps to play word audio --- */\n.word-block { position: relative; z-index: 1; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.word-block:active { opacity: 0.55; }\n/* the back word keeps the front word's exact box (margin 24px/16px, line-height 1.6) so it does not move on flip;\n   furigana hangs above the glyphs out of flow, in the leading + top margin */\n.front-word-ruby { position: relative; margin: 24px 0 -10px; line-height: 1.6; }\n.front-word-ruby .fw-base, .front-word-ruby .fk { position: relative; display: inline-block; line-height: 1; }\n.front-word-ruby .fw-read, .front-word-ruby .fr { position: absolute; left: 50%; bottom: 100%; transform: translateX(-50%); margin-bottom: 3px; font-size: 0.4em; font-weight: 500; color: #d63964; line-height: 1.2; letter-spacing: 0.02em; white-space: nowrap; }\n.word-block .meaning { margin-bottom: 0; }\n.word-block .meaning { margin-top: 4px; }\n.card.prod .front-english { margin-bottom: 0; }\n.card.prod .front-word-ruby { margin-top: 14px; }\n\n/* --- word info: part of speech + Nihongo word link; fades up behind the meaning --- */\n.wordinfo { position: relative; margin: -48px 0 0; padding: 62px 16px 10px; background: linear-gradient(to bottom, rgba(245,245,245,0) 0%, #f5f5f5 70%); border-radius: 10px; text-align: left; display: flex; align-items: center; justify-content: space-between; gap: 12px; overflow: hidden; }\n.card.prod .wordinfo { margin-top: -30px; padding-top: 44px; }\n.wordinfo-pos { font-size: 14px; font-weight: 600; color: #8c8c8c; letter-spacing: 0.01em; }\n.card a.wordinfo-nih { font-weight: 800; font-size: 20px; line-height: 1; color: #8c8c8c; text-decoration: none; padding: 0 0 2px; border-bottom: 2px dotted #8c8c8c; flex: none; -webkit-tap-highlight-color: transparent; }\n.card a.wordinfo-nih:active { background: rgba(0,0,0,0.08); }\n\n/* --- example card: the whole card taps to play the sentence --- */\n.example { margin-top: 12px; }\n.kanji-breakdown { margin-top: 12px; }\n.example.tap-play-ex { cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.example.tap-play-ex:active { opacity: 0.55; }\n.example .audio.example-audio { display: none; margin: 0; }\n\n/* --- example list (.ex-v2 is added by the template script): one .ex-item per sentence, split like the kanji entries.\n   The card itself has no padding - each item carries it, so the whole row (edge to edge) is the tap target --- */\n.example.ex-v2 { padding: 0; overflow: hidden; }\n.ex-v2 .ex-item { position: relative; padding: 10px 16px 12px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.ex-v2 .ex-item + .ex-item::before { content: \"\"; position: absolute; top: 0; left: 16px; right: 16px; border-top: 1px solid rgba(128,128,128,0.13); }\n.ex-v2 .ex-item:active { opacity: 0.55; }\n.ex-v2 .ex-item audio { display: none; }\n/* no-JS fallback: the separator stored in the fields still reads as a rule */\n.example hr.ex-sep { border: none; border-top: 1px solid rgba(128,128,128,0.13); margin: 8px 0; }\n.nightMode .ex-v2 .ex-item + .ex-item::before, .nightMode .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .ex-v2 .ex-item + .ex-item::before, .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); } }\n\n/* --- kanji entries (re-laid out by the template script; .kb-v2 is added once that has run) --- */\n.kb-v2 .k-brk { line-height: 1.45; }\n.kb-v2 .k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kb-v2 .k-head2 { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 5px; }\n.kb-v2 .k-readings { flex: 1 1 auto; min-width: 0; display: block; font-size: 0.95em; line-height: 1.4; }\n.kb-v2 .k-reading2 { display: flex; align-items: baseline; gap: 6px; color: #222; font-size: 1.02em; line-height: 1.5; }\n.kb-v2 .k-lab { flex: none; min-width: 2.4em; font-size: 0.68em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.kb-v2 .k-vals { color: #222; }\n.kb-v2 .k-r { white-space: nowrap; }\n.kb-v2 .k-mean2 { font-weight: 500; font-size: 1em; color: #222; line-height: 1.35; margin: 0; }\n.kb-v2 .k-stats2 { float: right; display: flex; flex-direction: column; align-items: flex-end; gap: 7px; margin-left: 12px; min-width: 2.2em; }\n.kb-v2 .k-sv { font-weight: 700; font-size: 0.8em; color: #8c8c8c; line-height: 1; letter-spacing: 0.02em; white-space: nowrap; }\n.kb-v2 .k-unit { font-size: 0.9em; font-weight: 600; margin-left: 1px; }\n.kb-v2 .k-brk a.k-nih { font-weight: 800; font-size: 1.35em; line-height: 1; color: #1f665b !important; text-decoration: none !important; padding: 0 0 2px; margin: -2px 0 2px; border-bottom: 2px dotted #1f665b; -webkit-tap-highlight-color: transparent; }\n.kb-v2 .k-brk a.k-nih:active { background: rgba(31,102,91,0.15); }\n\n/* --- on/kun readings tap to play their clip (class added by the template script); dotted underline = tappable --- */\n.kb-v2 .k-r.k-r-tap { cursor: pointer; text-decoration: underline dotted #a9a9a9; text-decoration-thickness: 1.5px; text-underline-offset: 4px; padding: 5px 2px; margin: 0 -2px; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.kb-v2 .k-r.k-r-tap:active { opacity: 0.55; }\n.kb-v2 .k-r.k-r-tap.playing { color: #1f665b; text-decoration-color: #1f665b; }\n.nightMode .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; }\n.nightMode .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; }\n@media (prefers-color-scheme: dark) { .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; } .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; } }\n\n/* --- every tap target: no double-tap zoom / 300 ms click delay on iOS --- */\n.word-block, .ex-v2 .ex-item, .kb-v2 .k-box, .kb-v2 .k-r.k-r-tap, .kb-v2 .k-head2, .card a.wordinfo-nih, .kb-v2 .k-brk a.k-nih { touch-action: manipulation; }\n\n/* --- the kanji grid box --- */\n.kb-v2 .k-box { position: relative; flex: none; width: 66px; height: 66px; box-sizing: border-box; border: 1.5px dotted #d2d2d2; border-radius: 4px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; --k-ink: #1f1f1f; --k-ghost: #bdbdbd; --k-grid: #c4c4c4; --k-dot: #49c248; }\n.kb-v2 .k-box:active { background: rgba(31,102,91,0.06); }\n.kb-v2 .k-fallback { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 40px; line-height: 1; color: #1f1f1f; }\n.kb-v2 .k-box.has-svg .k-fallback { display: none; }\n.kb-v2 .k-svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }\n.kb-v2 .k-grid line { stroke: var(--k-grid); stroke-width: 1.2; stroke-dasharray: 2 3; vector-effect: non-scaling-stroke; }\n.kb-v2 .k-ghost path { fill: none; stroke: var(--k-ghost); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; opacity: 0; transition: opacity 0.15s; }\n.kb-v2 .k-box.animating .k-ghost path { opacity: 1; }\n.kb-v2 .k-ink path { fill: none; stroke: var(--k-ink); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; }\n.kb-v2 .k-dot { fill: var(--k-dot); opacity: 0; transition: opacity 0.25s; }\n.kb-v2 .k-box.animating .k-dot, .kb-v2 .k-box.done .k-dot { opacity: 1; }\n.kb-v2 .k-play { position: absolute; right: -8px; bottom: -8px; width: 18px; height: 18px; border-radius: 50%; background: #efefef; color: #5a5a5a; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 0 2px #f5f5f5; cursor: pointer; z-index: 1; }\n.kb-v2 .k-play svg { width: 12px; height: 12px; margin-left: 2px; }\n.kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #dcdcdc; }\n.kb-v2 .k-box.animating .k-play { opacity: 0.55; }\n\n/* --- tap guard, answer side only (templates/tap_guard.js): taps on the card never reach AnkiMobile's tap zones.\n   The shield is a transparent full-screen layer behind the card, so the empty space around a short card is covered too --- */\n.tap-shield { position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 0; background: transparent; -webkit-tap-highlight-color: transparent; }\n.card[data-notap] { position: relative; z-index: 1; -webkit-tap-highlight-color: transparent; }\n\n/* --- narrow screens (iPhone): trim the side margins; wider screens keep max-width 600 + 20px padding --- */\n@media (max-width: 480px) {\n  body { margin-left: 0; margin-right: 0; }\n  .card { padding: 14px 12px 24px; }\n}\n\n/* dark (Anki .nightMode) */\n.nightMode .front-word-ruby .fw-read, .nightMode .front-word-ruby .fr { color: #f0826e; }\n.nightMode .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n.nightMode .wordinfo-pos { color: #8f8f8f; }\n.nightMode .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n.nightMode .kb-v2 .k-reading2, .nightMode .kb-v2 .k-vals { color: #e6e6e6; }\n.nightMode .kb-v2 .k-lab { color: #8a8a8a; }\n.nightMode .kb-v2 .k-mean2 { color: #e6e6e6; }\n.nightMode .kb-v2 .k-sv { color: #8f8f8f; }\n.nightMode .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n.nightMode .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n.nightMode .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n.nightMode .kb-v2 .k-fallback { color: #f2f2f2; }\n.nightMode .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n.nightMode .kb-v2 .k-box:active .k-play, .nightMode .kb-v2 .k-play:active { background: #4a4a4a; }\n\n/* dark (system) */\n@media (prefers-color-scheme: dark) {\n  .front-word-ruby .fw-read, .front-word-ruby .fr { color: #f0826e; }\n  .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n  .wordinfo-pos { color: #8f8f8f; }\n  .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n  .kb-v2 .k-reading2, .kb-v2 .k-vals { color: #e6e6e6; }\n  .kb-v2 .k-lab { color: #8a8a8a; }\n  .kb-v2 .k-mean2 { color: #e6e6e6; }\n  .kb-v2 .k-sv { color: #8f8f8f; }\n  .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n  .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n  .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n  .kb-v2 .k-fallback { color: #f2f2f2; }\n  .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n  .kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #4a4a4a; }\n}\n\n/* Answer-only compact reveal. Fronts and unillustrated cards keep their layout. */\n/* Anki can paint inserted HTML before evaluating its template scripts.\n   Suppress that intermediate layout, but automatically show it after 700ms\n   even if scripts fail. Never depend on JavaScript to make a card readable. */\n.card[data-notap]:has(.vocab-visual):not(.visual-ready) {\n  animation: visual-prepare-fallback 700ms step-end both;\n}\n@keyframes visual-prepare-fallback { from { opacity: 0; } to { opacity: 1; } }\n.vocab-visual { margin: 0; text-align: center; }\n.card.has-vocab-visual > .vocab-visual {\n  margin: -24px 0 0;\n  /* Reserve the final banner height; animate the artwork, not a clipping mask. */\n  overflow: visible;\n}\n.vocab-visual img {\n  display: block;\n  width: 100%;\n  max-width: 480px;\n  height: auto;\n  aspect-ratio: 3 / 1;\n  object-fit: contain;\n  box-sizing: border-box;\n  padding: 4% 6%;\n  margin: 0 auto;\n  border-radius: 0;\n  transform-origin: center center;\n\n}\n.card.visual-ready .vocab-visual img {\n  animation: visual-entrance 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.has-vocab-visual .front-word-ruby {\n  font-size: 32px;\n  line-height: 1.35;\n  /* Furigana occupies the gap; image padding already supplies breathing room. */\n  margin: 14px 0 0;\n  text-align: center;\n  transform-origin: center center;\n\n}\n.card.has-vocab-visual .meaning { font-size: 18px; line-height: 1.35; margin: 2px 0 0; }\n/* Keep the shared light/dark gradient behind the compact meaning and POS. */\n.card.has-vocab-visual .wordinfo { margin: -32px 0 0; padding: 38px 16px 10px; }\n.card.has-vocab-visual.prod .front-english { font-size: 22px; line-height: 1.3; margin: 6px 0 0; }\n.card.has-vocab-visual.prod .front-word-ruby { margin-top: 16px; }\n.card.has-vocab-visual .example { margin-top: 6px; }\n/* One moving answer block preserves every internal spacing relationship. */\n.visual-content { display: flow-root; }\n.card.visual-ready .visual-content {\n  animation: visual-content-slide 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready:not(.prod) .front-word-ruby {\n  animation: visual-word 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready .meaning,\n.card.visual-ready .wordinfo,\n.card.visual-ready .example,\n.card.visual-ready .kanji-breakdown,\n.card.visual-ready .fw-read,\n.card.visual-ready .fr {\n  animation: visual-details 400ms ease-out 100ms both;\n}\n.card.visual-ready.prod .front-english {\n  animation: visual-english 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n@keyframes visual-english { from { font-size: 34px; line-height: 1.6; color: var(--visual-cue-start, #111); } to { font-size: 22px; line-height: 1.3; color: var(--visual-cue-end, #8c8c8c); } }\n@keyframes visual-details { from { opacity: 0; } to { opacity: 1; } }\n@keyframes visual-content-slide {\n  from { transform: translateY(var(--visual-content-start, -100px)); }\n  to { transform: translateY(0); }\n}\n@keyframes visual-entrance {\n  from { opacity: 0; transform: translateY(-100%) scale(.94); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n@keyframes visual-word { from { transform: scale(1.4375); } to { transform: scale(1); } }\n@media (max-width: 480px) {\n  .card.has-vocab-visual > .vocab-visual { margin: -14px 0 0; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .card.has-vocab-visual > .vocab-visual,\n  .card.has-vocab-visual .vocab-visual img,\n  .card.visual-ready .visual-content,\n  .card.has-vocab-visual .fr,\n  .card.has-vocab-visual .fw-read,\n  .card.visual-ready:not(.prod) .front-word-ruby,\n  .card.visual-ready.prod .front-english,\n  .card.has-vocab-visual .meaning,\n  .card.has-vocab-visual .wordinfo,\n  .card.has-vocab-visual .example,\n  .card.has-vocab-visual .kanji-breakdown,\n  .card.has-vocab-visual.prod .front-english { animation: none; }\n}\n\n/* De-emphasize the English cue only after revealing a Production answer. */\n.card.prod:has(.wordinfo) .front-english { color: #8c8c8c; }\n.nightMode .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n}\n\n/* Carry the question color through the shrink instead of swapping it on reveal. */\n.nightMode .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n}\n.card.visual-ready.prod .word-block { animation: visual-details 400ms ease-out 100ms both; }\n@media (prefers-reduced-motion: reduce) {\n  .card.visual-ready.prod .word-block { animation: none; }\n}\n\nhtml,body{margin:0;padding:0;background:transparent}.card{padding-top:0;padding-bottom:16px;display:flow-root}.tap-shield{display:none}.word-block{cursor:pointer}\n</style></head><body><script src=\"_kanji_strokes.js\"></script>\n<div class=\"tap-shield tappable\" onclick=\"void 0\"></div>\n<div class=\"card tappable has-vocab-visual\" data-notap onclick=\"void 0\">\n<div class=\"word-block tap-play\" onclick=\"event.stopPropagation();var b=this.parentNode.querySelector('.word-audio-hidden a');if(b)b.click();\">\n<div class=\"front-word front-word-ruby\"><span class=\"fw-base\">傘</span><span class=\"fw-read\">かさ</span></div>\n<div class=\"meaning\">umbrella</div>\n</div>\n<div class=\"word-audio-hidden\"><a href=\"#\" onclick=\"event.preventDefault();this.nextElementSibling.currentTime=0;this.nextElementSibling.play()\">Play</a><audio src=\"n5_wd_1a11e425423d0929.mp3\"></audio></div>\n<div class=\"wordinfo\">\n<div class=\"wordinfo-pos\">Noun</div>\n<a class=\"wordinfo-nih\" href=\"https://nihongo-app.com/dictionary/word/傘\">語</a>\n</div>\n<div class=\"example tap-play-ex\" onclick=\"event.stopPropagation();var a=this.querySelector('audio');if(a){a.currentTime=0;a.play();}\">\n<div class=\"example-ja\"><ruby>傘<rt>かさ</rt></ruby>を <ruby>持<rt>も</rt></ruby>っていますか。<hr class=\"ex-sep\"><ruby>雨<rt>あめ</rt></ruby>が <ruby>降<rt>ふ</rt></ruby>っていますから、 <ruby>傘<rt>かさ</rt></ruby>をさしましょう。</div>\n<div class=\"example-en\">Do you have an umbrella?<hr class=\"ex-sep\">It's raining, so let's put up our umbrellas.</div>\n<div class=\"audio example-audio\"><audio src=\"n5_ex_a04fce8f8a1c34e0.mp3\" preload=\"none\"></audio><audio src=\"n5_ex_cbbbdcc1a4d38345.mp3\" preload=\"none\"></audio></div>\n</div>\n\n<div class=\"kanji-breakdown\">\n<div class=\"kb-content\"><div class=\"k-brk\">\n  <div class=\"k-head\"><a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji/傘\"><span class=\"k-char\">傘</span></a><span class=\"k-stats\"><span class=\"k-stat\"><span class=\"k-stat-v\">12</span><span class=\"k-stat-l\">Strokes</span></span><span class=\"k-stat\"><span class=\"k-stat-v\">N1</span><span class=\"k-stat-l\">JLPT</span></span></span></div>\n  <div class=\"k-mean\">umbrella</div>\n  <div class=\"k-reading\"><span class=\"k-label\">On:</span> <span class=\"k-r\">サン</span></div>\n  <div class=\"k-reading\"><span class=\"k-label\">Kun:</span> <span class=\"k-r\">かさ</span></div>\n  <div class=\"k-radical\"><span class=\"k-label\">Radical:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/人\">人</a> (hito, man)</div>\n  <div class=\"k-components\"><span class=\"k-label\">Components:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/十\">十</a> ten, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/人\">人</a> person</div>\n</div></div>\n</div>\n\n<span class=\"visual-key\" hidden>傘|かさ</span>\n<span class=\"dictionary-key\" hidden>傘|かさ|umbrella</span>\n<script>\n(function(){\n  var NS = 'http://www.w3.org/2000/svg';\n  var KANJI_RE = /[㐀-鿿豈-﫿々]/;\n  function el(tag, attrs){ var e = document.createElementNS(NS, tag); for (var k in attrs) e.setAttribute(k, attrs[k]); return e; }\n  function txt(n){ return n ? (n.textContent || '').replace(/\\s+/g, ' ').trim() : ''; }\n  function stop(e){ e.stopPropagation(); }\n  function guard(node){ node.addEventListener('click', stop, false); node.addEventListener('touchend', stop, false); }\n  /* run fn on a tap. iOS drops the click after a touch that stops a momentum scroll or that it takes for a double-tap,\n     so on touch devices we act on touchend of an unmoved touch and suppress the synthetic click; mouse/desktop use click */\n  function tap(node, fn){\n    var sx = 0, sy = 0, moved = true, handled = false;\n    node.addEventListener('touchstart', function(e){ var t = e.touches[0]; if (!t || e.touches.length > 1) { moved = true; return; } sx = t.clientX; sy = t.clientY; moved = false; handled = false; }, {passive: true});\n    node.addEventListener('touchmove', function(e){ var t = e.touches[0]; if (!t || Math.abs(t.clientX - sx) > 12 || Math.abs(t.clientY - sy) > 12) moved = true; }, {passive: true});\n    node.addEventListener('touchend', function(e){ if (moved) return; moved = true; handled = true; if (e.cancelable) e.preventDefault(); fn(); }, {passive: false});\n    node.addEventListener('touchcancel', function(){ moved = true; }, {passive: true});\n    node.addEventListener('click', function(){ if (handled) { handled = false; return; } fn(); }, false);\n  }\n  // scope everything to the card this script lives in (falls back to the last card on the page)\n  var root = null, cs = document.currentScript;\n  if (cs && cs.closest) root = cs.closest('.card');\n  if (!root) { var cards = document.querySelectorAll('.card'); root = cards.length ? cards[cards.length - 1] : document; }\n\n  /* ---- align a kana reading to the kanji runs of a word: お願いします + おねがいします -> お<ruby>願<rt>ねが</rt></ruby>います ---- */\n  function toHira(s){ return s.replace(/[ァ-ヶ]/g, function(c){ return String.fromCharCode(c.charCodeAt(0) - 0x60); }); }\n  function isKanji(c){ return KANJI_RE.test(c); }\n  function isKana(c){ return /[ぁ-ゟ゠-ヿ]/.test(c); }\n  function esc(s){ return s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&'); }\n  function alignFurigana(word, reading){\n    reading = (reading || '').replace(/\\s+/g, '');\n    if (word.indexOf('(') < 0) reading = reading.replace(/[（(][^)）]*[)）]/g, '');\n    if (word.indexOf('/') < 0 && reading.indexOf('/') >= 0) reading = reading.split('/')[0];\n    var hira = toHira(reading);\n    // split the word into runs: kanji / kana / other\n    var runs = [], i, c, t, cur = null;\n    for (i = 0; i < word.length; i++) {\n      c = word.charAt(i); t = isKanji(c) ? 'k' : (isKana(c) ? 'a' : 'o');\n      if (c === '々' && cur && cur.t === 'k') t = 'k';\n      if (cur && cur.t === t) cur.s += c; else { cur = {t:t, s:c}; runs.push(cur); }\n    }\n    var kanjiRuns = 0; for (i = 0; i < runs.length; i++) if (runs[i].t === 'k') kanjiRuns++;\n    if (!kanjiRuns) return null;\n    var pat = '^';\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') pat += '(.+?)';\n      else if (runs[i].t === 'a') pat += esc(toHira(runs[i].s));\n      else pat += '(?:' + esc(runs[i].s) + ')?';\n    }\n    pat += '$';\n    var m = hira.match(new RegExp(pat));\n    if (!m) return null;\n    var out = [], gi = 1, pos = 0;\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') {\n        // take the kana slice from the original reading (keeps katakana if it was katakana)\n        var idx = hira.indexOf(m[gi], pos); if (idx < 0) return null;\n        out.push({kanji: runs[i].s, kana: reading.substr(idx, m[gi].length)});\n        pos = idx + m[gi].length; gi++;\n      } else { out.push({text: runs[i].s}); if (runs[i].t === 'a') pos += runs[i].s.length; }\n    }\n    return out;\n  }\n  function fk(kanji, kana){\n    var s = document.createElement('span'); s.className = 'fk'; s.appendChild(document.createTextNode(kanji));\n    var r = document.createElement('span'); r.className = 'fr'; r.textContent = kana; s.appendChild(r);\n    return s;\n  }\n  function renderFurigana(container, word, reading){\n    var parts = alignFurigana(word, reading);\n    if (!parts) return false;\n    while (container.firstChild) container.removeChild(container.firstChild);\n    for (var i = 0; i < parts.length; i++) {\n      if (parts[i].kanji) container.appendChild(fk(parts[i].kanji, parts[i].kana));\n      else container.appendChild(document.createTextNode(parts[i].text));\n    }\n    return true;\n  }\n  function renderWhole(container, word, reading){\n    while (container.firstChild) container.removeChild(container.firstChild);\n    if (reading) container.appendChild(fk(word, reading)); else container.appendChild(document.createTextNode(word));\n  }\n\n  /* ---- 1. furigana over the word: only over the kanji, hung above the glyphs so the word sits exactly where it does on the front ---- */\n  var fw = root.querySelector('.front-word-ruby');\n  if (fw) {\n    var baseEl = fw.querySelector('.fw-base'), readEl = fw.querySelector('.fw-read');\n    var base = txt(baseEl), reading = txt(readEl);\n    if (!KANJI_RE.test(base) || reading === base || !reading) renderWhole(fw, base, '');\n    else if (!renderFurigana(fw, base, reading)) renderWhole(fw, base, reading);\n  }\n\n  /* ---- 2. audio tap targets must never reach the card's tap gestures ---- */\n  var taps = root.querySelectorAll('.tap-play, .tap-play-ex, .wordinfo-nih');\n  for (var i = 0; i < taps.length; i++) guard(taps[i]);\n\n  /* ---- 2b. example sentences: the fields may hold two sentences separated by <hr class=\"ex-sep\">.\n     Re-lay them out as list items (.ex-item = Japanese + English + its own clip); the WHOLE item,\n     padding included, is the tap target, and nothing inside the red card ever reaches Anki's tap gestures ---- */\n  var ex = root.querySelector('.example');\n  if (ex && !ex.classList.contains('ex-v2')) {\n    var splitAtHr = function(node){\n      var groups = [[]]; if (!node) return groups;\n      var n = node.firstChild;\n      while (n) { var nx = n.nextSibling; if (n.nodeType === 1 && n.tagName === 'HR') groups.push([]); else groups[groups.length - 1].push(n); n = nx; }\n      return groups;\n    };\n    var jaG = splitAtHr(ex.querySelector('.example-ja')), enG = splitAtHr(ex.querySelector('.example-en'));\n    var auds = ex.querySelectorAll('audio'), items = [], g, k;\n    for (g = 0; g < jaG.length; g++) {\n      var item = document.createElement('div'); item.className = 'ex-item'; item.setAttribute('role', 'button');\n      var ja = document.createElement('div'); ja.className = 'example-ja';\n      for (k = 0; k < jaG[g].length; k++) ja.appendChild(jaG[g][k]);\n      item.appendChild(ja);\n      if (enG[g]) { var en = document.createElement('div'); en.className = 'example-en'; for (k = 0; k < enG[g].length; k++) en.appendChild(enG[g][k]); item.appendChild(en); }\n      if (auds[g]) item.appendChild(auds[g]);\n      items.push(item);\n    }\n    while (ex.firstChild) ex.removeChild(ex.firstChild);\n    ex.removeAttribute('onclick'); ex.onclick = null;\n    ex.classList.remove('tap-play-ex'); ex.classList.add('ex-v2');\n    var playItem = function(item){\n      var all = ex.querySelectorAll('audio'), mine = item.querySelector('audio');\n      for (var a = 0; a < all.length; a++) if (all[a] !== mine) { try { all[a].pause(); all[a].currentTime = 0; } catch (e) {} }\n      if (mine) { try { mine.currentTime = 0; } catch (e) {} var pr = mine.play(); if (pr && pr.catch) pr.catch(function(){}); }\n    };\n    for (g = 0; g < items.length; g++) {\n      ex.appendChild(items[g]); guard(items[g]);\n      (function(it){ tap(it, function(){ playItem(it); }); })(items[g]);\n    }\n  }\n\n  /* ---- 3. re-lay out each kanji breakdown entry (field markup stays unchanged) ---- */\n  var kb = root.querySelector('.kanji-breakdown');\n  if (kb && !kb.classList.contains('kb-v2')) {\n    var brks = kb.querySelectorAll('.k-brk');\n    for (var b = 0; b < brks.length; b++) relayout(brks[b]);\n    kb.classList.add('kb-v2');\n\n    /* ---- 3b. tappable on/kun readings: each .k-r plays `_kr_<hex of the hiragana reading>.mp3`\n       (a _-prefixed template media file; okurigana marks, dots and hyphens are dropped, katakana -> hiragana).\n       The whole head row swallows taps so a near miss never flips the card. ---- */\n    var krAudio = null;\n    var krFile = function(t){\n      var sp = toHira(t.replace(/[-.()（）\\s‐－]/g, '')), hex = '';\n      if (!sp || !/^[ぁ-ゖー]+$/.test(sp)) return null;\n      for (var i = 0; i < sp.length; i++) hex += ('0000' + sp.charCodeAt(i).toString(16)).slice(-4);\n      return '_kr_' + hex + '.mp3';\n    };\n    var playKr = function(node, file){\n      if (!krAudio) { krAudio = document.createElement('audio'); krAudio.setAttribute('preload', 'none'); krAudio.style.display = 'none'; root.appendChild(krAudio); }\n      var others = root.querySelectorAll('.example audio');\n      for (var o = 0; o < others.length; o++) { try { others[o].pause(); } catch (e) {} }\n      var on = kb.querySelectorAll('.k-r.playing'); for (var q = 0; q < on.length; q++) on[q].classList.remove('playing');\n      node.classList.add('playing'); setTimeout(function(){ node.classList.remove('playing'); }, 700);\n      try { krAudio.pause(); krAudio.src = file; krAudio.currentTime = 0; } catch (e) {}\n      var pr = krAudio.play(); if (pr && pr.catch) pr.catch(function(){});\n    };\n    var krs = kb.querySelectorAll('.k-r');\n    for (var r2 = 0; r2 < krs.length; r2++) (function(node){\n      var file = krFile(txt(node)); if (!file) return;\n      node.classList.add('k-r-tap'); node.setAttribute('role', 'button');\n      guard(node); tap(node, function(){ playKr(node, file); });\n    })(krs[r2]);\n    var heads = kb.querySelectorAll('.k-head2'); for (var h2 = 0; h2 < heads.length; h2++) guard(heads[h2]);\n  }\n\n  function relayout(brk){\n    var ch = txt(brk.querySelector('.k-char'));\n    if (!ch) return;\n    var link = brk.querySelector('.k-head a');\n    var href = (link && link.getAttribute('href')) || ('https://nihongo-app.com/dictionary/kanji/' + ch);\n    var strokes = '', jlpt = '';\n    var stats = brk.querySelectorAll('.k-stat');\n    for (var s = 0; s < stats.length; s++) {\n      var lab = txt(stats[s].querySelector('.k-stat-l')).toLowerCase(), v = txt(stats[s].querySelector('.k-stat-v'));\n      if (lab.indexOf('stroke') === 0) strokes = v; else if (lab.indexOf('jlpt') === 0) jlpt = v;\n    }\n    var meanText = txt(brk.querySelector('.k-mean'));\n    var readings = brk.querySelectorAll('.k-reading');\n\n    var head = document.createElement('div'); head.className = 'k-head2';\n    var box = document.createElement('div'); box.className = 'k-box'; box.setAttribute('data-kanji', ch); box.setAttribute('role', 'button');\n    var fb = document.createElement('span'); fb.className = 'k-fallback'; fb.textContent = ch; box.appendChild(fb);\n    var play = document.createElement('span'); play.className = 'k-play';\n    play.innerHTML = '<svg viewBox=\"0 0 12 12\"><path d=\"M3.6 2.2 L10 6 L3.6 9.8 Z\" fill=\"currentColor\"/></svg>';\n    box.appendChild(play);\n    head.appendChild(box);\n\n    var col = document.createElement('div'); col.className = 'k-readings';\n    var st = document.createElement('span'); st.className = 'k-stats2';\n    var nih = document.createElement('a'); nih.className = 'k-nih'; nih.href = href; nih.textContent = '語'; st.appendChild(nih);\n    if (strokes) { var sv = document.createElement('span'); sv.className = 'k-sv'; sv.innerHTML = strokes + '<span class=\"k-unit\">画</span>'; st.appendChild(sv); }\n    if (jlpt) { var jv = document.createElement('span'); jv.className = 'k-sv'; jv.textContent = jlpt; st.appendChild(jv); }\n    col.appendChild(st);\n    for (var r = 0; r < readings.length; r++) {\n      var src = readings[r], label = src.querySelector('.k-label');\n      var row = document.createElement('div'); row.className = 'k-reading2';\n      var lab2 = document.createElement('span'); lab2.className = 'k-lab'; lab2.textContent = txt(label).replace(/:$/, ''); row.appendChild(lab2);\n      var vals = document.createElement('span'); vals.className = 'k-vals';\n      var n = src.firstChild;\n      while (n) { var next = n.nextSibling; if (n !== label) vals.appendChild(n); n = next; }\n      row.appendChild(vals); col.appendChild(row);\n    }\n    head.appendChild(col);\n\n    var mean = document.createElement('div'); mean.className = 'k-mean2'; mean.textContent = meanText;\n\n    while (brk.firstChild) brk.removeChild(brk.firstChild);\n    brk.appendChild(head); brk.appendChild(mean);\n    guard(box); guard(nih);\n    tap(box, function(){ animate(box); });\n  }\n\n  /* ---- 4. stroke-order boxes (KanjiVG paths from _kanji_strokes.js) ---- */\n  function buildBox(box){\n    var strokes = window.KANJI_STROKES[box.getAttribute('data-kanji')];\n    if (!strokes || !strokes.length) return;\n    var svg = el('svg', {viewBox:'-7 -7 123 123', 'class':'k-svg', 'aria-hidden':'true'});\n    var grid = el('g', {'class':'k-grid'});\n    grid.appendChild(el('line', {x1:54.5, y1:-5, x2:54.5, y2:114}));\n    grid.appendChild(el('line', {x1:-5, y1:54.5, x2:114, y2:54.5}));\n    svg.appendChild(grid);\n    var ghost = el('g', {'class':'k-ghost'}), ink = el('g', {'class':'k-ink'}), paths = [];\n    for (var i = 0; i < strokes.length; i++) {\n      ghost.appendChild(el('path', {d:strokes[i]}));\n      var p = el('path', {d:strokes[i]}); ink.appendChild(p); paths.push(p);\n    }\n    svg.appendChild(ghost); svg.appendChild(ink);\n    var dot = el('circle', {'class':'k-dot', r:5.2, cx:-20, cy:-20});\n    svg.appendChild(dot);\n    box.insertBefore(svg, box.firstChild);\n    box.classList.add('has-svg');\n    box._k = {paths:paths, dot:dot, raf:0, timer:0};\n  }\n  function cancel(box){\n    var s = box._k; if (!s) return;\n    if (s.raf) cancelAnimationFrame(s.raf); s.raf = 0;\n    if (s.timer) clearTimeout(s.timer); s.timer = 0;\n    box.classList.remove('animating'); box.classList.remove('done');\n  }\n  function animate(box){\n    if (!box._k && window.KANJI_STROKES) buildBox(box);   // asset arrived after this box was laid out\n    var s = box._k; if (!s) return;\n    cancel(box);\n    var lens = [], i, p;\n    for (i = 0; i < s.paths.length; i++) { lens.push(s.paths[i].getTotalLength()); }\n    for (i = 0; i < s.paths.length; i++) { p = s.paths[i]; p.style.strokeDasharray = lens[i] + ' ' + lens[i]; p.style.strokeDashoffset = lens[i]; }\n    box.classList.add('animating');\n    var idx = 0, t0 = 0, GAP = 70;\n    function dur(len){ return Math.max(170, 90 + len * 4.6); }\n    function ease(t){ return 1 - Math.pow(1 - t, 1.5); }\n    function step(ts){\n      if (!t0) t0 = ts;\n      var q = s.paths[idx], len = lens[idx], t = Math.min(1, (ts - t0) / dur(len)), e = ease(t);\n      q.style.strokeDashoffset = len * (1 - e);\n      var pt = q.getPointAtLength(len * e);\n      s.dot.setAttribute('cx', pt.x); s.dot.setAttribute('cy', pt.y);\n      if (t < 1) { s.raf = requestAnimationFrame(step); return; }\n      idx++; t0 = 0;\n      if (idx < s.paths.length) {\n        s.timer = setTimeout(function(){ s.timer = 0; s.raf = requestAnimationFrame(step); }, GAP);\n      } else {\n        box.classList.remove('animating'); box.classList.add('done');\n        s.timer = setTimeout(function(){ s.timer = 0; box.classList.remove('done'); }, 650);\n      }\n    }\n    var p0 = s.paths[0].getPointAtLength(0); s.dot.setAttribute('cx', p0.x); s.dot.setAttribute('cy', p0.y);\n    s.raf = requestAnimationFrame(step);\n  }\n  var tries = 0;\n  function fill(){\n    if (window.KANJI_STROKES) {\n      var boxes = root.querySelectorAll('.k-box:not(.has-svg)');\n      for (var i = 0; i < boxes.length; i++) buildBox(boxes[i]);\n    } else if (tries++ < 150) { setTimeout(fill, tries < 20 ? 50 : 200); }   // external asset may still be loading (waits up to ~27 s)\n  }\n  fill();\n  // if the asset script is still in flight, fill as soon as it lands (covers WebViews that load it asynchronously)\n  var ks = document.querySelectorAll('script[src*=\"_kanji_strokes\"]');\n  for (var si = 0; si < ks.length; si++) ks[si].addEventListener('load', fill, false);\n})();\n\n</script>\n<script>\n\n</script>\n</div>\n</body></html>"}, {"word": "猫", "reading": "ねこ", "image": "media/vocab-fdf9d40719eb.webp", "audio": "media/n5_wd_d6c72565c05815af.mp3", "doc": "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><base href=\"media/\"><style>/* ===== BASE / LIGHT MODE ===== */\n.card {\n  font-family: 'SF Pro Display', 'SF Pro Text', -apple-system, BlinkMacSystemFont,\n               'Hiragino Sans', 'Hiragino Kaku Gothic ProN', system-ui, sans-serif;\n  text-align: center;\n  padding: 24px 20px;\n  line-height: 1.6;\n  background: #ffffff;\n  color: #1a1a1a;\n  max-width: 600px;\n  margin: 0 auto;\n}\n.front-word {\n  font-size: 46px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n  letter-spacing: 0.02em;\n}\n.front-english {\n  font-size: 34px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n}\n.reading {\n  font-size: 26px;\n  color: #d63964;\n  margin: 8px 0;\n  font-weight: 500;\n}\n.meaning {\n  font-size: 22px;\n  color: #1a5276;\n  margin: 8px 0;\n  font-weight: 600;\n}\n.pos-tag {\n  display: inline-block;\n  background-color: #2c3e50;\n  color: #fff;\n  padding: 4px 14px;\n  border-radius: 14px;\n  font-size: 13px;\n  margin: 6px 0;\n  letter-spacing: 0.03em;\n}\n.example {\n  margin: 18px 0 8px;\n  padding: 14px 16px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #d63964;\n}\n.example-ja {\n  font-size: 19px;\n  color: #222;\n  margin-bottom: 6px;\n  line-height: 1.7;\n}\n.example-ja ruby rt {\n  line-height: 1;\n  font-size: 0.55em;\n  color: #888;\n  font-weight: 400;\n}\n.example-en {\n  font-size: 15px;\n  color: #555;\n  font-style: italic;\n  line-height: 1.45;\n}\n.divider {\n  border: none;\n  border-top: 1px solid #e0e0e0;\n  margin: 16px 0;\n}\n.hint {\n  font-size: 14px;\n  color: #999;\n  margin-top: 12px;\n  letter-spacing: 0.02em;\n}\n.audio {\n  margin: 8px 0;\n}\n\n/* --- Example card: even out top/bottom (furigana rides in the 1.7 line-height leading; hidden <audio> wrapper added 8px) --- */\n.example { padding-top: 10px; padding-bottom: 12px; }\n.example .example-ja { margin-bottom: 0; }\n.example .audio.example-audio { margin: 0; }\n\n/* --- Kanji breakdown (always open, matches .example card, blue accent) --- */\n.kanji-breakdown {\n  margin: 14px 0 8px;\n  padding: 14px 16px 12px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #1fa77c;\n}\n.kanji-breakdown .kb-content {\n  font-size: 15px;\n  line-height: 1.9;\n  color: #444;\n}\n\n/* ===== DARK MODE: Anki .nightMode class ===== */\n.nightMode .card,\n.nightMode.card {\n  background: #1e1e1e;\n  color: #e0e0e0;\n}\n.nightMode .front-word { color: #f0f0f0; }\n.nightMode .front-english { color: #f0f0f0; }\n.nightMode .reading { color: #f0826e; }\n.nightMode .meaning { color: #6cb4ee; }\n.nightMode .pos-tag { background-color: #3a3f4b; color: #ccc; }\n.nightMode .example { background: #2a2a2a; border-left-color: #f0826e; }\n.nightMode .example-ja { color: #ddd; }\n.nightMode .example-ja ruby rt { color: #aaa; }\n.nightMode .example-en { color: #b0b0b0; }\n.nightMode .divider { border-top-color: #3a3a3a; }\n.nightMode .hint { color: #777; }\n.nightMode .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n.nightMode .kanji-breakdown .kb-content { color: #bbb; }\n\n/* ===== DARK MODE: prefers-color-scheme ===== */\n@media (prefers-color-scheme: dark) {\n  .card { background: #1e1e1e; color: #e0e0e0; }\n  .front-word { color: #f0f0f0; }\n  .front-english { color: #f0f0f0; }\n  .reading { color: #f0826e; }\n  .meaning { color: #6cb4ee; }\n  .pos-tag { background-color: #3a3f4b; color: #ccc; }\n  .example { background: #2a2a2a; border-left-color: #f0826e; }\n  .example-ja { color: #ddd; }\n  .example-ja ruby rt { color: #aaa; }\n  .example-en { color: #b0b0b0; }\n  .divider { border-top-color: #3a3a3a; }\n  .hint { color: #777; }\n  .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n  .kanji-breakdown .kb-content { color: #bbb; }\n}\n\n\n/* --- Audio replay button (matches kanji-breakdown pill) --- */\n.audio.player {\n  margin-top: 14px;\n}\n\n.replay-button {\n  display: flex;\n  justify-content: center;\n  align-items: center; \n  margin: 12px auto;\n  padding: 8px 18px;\n  min-width: 44px;\n  min-height: 44px;\n  box-sizing: border-box;\n  background: #F0F8EA;\n  border: 1px solid #C2E9C3;\n  border-radius: 8px;\n  color: #3E8C40;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n  transition: background 0.15s;\n  text-decoration: none;\n  line-height: 1;\n  text-align: center;\n}\n.replay-button svg {\n  width: 20px;\n  height: 20px;\n  vertical-align: middle;\n  fill: currentColor;\n}\n.replay-button svg circle {\n  fill: none;\n  stroke: none;\n}\n.replay-button svg path {\n  fill: currentColor;\n  stroke: none;\n}\n.replay-button:hover { background: #F0F8EA; }\n.replay-button:active { background: #C2E1C8; }\n\n.nightMode .replay-button {\n  background: #2B3A2A;\n  border-color: #3A503D;\n  color: #73EA8B;\n}\n.nightMode .replay-button:hover { background: #2B3A2A; }\n.nightMode .replay-button:active { background: #273827; }\n\n@media (prefers-color-scheme: dark) {\n  .replay-button {\n    background: #334633;\n    border-color: #3A503D;\n    color: #73EA8B;\n  }\n  .replay-button:hover { background: #2B3A2A; }\n  .replay-button:active { background: #334633; }\n}\n\n\n/* --- Example sentence: tap the Japanese text to play the sentence audio --- */\n.example .example-ja.tap-play-ex {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.example .example-ja.tap-play-ex:active { opacity: 0.55; }\n\n/* --- Word audio: hidden auto-generated button; tap the reading to replay --- */\n.word-audio-hidden { display: none; }\n.reading.tap-play {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.reading.tap-play:active { opacity: 0.55; }\n\n\n/* --- kanji breakdown (k-brk) --- */\n.k-brk { padding: 0; margin: 0; font-family: -apple-system, \"Hiragino Sans\", sans-serif; }\n.k-brk + .k-brk { border-top: 1px solid rgba(128,128,128,0.13); margin-top: 14px; padding-top: 14px; }\n.k-brk .k-mean { font-weight: 500; margin-bottom: 8px; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; }\n.k-brk .k-head .k-char { margin-right: 0; }\n.k-brk .k-stats { display: flex; gap: 18px; align-items: flex-start; margin-left: auto; }\n.k-brk .k-stat { display: flex; flex-direction: column; align-items: center; line-height: 1.25; }\n.k-brk .k-stat-v { font-weight: 700; font-size: 1em; color: #222; line-height: 1.2; height: 1.2em; display: block; }\n.k-brk .k-stat-l { margin-top: 3px; line-height: 1; font-size: 0.48em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.nightMode .k-brk .k-stat-v { color: #ddd; }\n.k-brk .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-meta { font-size: 0.9em; color: #888; }\n.k-brk .k-radical, .k-brk .k-components, .k-brk .k-mean { font-size: 0.95em; margin-top: 3px; }\n.nightMode .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); } .k-brk .k-meta { color: #aaa; } .k-brk .k-stat-v { color: #ddd; } }\n\n/* --- kanji breakdown enhancements (readings) --- */\n.k-brk { line-height: 1.7; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; margin-bottom: 6px; line-height: 1.1; }\n.k-brk .k-head .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-head .k-meta { font-size: 0.9em; color: #888; vertical-align: middle; }\n.k-brk .k-mean, .k-brk .k-reading, .k-brk .k-radical, .k-brk .k-components { margin-top: 1px; line-height: 1.45; }\n.k-brk .k-reading { font-size: 0.95em; }\n.k-brk .k-label { display: inline-block; min-width: 2.6em; color: #666; font-weight: 600; font-size: 0.85em; margin-right: 4px; letter-spacing: 0.02em; }\n.nightMode .k-brk .k-head .k-meta { color: #aaa; }\n.nightMode .k-brk .k-label { color: #bbb; }\n@media (prefers-color-scheme: dark) {\n  .k-brk .k-head .k-meta { color: #aaa; }\n  .k-brk .k-label { color: #bbb; }\n}\n\n/* --- compact kanji entries: no components line, On/Kun readings inline --- */\n.k-brk .k-components { display: none; }\n.k-brk .k-reading { display: inline; word-break: keep-all; }\n.k-brk .k-reading + .k-reading { margin-left: 14px; }\n.k-brk .k-reading .k-label { min-width: 0; }\n.k-brk .k-reading + .k-radical { margin-top: 3px; }\n.k-brk .k-reading .k-r { white-space: nowrap; }\n\n/* --- tight vertical rhythm for kanji entries --- */\n.k-brk { line-height: 1.45; }\n.k-brk .k-head { margin-bottom: 4px; }\n.k-brk .k-mean { margin-bottom: 2px; }\n.k-brk .k-reading + .k-radical { margin-top: 1px; }\n.k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kanji-breakdown .kb-content { line-height: 1.5; }\n\n/* --- Nihongo deep-link styling (assertive) --- */\n.k-brk a, .k-brk .k-link { color: #1f665b !important; text-decoration: underline dotted !important; text-underline-offset: 2px; text-decoration-thickness: 1.5px; padding-bottom: 1px; }\n.k-brk .k-head a, .k-brk .k-head .k-link { text-decoration: none !important; padding-bottom: 0; }\n.k-brk .k-head .k-char { color: inherit; }\n.k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #222 !important; border-bottom: 2px dotted #1f665b !important; padding-bottom: 2px; }\n.k-brk a:active, .k-brk .k-link:active { background: rgba(31, 102, 91, 0.15); }\n.k-brk .k-head a:active .k-char, .k-brk .k-head .k-link:active .k-char { background: rgba(31, 102, 91, 0.15); }\n.nightMode .k-brk a, .nightMode .k-brk .k-link { color: #63c2b1 !important; }\n.nightMode .k-brk .k-head a .k-char, .nightMode .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n@media (prefers-color-scheme: dark) {\n  .k-brk a, .k-brk .k-link { color: #63c2b1 !important; }\n  .k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n}\n\n/* --- POS pill tap target (wraps .pos-tag in Nihongo word link) --- */\n.pos-tag-link { text-decoration: none; color: inherit; display: inline-block; }\n.pos-tag-link:active .pos-tag { opacity: 0.7; }\n\n/* === v2: stroke-order layout (Sep 2026) === */\n/* --- word block: furigana over the word, meaning below; whole block taps to play word audio --- */\n.word-block { position: relative; z-index: 1; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.word-block:active { opacity: 0.55; }\n/* the back word keeps the front word's exact box (margin 24px/16px, line-height 1.6) so it does not move on flip;\n   furigana hangs above the glyphs out of flow, in the leading + top margin */\n.front-word-ruby { position: relative; margin: 24px 0 -10px; line-height: 1.6; }\n.front-word-ruby .fw-base, .front-word-ruby .fk { position: relative; display: inline-block; line-height: 1; }\n.front-word-ruby .fw-read, .front-word-ruby .fr { position: absolute; left: 50%; bottom: 100%; transform: translateX(-50%); margin-bottom: 3px; font-size: 0.4em; font-weight: 500; color: #d63964; line-height: 1.2; letter-spacing: 0.02em; white-space: nowrap; }\n.word-block .meaning { margin-bottom: 0; }\n.word-block .meaning { margin-top: 4px; }\n.card.prod .front-english { margin-bottom: 0; }\n.card.prod .front-word-ruby { margin-top: 14px; }\n\n/* --- word info: part of speech + Nihongo word link; fades up behind the meaning --- */\n.wordinfo { position: relative; margin: -48px 0 0; padding: 62px 16px 10px; background: linear-gradient(to bottom, rgba(245,245,245,0) 0%, #f5f5f5 70%); border-radius: 10px; text-align: left; display: flex; align-items: center; justify-content: space-between; gap: 12px; overflow: hidden; }\n.card.prod .wordinfo { margin-top: -30px; padding-top: 44px; }\n.wordinfo-pos { font-size: 14px; font-weight: 600; color: #8c8c8c; letter-spacing: 0.01em; }\n.card a.wordinfo-nih { font-weight: 800; font-size: 20px; line-height: 1; color: #8c8c8c; text-decoration: none; padding: 0 0 2px; border-bottom: 2px dotted #8c8c8c; flex: none; -webkit-tap-highlight-color: transparent; }\n.card a.wordinfo-nih:active { background: rgba(0,0,0,0.08); }\n\n/* --- example card: the whole card taps to play the sentence --- */\n.example { margin-top: 12px; }\n.kanji-breakdown { margin-top: 12px; }\n.example.tap-play-ex { cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.example.tap-play-ex:active { opacity: 0.55; }\n.example .audio.example-audio { display: none; margin: 0; }\n\n/* --- example list (.ex-v2 is added by the template script): one .ex-item per sentence, split like the kanji entries.\n   The card itself has no padding - each item carries it, so the whole row (edge to edge) is the tap target --- */\n.example.ex-v2 { padding: 0; overflow: hidden; }\n.ex-v2 .ex-item { position: relative; padding: 10px 16px 12px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.ex-v2 .ex-item + .ex-item::before { content: \"\"; position: absolute; top: 0; left: 16px; right: 16px; border-top: 1px solid rgba(128,128,128,0.13); }\n.ex-v2 .ex-item:active { opacity: 0.55; }\n.ex-v2 .ex-item audio { display: none; }\n/* no-JS fallback: the separator stored in the fields still reads as a rule */\n.example hr.ex-sep { border: none; border-top: 1px solid rgba(128,128,128,0.13); margin: 8px 0; }\n.nightMode .ex-v2 .ex-item + .ex-item::before, .nightMode .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .ex-v2 .ex-item + .ex-item::before, .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); } }\n\n/* --- kanji entries (re-laid out by the template script; .kb-v2 is added once that has run) --- */\n.kb-v2 .k-brk { line-height: 1.45; }\n.kb-v2 .k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kb-v2 .k-head2 { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 5px; }\n.kb-v2 .k-readings { flex: 1 1 auto; min-width: 0; display: block; font-size: 0.95em; line-height: 1.4; }\n.kb-v2 .k-reading2 { display: flex; align-items: baseline; gap: 6px; color: #222; font-size: 1.02em; line-height: 1.5; }\n.kb-v2 .k-lab { flex: none; min-width: 2.4em; font-size: 0.68em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.kb-v2 .k-vals { color: #222; }\n.kb-v2 .k-r { white-space: nowrap; }\n.kb-v2 .k-mean2 { font-weight: 500; font-size: 1em; color: #222; line-height: 1.35; margin: 0; }\n.kb-v2 .k-stats2 { float: right; display: flex; flex-direction: column; align-items: flex-end; gap: 7px; margin-left: 12px; min-width: 2.2em; }\n.kb-v2 .k-sv { font-weight: 700; font-size: 0.8em; color: #8c8c8c; line-height: 1; letter-spacing: 0.02em; white-space: nowrap; }\n.kb-v2 .k-unit { font-size: 0.9em; font-weight: 600; margin-left: 1px; }\n.kb-v2 .k-brk a.k-nih { font-weight: 800; font-size: 1.35em; line-height: 1; color: #1f665b !important; text-decoration: none !important; padding: 0 0 2px; margin: -2px 0 2px; border-bottom: 2px dotted #1f665b; -webkit-tap-highlight-color: transparent; }\n.kb-v2 .k-brk a.k-nih:active { background: rgba(31,102,91,0.15); }\n\n/* --- on/kun readings tap to play their clip (class added by the template script); dotted underline = tappable --- */\n.kb-v2 .k-r.k-r-tap { cursor: pointer; text-decoration: underline dotted #a9a9a9; text-decoration-thickness: 1.5px; text-underline-offset: 4px; padding: 5px 2px; margin: 0 -2px; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.kb-v2 .k-r.k-r-tap:active { opacity: 0.55; }\n.kb-v2 .k-r.k-r-tap.playing { color: #1f665b; text-decoration-color: #1f665b; }\n.nightMode .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; }\n.nightMode .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; }\n@media (prefers-color-scheme: dark) { .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; } .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; } }\n\n/* --- every tap target: no double-tap zoom / 300 ms click delay on iOS --- */\n.word-block, .ex-v2 .ex-item, .kb-v2 .k-box, .kb-v2 .k-r.k-r-tap, .kb-v2 .k-head2, .card a.wordinfo-nih, .kb-v2 .k-brk a.k-nih { touch-action: manipulation; }\n\n/* --- the kanji grid box --- */\n.kb-v2 .k-box { position: relative; flex: none; width: 66px; height: 66px; box-sizing: border-box; border: 1.5px dotted #d2d2d2; border-radius: 4px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; --k-ink: #1f1f1f; --k-ghost: #bdbdbd; --k-grid: #c4c4c4; --k-dot: #49c248; }\n.kb-v2 .k-box:active { background: rgba(31,102,91,0.06); }\n.kb-v2 .k-fallback { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 40px; line-height: 1; color: #1f1f1f; }\n.kb-v2 .k-box.has-svg .k-fallback { display: none; }\n.kb-v2 .k-svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }\n.kb-v2 .k-grid line { stroke: var(--k-grid); stroke-width: 1.2; stroke-dasharray: 2 3; vector-effect: non-scaling-stroke; }\n.kb-v2 .k-ghost path { fill: none; stroke: var(--k-ghost); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; opacity: 0; transition: opacity 0.15s; }\n.kb-v2 .k-box.animating .k-ghost path { opacity: 1; }\n.kb-v2 .k-ink path { fill: none; stroke: var(--k-ink); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; }\n.kb-v2 .k-dot { fill: var(--k-dot); opacity: 0; transition: opacity 0.25s; }\n.kb-v2 .k-box.animating .k-dot, .kb-v2 .k-box.done .k-dot { opacity: 1; }\n.kb-v2 .k-play { position: absolute; right: -8px; bottom: -8px; width: 18px; height: 18px; border-radius: 50%; background: #efefef; color: #5a5a5a; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 0 2px #f5f5f5; cursor: pointer; z-index: 1; }\n.kb-v2 .k-play svg { width: 12px; height: 12px; margin-left: 2px; }\n.kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #dcdcdc; }\n.kb-v2 .k-box.animating .k-play { opacity: 0.55; }\n\n/* --- tap guard, answer side only (templates/tap_guard.js): taps on the card never reach AnkiMobile's tap zones.\n   The shield is a transparent full-screen layer behind the card, so the empty space around a short card is covered too --- */\n.tap-shield { position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 0; background: transparent; -webkit-tap-highlight-color: transparent; }\n.card[data-notap] { position: relative; z-index: 1; -webkit-tap-highlight-color: transparent; }\n\n/* --- narrow screens (iPhone): trim the side margins; wider screens keep max-width 600 + 20px padding --- */\n@media (max-width: 480px) {\n  body { margin-left: 0; margin-right: 0; }\n  .card { padding: 14px 12px 24px; }\n}\n\n/* dark (Anki .nightMode) */\n.nightMode .front-word-ruby .fw-read, .nightMode .front-word-ruby .fr { color: #f0826e; }\n.nightMode .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n.nightMode .wordinfo-pos { color: #8f8f8f; }\n.nightMode .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n.nightMode .kb-v2 .k-reading2, .nightMode .kb-v2 .k-vals { color: #e6e6e6; }\n.nightMode .kb-v2 .k-lab { color: #8a8a8a; }\n.nightMode .kb-v2 .k-mean2 { color: #e6e6e6; }\n.nightMode .kb-v2 .k-sv { color: #8f8f8f; }\n.nightMode .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n.nightMode .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n.nightMode .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n.nightMode .kb-v2 .k-fallback { color: #f2f2f2; }\n.nightMode .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n.nightMode .kb-v2 .k-box:active .k-play, .nightMode .kb-v2 .k-play:active { background: #4a4a4a; }\n\n/* dark (system) */\n@media (prefers-color-scheme: dark) {\n  .front-word-ruby .fw-read, .front-word-ruby .fr { color: #f0826e; }\n  .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n  .wordinfo-pos { color: #8f8f8f; }\n  .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n  .kb-v2 .k-reading2, .kb-v2 .k-vals { color: #e6e6e6; }\n  .kb-v2 .k-lab { color: #8a8a8a; }\n  .kb-v2 .k-mean2 { color: #e6e6e6; }\n  .kb-v2 .k-sv { color: #8f8f8f; }\n  .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n  .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n  .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n  .kb-v2 .k-fallback { color: #f2f2f2; }\n  .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n  .kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #4a4a4a; }\n}\n\n/* Answer-only compact reveal. Fronts and unillustrated cards keep their layout. */\n/* Anki can paint inserted HTML before evaluating its template scripts.\n   Suppress that intermediate layout, but automatically show it after 700ms\n   even if scripts fail. Never depend on JavaScript to make a card readable. */\n.card[data-notap]:has(.vocab-visual):not(.visual-ready) {\n  animation: visual-prepare-fallback 700ms step-end both;\n}\n@keyframes visual-prepare-fallback { from { opacity: 0; } to { opacity: 1; } }\n.vocab-visual { margin: 0; text-align: center; }\n.card.has-vocab-visual > .vocab-visual {\n  margin: -24px 0 0;\n  /* Reserve the final banner height; animate the artwork, not a clipping mask. */\n  overflow: visible;\n}\n.vocab-visual img {\n  display: block;\n  width: 100%;\n  max-width: 480px;\n  height: auto;\n  aspect-ratio: 3 / 1;\n  object-fit: contain;\n  box-sizing: border-box;\n  padding: 4% 6%;\n  margin: 0 auto;\n  border-radius: 0;\n  transform-origin: center center;\n\n}\n.card.visual-ready .vocab-visual img {\n  animation: visual-entrance 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.has-vocab-visual .front-word-ruby {\n  font-size: 32px;\n  line-height: 1.35;\n  /* Furigana occupies the gap; image padding already supplies breathing room. */\n  margin: 14px 0 0;\n  text-align: center;\n  transform-origin: center center;\n\n}\n.card.has-vocab-visual .meaning { font-size: 18px; line-height: 1.35; margin: 2px 0 0; }\n/* Keep the shared light/dark gradient behind the compact meaning and POS. */\n.card.has-vocab-visual .wordinfo { margin: -32px 0 0; padding: 38px 16px 10px; }\n.card.has-vocab-visual.prod .front-english { font-size: 22px; line-height: 1.3; margin: 6px 0 0; }\n.card.has-vocab-visual.prod .front-word-ruby { margin-top: 16px; }\n.card.has-vocab-visual .example { margin-top: 6px; }\n/* One moving answer block preserves every internal spacing relationship. */\n.visual-content { display: flow-root; }\n.card.visual-ready .visual-content {\n  animation: visual-content-slide 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready:not(.prod) .front-word-ruby {\n  animation: visual-word 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready .meaning,\n.card.visual-ready .wordinfo,\n.card.visual-ready .example,\n.card.visual-ready .kanji-breakdown,\n.card.visual-ready .fw-read,\n.card.visual-ready .fr {\n  animation: visual-details 400ms ease-out 100ms both;\n}\n.card.visual-ready.prod .front-english {\n  animation: visual-english 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n@keyframes visual-english { from { font-size: 34px; line-height: 1.6; color: var(--visual-cue-start, #111); } to { font-size: 22px; line-height: 1.3; color: var(--visual-cue-end, #8c8c8c); } }\n@keyframes visual-details { from { opacity: 0; } to { opacity: 1; } }\n@keyframes visual-content-slide {\n  from { transform: translateY(var(--visual-content-start, -100px)); }\n  to { transform: translateY(0); }\n}\n@keyframes visual-entrance {\n  from { opacity: 0; transform: translateY(-100%) scale(.94); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n@keyframes visual-word { from { transform: scale(1.4375); } to { transform: scale(1); } }\n@media (max-width: 480px) {\n  .card.has-vocab-visual > .vocab-visual { margin: -14px 0 0; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .card.has-vocab-visual > .vocab-visual,\n  .card.has-vocab-visual .vocab-visual img,\n  .card.visual-ready .visual-content,\n  .card.has-vocab-visual .fr,\n  .card.has-vocab-visual .fw-read,\n  .card.visual-ready:not(.prod) .front-word-ruby,\n  .card.visual-ready.prod .front-english,\n  .card.has-vocab-visual .meaning,\n  .card.has-vocab-visual .wordinfo,\n  .card.has-vocab-visual .example,\n  .card.has-vocab-visual .kanji-breakdown,\n  .card.has-vocab-visual.prod .front-english { animation: none; }\n}\n\n/* De-emphasize the English cue only after revealing a Production answer. */\n.card.prod:has(.wordinfo) .front-english { color: #8c8c8c; }\n.nightMode .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n}\n\n/* Carry the question color through the shrink instead of swapping it on reveal. */\n.nightMode .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n}\n.card.visual-ready.prod .word-block { animation: visual-details 400ms ease-out 100ms both; }\n@media (prefers-reduced-motion: reduce) {\n  .card.visual-ready.prod .word-block { animation: none; }\n}\n\nhtml,body{margin:0;padding:0;background:transparent}.card{padding-top:0;padding-bottom:16px;display:flow-root}.tap-shield{display:none}.word-block{cursor:pointer}\n</style></head><body><script src=\"_kanji_strokes.js\"></script>\n<div class=\"tap-shield tappable\" onclick=\"void 0\"></div>\n<div class=\"card tappable has-vocab-visual\" data-notap onclick=\"void 0\">\n<div class=\"word-block tap-play\" onclick=\"event.stopPropagation();var b=this.parentNode.querySelector('.word-audio-hidden a');if(b)b.click();\">\n<div class=\"front-word front-word-ruby\"><span class=\"fw-base\">猫</span><span class=\"fw-read\">ねこ</span></div>\n<div class=\"meaning\">cat</div>\n</div>\n<div class=\"word-audio-hidden\"><a href=\"#\" onclick=\"event.preventDefault();this.nextElementSibling.currentTime=0;this.nextElementSibling.play()\">Play</a><audio src=\"n5_wd_d6c72565c05815af.mp3\"></audio></div>\n<div class=\"wordinfo\">\n<div class=\"wordinfo-pos\">Noun</div>\n<a class=\"wordinfo-nih\" href=\"https://nihongo-app.com/dictionary/word/猫\">語</a>\n</div>\n<div class=\"example tap-play-ex\" onclick=\"event.stopPropagation();var a=this.querySelector('audio');if(a){a.currentTime=0;a.play();}\">\n<div class=\"example-ja\">うちに <ruby>猫<rt>ねこ</rt></ruby>が <ruby>二匹<rt>にひき</rt></ruby>います。<hr class=\"ex-sep\"><ruby>猫<rt>ねこ</rt></ruby>がいすの <ruby>上<rt>うえ</rt></ruby>で <ruby>寝<rt>ね</rt></ruby>ています。</div>\n<div class=\"example-en\">We have two cats at home.<hr class=\"ex-sep\">The cat is sleeping on the chair.</div>\n<div class=\"audio example-audio\"><audio src=\"n5_ex_d5fbd50890365d5f.mp3\" preload=\"none\"></audio><audio src=\"n5_ex_a386f82af75953a1.mp3\" preload=\"none\"></audio></div>\n</div>\n\n<div class=\"kanji-breakdown\">\n<div class=\"kb-content\"><div class=\"k-brk\">\n  <div class=\"k-head\"><a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji/猫\"><span class=\"k-char\">猫</span></a><span class=\"k-stats\"><span class=\"k-stat\"><span class=\"k-stat-v\">11</span><span class=\"k-stat-l\">Strokes</span></span><span class=\"k-stat\"><span class=\"k-stat-v\">N2</span><span class=\"k-stat-l\">JLPT</span></span></span></div>\n  <div class=\"k-mean\">cat</div>\n  <div class=\"k-reading\"><span class=\"k-label\">On:</span> <span class=\"k-r\">ビョウ</span></div>\n  <div class=\"k-reading\"><span class=\"k-label\">Kun:</span> <span class=\"k-r\">ねこ</span></div>\n  <div class=\"k-radical\"><span class=\"k-label\">Radical:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/犬\">犬</a> (inu, dog)</div>\n  <div class=\"k-components\"><span class=\"k-label\">Components:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/田\">田</a> rice field, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/犭\">犭</a> dog, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/⺾\">⺾</a></div>\n</div></div>\n</div>\n\n<span class=\"visual-key\" hidden>猫|ねこ</span>\n<span class=\"dictionary-key\" hidden>猫|ねこ|cat</span>\n<script>\n(function(){\n  var NS = 'http://www.w3.org/2000/svg';\n  var KANJI_RE = /[㐀-鿿豈-﫿々]/;\n  function el(tag, attrs){ var e = document.createElementNS(NS, tag); for (var k in attrs) e.setAttribute(k, attrs[k]); return e; }\n  function txt(n){ return n ? (n.textContent || '').replace(/\\s+/g, ' ').trim() : ''; }\n  function stop(e){ e.stopPropagation(); }\n  function guard(node){ node.addEventListener('click', stop, false); node.addEventListener('touchend', stop, false); }\n  /* run fn on a tap. iOS drops the click after a touch that stops a momentum scroll or that it takes for a double-tap,\n     so on touch devices we act on touchend of an unmoved touch and suppress the synthetic click; mouse/desktop use click */\n  function tap(node, fn){\n    var sx = 0, sy = 0, moved = true, handled = false;\n    node.addEventListener('touchstart', function(e){ var t = e.touches[0]; if (!t || e.touches.length > 1) { moved = true; return; } sx = t.clientX; sy = t.clientY; moved = false; handled = false; }, {passive: true});\n    node.addEventListener('touchmove', function(e){ var t = e.touches[0]; if (!t || Math.abs(t.clientX - sx) > 12 || Math.abs(t.clientY - sy) > 12) moved = true; }, {passive: true});\n    node.addEventListener('touchend', function(e){ if (moved) return; moved = true; handled = true; if (e.cancelable) e.preventDefault(); fn(); }, {passive: false});\n    node.addEventListener('touchcancel', function(){ moved = true; }, {passive: true});\n    node.addEventListener('click', function(){ if (handled) { handled = false; return; } fn(); }, false);\n  }\n  // scope everything to the card this script lives in (falls back to the last card on the page)\n  var root = null, cs = document.currentScript;\n  if (cs && cs.closest) root = cs.closest('.card');\n  if (!root) { var cards = document.querySelectorAll('.card'); root = cards.length ? cards[cards.length - 1] : document; }\n\n  /* ---- align a kana reading to the kanji runs of a word: お願いします + おねがいします -> お<ruby>願<rt>ねが</rt></ruby>います ---- */\n  function toHira(s){ return s.replace(/[ァ-ヶ]/g, function(c){ return String.fromCharCode(c.charCodeAt(0) - 0x60); }); }\n  function isKanji(c){ return KANJI_RE.test(c); }\n  function isKana(c){ return /[ぁ-ゟ゠-ヿ]/.test(c); }\n  function esc(s){ return s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&'); }\n  function alignFurigana(word, reading){\n    reading = (reading || '').replace(/\\s+/g, '');\n    if (word.indexOf('(') < 0) reading = reading.replace(/[（(][^)）]*[)）]/g, '');\n    if (word.indexOf('/') < 0 && reading.indexOf('/') >= 0) reading = reading.split('/')[0];\n    var hira = toHira(reading);\n    // split the word into runs: kanji / kana / other\n    var runs = [], i, c, t, cur = null;\n    for (i = 0; i < word.length; i++) {\n      c = word.charAt(i); t = isKanji(c) ? 'k' : (isKana(c) ? 'a' : 'o');\n      if (c === '々' && cur && cur.t === 'k') t = 'k';\n      if (cur && cur.t === t) cur.s += c; else { cur = {t:t, s:c}; runs.push(cur); }\n    }\n    var kanjiRuns = 0; for (i = 0; i < runs.length; i++) if (runs[i].t === 'k') kanjiRuns++;\n    if (!kanjiRuns) return null;\n    var pat = '^';\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') pat += '(.+?)';\n      else if (runs[i].t === 'a') pat += esc(toHira(runs[i].s));\n      else pat += '(?:' + esc(runs[i].s) + ')?';\n    }\n    pat += '$';\n    var m = hira.match(new RegExp(pat));\n    if (!m) return null;\n    var out = [], gi = 1, pos = 0;\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') {\n        // take the kana slice from the original reading (keeps katakana if it was katakana)\n        var idx = hira.indexOf(m[gi], pos); if (idx < 0) return null;\n        out.push({kanji: runs[i].s, kana: reading.substr(idx, m[gi].length)});\n        pos = idx + m[gi].length; gi++;\n      } else { out.push({text: runs[i].s}); if (runs[i].t === 'a') pos += runs[i].s.length; }\n    }\n    return out;\n  }\n  function fk(kanji, kana){\n    var s = document.createElement('span'); s.className = 'fk'; s.appendChild(document.createTextNode(kanji));\n    var r = document.createElement('span'); r.className = 'fr'; r.textContent = kana; s.appendChild(r);\n    return s;\n  }\n  function renderFurigana(container, word, reading){\n    var parts = alignFurigana(word, reading);\n    if (!parts) return false;\n    while (container.firstChild) container.removeChild(container.firstChild);\n    for (var i = 0; i < parts.length; i++) {\n      if (parts[i].kanji) container.appendChild(fk(parts[i].kanji, parts[i].kana));\n      else container.appendChild(document.createTextNode(parts[i].text));\n    }\n    return true;\n  }\n  function renderWhole(container, word, reading){\n    while (container.firstChild) container.removeChild(container.firstChild);\n    if (reading) container.appendChild(fk(word, reading)); else container.appendChild(document.createTextNode(word));\n  }\n\n  /* ---- 1. furigana over the word: only over the kanji, hung above the glyphs so the word sits exactly where it does on the front ---- */\n  var fw = root.querySelector('.front-word-ruby');\n  if (fw) {\n    var baseEl = fw.querySelector('.fw-base'), readEl = fw.querySelector('.fw-read');\n    var base = txt(baseEl), reading = txt(readEl);\n    if (!KANJI_RE.test(base) || reading === base || !reading) renderWhole(fw, base, '');\n    else if (!renderFurigana(fw, base, reading)) renderWhole(fw, base, reading);\n  }\n\n  /* ---- 2. audio tap targets must never reach the card's tap gestures ---- */\n  var taps = root.querySelectorAll('.tap-play, .tap-play-ex, .wordinfo-nih');\n  for (var i = 0; i < taps.length; i++) guard(taps[i]);\n\n  /* ---- 2b. example sentences: the fields may hold two sentences separated by <hr class=\"ex-sep\">.\n     Re-lay them out as list items (.ex-item = Japanese + English + its own clip); the WHOLE item,\n     padding included, is the tap target, and nothing inside the red card ever reaches Anki's tap gestures ---- */\n  var ex = root.querySelector('.example');\n  if (ex && !ex.classList.contains('ex-v2')) {\n    var splitAtHr = function(node){\n      var groups = [[]]; if (!node) return groups;\n      var n = node.firstChild;\n      while (n) { var nx = n.nextSibling; if (n.nodeType === 1 && n.tagName === 'HR') groups.push([]); else groups[groups.length - 1].push(n); n = nx; }\n      return groups;\n    };\n    var jaG = splitAtHr(ex.querySelector('.example-ja')), enG = splitAtHr(ex.querySelector('.example-en'));\n    var auds = ex.querySelectorAll('audio'), items = [], g, k;\n    for (g = 0; g < jaG.length; g++) {\n      var item = document.createElement('div'); item.className = 'ex-item'; item.setAttribute('role', 'button');\n      var ja = document.createElement('div'); ja.className = 'example-ja';\n      for (k = 0; k < jaG[g].length; k++) ja.appendChild(jaG[g][k]);\n      item.appendChild(ja);\n      if (enG[g]) { var en = document.createElement('div'); en.className = 'example-en'; for (k = 0; k < enG[g].length; k++) en.appendChild(enG[g][k]); item.appendChild(en); }\n      if (auds[g]) item.appendChild(auds[g]);\n      items.push(item);\n    }\n    while (ex.firstChild) ex.removeChild(ex.firstChild);\n    ex.removeAttribute('onclick'); ex.onclick = null;\n    ex.classList.remove('tap-play-ex'); ex.classList.add('ex-v2');\n    var playItem = function(item){\n      var all = ex.querySelectorAll('audio'), mine = item.querySelector('audio');\n      for (var a = 0; a < all.length; a++) if (all[a] !== mine) { try { all[a].pause(); all[a].currentTime = 0; } catch (e) {} }\n      if (mine) { try { mine.currentTime = 0; } catch (e) {} var pr = mine.play(); if (pr && pr.catch) pr.catch(function(){}); }\n    };\n    for (g = 0; g < items.length; g++) {\n      ex.appendChild(items[g]); guard(items[g]);\n      (function(it){ tap(it, function(){ playItem(it); }); })(items[g]);\n    }\n  }\n\n  /* ---- 3. re-lay out each kanji breakdown entry (field markup stays unchanged) ---- */\n  var kb = root.querySelector('.kanji-breakdown');\n  if (kb && !kb.classList.contains('kb-v2')) {\n    var brks = kb.querySelectorAll('.k-brk');\n    for (var b = 0; b < brks.length; b++) relayout(brks[b]);\n    kb.classList.add('kb-v2');\n\n    /* ---- 3b. tappable on/kun readings: each .k-r plays `_kr_<hex of the hiragana reading>.mp3`\n       (a _-prefixed template media file; okurigana marks, dots and hyphens are dropped, katakana -> hiragana).\n       The whole head row swallows taps so a near miss never flips the card. ---- */\n    var krAudio = null;\n    var krFile = function(t){\n      var sp = toHira(t.replace(/[-.()（）\\s‐－]/g, '')), hex = '';\n      if (!sp || !/^[ぁ-ゖー]+$/.test(sp)) return null;\n      for (var i = 0; i < sp.length; i++) hex += ('0000' + sp.charCodeAt(i).toString(16)).slice(-4);\n      return '_kr_' + hex + '.mp3';\n    };\n    var playKr = function(node, file){\n      if (!krAudio) { krAudio = document.createElement('audio'); krAudio.setAttribute('preload', 'none'); krAudio.style.display = 'none'; root.appendChild(krAudio); }\n      var others = root.querySelectorAll('.example audio');\n      for (var o = 0; o < others.length; o++) { try { others[o].pause(); } catch (e) {} }\n      var on = kb.querySelectorAll('.k-r.playing'); for (var q = 0; q < on.length; q++) on[q].classList.remove('playing');\n      node.classList.add('playing'); setTimeout(function(){ node.classList.remove('playing'); }, 700);\n      try { krAudio.pause(); krAudio.src = file; krAudio.currentTime = 0; } catch (e) {}\n      var pr = krAudio.play(); if (pr && pr.catch) pr.catch(function(){});\n    };\n    var krs = kb.querySelectorAll('.k-r');\n    for (var r2 = 0; r2 < krs.length; r2++) (function(node){\n      var file = krFile(txt(node)); if (!file) return;\n      node.classList.add('k-r-tap'); node.setAttribute('role', 'button');\n      guard(node); tap(node, function(){ playKr(node, file); });\n    })(krs[r2]);\n    var heads = kb.querySelectorAll('.k-head2'); for (var h2 = 0; h2 < heads.length; h2++) guard(heads[h2]);\n  }\n\n  function relayout(brk){\n    var ch = txt(brk.querySelector('.k-char'));\n    if (!ch) return;\n    var link = brk.querySelector('.k-head a');\n    var href = (link && link.getAttribute('href')) || ('https://nihongo-app.com/dictionary/kanji/' + ch);\n    var strokes = '', jlpt = '';\n    var stats = brk.querySelectorAll('.k-stat');\n    for (var s = 0; s < stats.length; s++) {\n      var lab = txt(stats[s].querySelector('.k-stat-l')).toLowerCase(), v = txt(stats[s].querySelector('.k-stat-v'));\n      if (lab.indexOf('stroke') === 0) strokes = v; else if (lab.indexOf('jlpt') === 0) jlpt = v;\n    }\n    var meanText = txt(brk.querySelector('.k-mean'));\n    var readings = brk.querySelectorAll('.k-reading');\n\n    var head = document.createElement('div'); head.className = 'k-head2';\n    var box = document.createElement('div'); box.className = 'k-box'; box.setAttribute('data-kanji', ch); box.setAttribute('role', 'button');\n    var fb = document.createElement('span'); fb.className = 'k-fallback'; fb.textContent = ch; box.appendChild(fb);\n    var play = document.createElement('span'); play.className = 'k-play';\n    play.innerHTML = '<svg viewBox=\"0 0 12 12\"><path d=\"M3.6 2.2 L10 6 L3.6 9.8 Z\" fill=\"currentColor\"/></svg>';\n    box.appendChild(play);\n    head.appendChild(box);\n\n    var col = document.createElement('div'); col.className = 'k-readings';\n    var st = document.createElement('span'); st.className = 'k-stats2';\n    var nih = document.createElement('a'); nih.className = 'k-nih'; nih.href = href; nih.textContent = '語'; st.appendChild(nih);\n    if (strokes) { var sv = document.createElement('span'); sv.className = 'k-sv'; sv.innerHTML = strokes + '<span class=\"k-unit\">画</span>'; st.appendChild(sv); }\n    if (jlpt) { var jv = document.createElement('span'); jv.className = 'k-sv'; jv.textContent = jlpt; st.appendChild(jv); }\n    col.appendChild(st);\n    for (var r = 0; r < readings.length; r++) {\n      var src = readings[r], label = src.querySelector('.k-label');\n      var row = document.createElement('div'); row.className = 'k-reading2';\n      var lab2 = document.createElement('span'); lab2.className = 'k-lab'; lab2.textContent = txt(label).replace(/:$/, ''); row.appendChild(lab2);\n      var vals = document.createElement('span'); vals.className = 'k-vals';\n      var n = src.firstChild;\n      while (n) { var next = n.nextSibling; if (n !== label) vals.appendChild(n); n = next; }\n      row.appendChild(vals); col.appendChild(row);\n    }\n    head.appendChild(col);\n\n    var mean = document.createElement('div'); mean.className = 'k-mean2'; mean.textContent = meanText;\n\n    while (brk.firstChild) brk.removeChild(brk.firstChild);\n    brk.appendChild(head); brk.appendChild(mean);\n    guard(box); guard(nih);\n    tap(box, function(){ animate(box); });\n  }\n\n  /* ---- 4. stroke-order boxes (KanjiVG paths from _kanji_strokes.js) ---- */\n  function buildBox(box){\n    var strokes = window.KANJI_STROKES[box.getAttribute('data-kanji')];\n    if (!strokes || !strokes.length) return;\n    var svg = el('svg', {viewBox:'-7 -7 123 123', 'class':'k-svg', 'aria-hidden':'true'});\n    var grid = el('g', {'class':'k-grid'});\n    grid.appendChild(el('line', {x1:54.5, y1:-5, x2:54.5, y2:114}));\n    grid.appendChild(el('line', {x1:-5, y1:54.5, x2:114, y2:54.5}));\n    svg.appendChild(grid);\n    var ghost = el('g', {'class':'k-ghost'}), ink = el('g', {'class':'k-ink'}), paths = [];\n    for (var i = 0; i < strokes.length; i++) {\n      ghost.appendChild(el('path', {d:strokes[i]}));\n      var p = el('path', {d:strokes[i]}); ink.appendChild(p); paths.push(p);\n    }\n    svg.appendChild(ghost); svg.appendChild(ink);\n    var dot = el('circle', {'class':'k-dot', r:5.2, cx:-20, cy:-20});\n    svg.appendChild(dot);\n    box.insertBefore(svg, box.firstChild);\n    box.classList.add('has-svg');\n    box._k = {paths:paths, dot:dot, raf:0, timer:0};\n  }\n  function cancel(box){\n    var s = box._k; if (!s) return;\n    if (s.raf) cancelAnimationFrame(s.raf); s.raf = 0;\n    if (s.timer) clearTimeout(s.timer); s.timer = 0;\n    box.classList.remove('animating'); box.classList.remove('done');\n  }\n  function animate(box){\n    if (!box._k && window.KANJI_STROKES) buildBox(box);   // asset arrived after this box was laid out\n    var s = box._k; if (!s) return;\n    cancel(box);\n    var lens = [], i, p;\n    for (i = 0; i < s.paths.length; i++) { lens.push(s.paths[i].getTotalLength()); }\n    for (i = 0; i < s.paths.length; i++) { p = s.paths[i]; p.style.strokeDasharray = lens[i] + ' ' + lens[i]; p.style.strokeDashoffset = lens[i]; }\n    box.classList.add('animating');\n    var idx = 0, t0 = 0, GAP = 70;\n    function dur(len){ return Math.max(170, 90 + len * 4.6); }\n    function ease(t){ return 1 - Math.pow(1 - t, 1.5); }\n    function step(ts){\n      if (!t0) t0 = ts;\n      var q = s.paths[idx], len = lens[idx], t = Math.min(1, (ts - t0) / dur(len)), e = ease(t);\n      q.style.strokeDashoffset = len * (1 - e);\n      var pt = q.getPointAtLength(len * e);\n      s.dot.setAttribute('cx', pt.x); s.dot.setAttribute('cy', pt.y);\n      if (t < 1) { s.raf = requestAnimationFrame(step); return; }\n      idx++; t0 = 0;\n      if (idx < s.paths.length) {\n        s.timer = setTimeout(function(){ s.timer = 0; s.raf = requestAnimationFrame(step); }, GAP);\n      } else {\n        box.classList.remove('animating'); box.classList.add('done');\n        s.timer = setTimeout(function(){ s.timer = 0; box.classList.remove('done'); }, 650);\n      }\n    }\n    var p0 = s.paths[0].getPointAtLength(0); s.dot.setAttribute('cx', p0.x); s.dot.setAttribute('cy', p0.y);\n    s.raf = requestAnimationFrame(step);\n  }\n  var tries = 0;\n  function fill(){\n    if (window.KANJI_STROKES) {\n      var boxes = root.querySelectorAll('.k-box:not(.has-svg)');\n      for (var i = 0; i < boxes.length; i++) buildBox(boxes[i]);\n    } else if (tries++ < 150) { setTimeout(fill, tries < 20 ? 50 : 200); }   // external asset may still be loading (waits up to ~27 s)\n  }\n  fill();\n  // if the asset script is still in flight, fill as soon as it lands (covers WebViews that load it asynchronously)\n  var ks = document.querySelectorAll('script[src*=\"_kanji_strokes\"]');\n  for (var si = 0; si < ks.length; si++) ks[si].addEventListener('load', fill, false);\n})();\n\n</script>\n<script>\n\n</script>\n</div>\n</body></html>"}, {"word": "時計", "reading": "とけい", "image": "media/vocab-389a8b3af5f3.webp", "audio": "media/n5_wd_0065385ff4b92ab3.mp3", "doc": "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><base href=\"media/\"><style>/* ===== BASE / LIGHT MODE ===== */\n.card {\n  font-family: 'SF Pro Display', 'SF Pro Text', -apple-system, BlinkMacSystemFont,\n               'Hiragino Sans', 'Hiragino Kaku Gothic ProN', system-ui, sans-serif;\n  text-align: center;\n  padding: 24px 20px;\n  line-height: 1.6;\n  background: #ffffff;\n  color: #1a1a1a;\n  max-width: 600px;\n  margin: 0 auto;\n}\n.front-word {\n  font-size: 46px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n  letter-spacing: 0.02em;\n}\n.front-english {\n  font-size: 34px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n}\n.reading {\n  font-size: 26px;\n  color: #d63964;\n  margin: 8px 0;\n  font-weight: 500;\n}\n.meaning {\n  font-size: 22px;\n  color: #1a5276;\n  margin: 8px 0;\n  font-weight: 600;\n}\n.pos-tag {\n  display: inline-block;\n  background-color: #2c3e50;\n  color: #fff;\n  padding: 4px 14px;\n  border-radius: 14px;\n  font-size: 13px;\n  margin: 6px 0;\n  letter-spacing: 0.03em;\n}\n.example {\n  margin: 18px 0 8px;\n  padding: 14px 16px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #d63964;\n}\n.example-ja {\n  font-size: 19px;\n  color: #222;\n  margin-bottom: 6px;\n  line-height: 1.7;\n}\n.example-ja ruby rt {\n  line-height: 1;\n  font-size: 0.55em;\n  color: #888;\n  font-weight: 400;\n}\n.example-en {\n  font-size: 15px;\n  color: #555;\n  font-style: italic;\n  line-height: 1.45;\n}\n.divider {\n  border: none;\n  border-top: 1px solid #e0e0e0;\n  margin: 16px 0;\n}\n.hint {\n  font-size: 14px;\n  color: #999;\n  margin-top: 12px;\n  letter-spacing: 0.02em;\n}\n.audio {\n  margin: 8px 0;\n}\n\n/* --- Example card: even out top/bottom (furigana rides in the 1.7 line-height leading; hidden <audio> wrapper added 8px) --- */\n.example { padding-top: 10px; padding-bottom: 12px; }\n.example .example-ja { margin-bottom: 0; }\n.example .audio.example-audio { margin: 0; }\n\n/* --- Kanji breakdown (always open, matches .example card, blue accent) --- */\n.kanji-breakdown {\n  margin: 14px 0 8px;\n  padding: 14px 16px 12px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #1fa77c;\n}\n.kanji-breakdown .kb-content {\n  font-size: 15px;\n  line-height: 1.9;\n  color: #444;\n}\n\n/* ===== DARK MODE: Anki .nightMode class ===== */\n.nightMode .card,\n.nightMode.card {\n  background: #1e1e1e;\n  color: #e0e0e0;\n}\n.nightMode .front-word { color: #f0f0f0; }\n.nightMode .front-english { color: #f0f0f0; }\n.nightMode .reading { color: #f0826e; }\n.nightMode .meaning { color: #6cb4ee; }\n.nightMode .pos-tag { background-color: #3a3f4b; color: #ccc; }\n.nightMode .example { background: #2a2a2a; border-left-color: #f0826e; }\n.nightMode .example-ja { color: #ddd; }\n.nightMode .example-ja ruby rt { color: #aaa; }\n.nightMode .example-en { color: #b0b0b0; }\n.nightMode .divider { border-top-color: #3a3a3a; }\n.nightMode .hint { color: #777; }\n.nightMode .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n.nightMode .kanji-breakdown .kb-content { color: #bbb; }\n\n/* ===== DARK MODE: prefers-color-scheme ===== */\n@media (prefers-color-scheme: dark) {\n  .card { background: #1e1e1e; color: #e0e0e0; }\n  .front-word { color: #f0f0f0; }\n  .front-english { color: #f0f0f0; }\n  .reading { color: #f0826e; }\n  .meaning { color: #6cb4ee; }\n  .pos-tag { background-color: #3a3f4b; color: #ccc; }\n  .example { background: #2a2a2a; border-left-color: #f0826e; }\n  .example-ja { color: #ddd; }\n  .example-ja ruby rt { color: #aaa; }\n  .example-en { color: #b0b0b0; }\n  .divider { border-top-color: #3a3a3a; }\n  .hint { color: #777; }\n  .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n  .kanji-breakdown .kb-content { color: #bbb; }\n}\n\n\n/* --- Audio replay button (matches kanji-breakdown pill) --- */\n.audio.player {\n  margin-top: 14px;\n}\n\n.replay-button {\n  display: flex;\n  justify-content: center;\n  align-items: center; \n  margin: 12px auto;\n  padding: 8px 18px;\n  min-width: 44px;\n  min-height: 44px;\n  box-sizing: border-box;\n  background: #F0F8EA;\n  border: 1px solid #C2E9C3;\n  border-radius: 8px;\n  color: #3E8C40;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n  transition: background 0.15s;\n  text-decoration: none;\n  line-height: 1;\n  text-align: center;\n}\n.replay-button svg {\n  width: 20px;\n  height: 20px;\n  vertical-align: middle;\n  fill: currentColor;\n}\n.replay-button svg circle {\n  fill: none;\n  stroke: none;\n}\n.replay-button svg path {\n  fill: currentColor;\n  stroke: none;\n}\n.replay-button:hover { background: #F0F8EA; }\n.replay-button:active { background: #C2E1C8; }\n\n.nightMode .replay-button {\n  background: #2B3A2A;\n  border-color: #3A503D;\n  color: #73EA8B;\n}\n.nightMode .replay-button:hover { background: #2B3A2A; }\n.nightMode .replay-button:active { background: #273827; }\n\n@media (prefers-color-scheme: dark) {\n  .replay-button {\n    background: #334633;\n    border-color: #3A503D;\n    color: #73EA8B;\n  }\n  .replay-button:hover { background: #2B3A2A; }\n  .replay-button:active { background: #334633; }\n}\n\n\n/* --- Example sentence: tap the Japanese text to play the sentence audio --- */\n.example .example-ja.tap-play-ex {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.example .example-ja.tap-play-ex:active { opacity: 0.55; }\n\n/* --- Word audio: hidden auto-generated button; tap the reading to replay --- */\n.word-audio-hidden { display: none; }\n.reading.tap-play {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.reading.tap-play:active { opacity: 0.55; }\n\n\n/* --- kanji breakdown (k-brk) --- */\n.k-brk { padding: 0; margin: 0; font-family: -apple-system, \"Hiragino Sans\", sans-serif; }\n.k-brk + .k-brk { border-top: 1px solid rgba(128,128,128,0.13); margin-top: 14px; padding-top: 14px; }\n.k-brk .k-mean { font-weight: 500; margin-bottom: 8px; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; }\n.k-brk .k-head .k-char { margin-right: 0; }\n.k-brk .k-stats { display: flex; gap: 18px; align-items: flex-start; margin-left: auto; }\n.k-brk .k-stat { display: flex; flex-direction: column; align-items: center; line-height: 1.25; }\n.k-brk .k-stat-v { font-weight: 700; font-size: 1em; color: #222; line-height: 1.2; height: 1.2em; display: block; }\n.k-brk .k-stat-l { margin-top: 3px; line-height: 1; font-size: 0.48em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.nightMode .k-brk .k-stat-v { color: #ddd; }\n.k-brk .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-meta { font-size: 0.9em; color: #888; }\n.k-brk .k-radical, .k-brk .k-components, .k-brk .k-mean { font-size: 0.95em; margin-top: 3px; }\n.nightMode .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); } .k-brk .k-meta { color: #aaa; } .k-brk .k-stat-v { color: #ddd; } }\n\n/* --- kanji breakdown enhancements (readings) --- */\n.k-brk { line-height: 1.7; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; margin-bottom: 6px; line-height: 1.1; }\n.k-brk .k-head .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-head .k-meta { font-size: 0.9em; color: #888; vertical-align: middle; }\n.k-brk .k-mean, .k-brk .k-reading, .k-brk .k-radical, .k-brk .k-components { margin-top: 1px; line-height: 1.45; }\n.k-brk .k-reading { font-size: 0.95em; }\n.k-brk .k-label { display: inline-block; min-width: 2.6em; color: #666; font-weight: 600; font-size: 0.85em; margin-right: 4px; letter-spacing: 0.02em; }\n.nightMode .k-brk .k-head .k-meta { color: #aaa; }\n.nightMode .k-brk .k-label { color: #bbb; }\n@media (prefers-color-scheme: dark) {\n  .k-brk .k-head .k-meta { color: #aaa; }\n  .k-brk .k-label { color: #bbb; }\n}\n\n/* --- compact kanji entries: no components line, On/Kun readings inline --- */\n.k-brk .k-components { display: none; }\n.k-brk .k-reading { display: inline; word-break: keep-all; }\n.k-brk .k-reading + .k-reading { margin-left: 14px; }\n.k-brk .k-reading .k-label { min-width: 0; }\n.k-brk .k-reading + .k-radical { margin-top: 3px; }\n.k-brk .k-reading .k-r { white-space: nowrap; }\n\n/* --- tight vertical rhythm for kanji entries --- */\n.k-brk { line-height: 1.45; }\n.k-brk .k-head { margin-bottom: 4px; }\n.k-brk .k-mean { margin-bottom: 2px; }\n.k-brk .k-reading + .k-radical { margin-top: 1px; }\n.k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kanji-breakdown .kb-content { line-height: 1.5; }\n\n/* --- Nihongo deep-link styling (assertive) --- */\n.k-brk a, .k-brk .k-link { color: #1f665b !important; text-decoration: underline dotted !important; text-underline-offset: 2px; text-decoration-thickness: 1.5px; padding-bottom: 1px; }\n.k-brk .k-head a, .k-brk .k-head .k-link { text-decoration: none !important; padding-bottom: 0; }\n.k-brk .k-head .k-char { color: inherit; }\n.k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #222 !important; border-bottom: 2px dotted #1f665b !important; padding-bottom: 2px; }\n.k-brk a:active, .k-brk .k-link:active { background: rgba(31, 102, 91, 0.15); }\n.k-brk .k-head a:active .k-char, .k-brk .k-head .k-link:active .k-char { background: rgba(31, 102, 91, 0.15); }\n.nightMode .k-brk a, .nightMode .k-brk .k-link { color: #63c2b1 !important; }\n.nightMode .k-brk .k-head a .k-char, .nightMode .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n@media (prefers-color-scheme: dark) {\n  .k-brk a, .k-brk .k-link { color: #63c2b1 !important; }\n  .k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n}\n\n/* --- POS pill tap target (wraps .pos-tag in Nihongo word link) --- */\n.pos-tag-link { text-decoration: none; color: inherit; display: inline-block; }\n.pos-tag-link:active .pos-tag { opacity: 0.7; }\n\n/* === v2: stroke-order layout (Sep 2026) === */\n/* --- word block: furigana over the word, meaning below; whole block taps to play word audio --- */\n.word-block { position: relative; z-index: 1; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.word-block:active { opacity: 0.55; }\n/* the back word keeps the front word's exact box (margin 24px/16px, line-height 1.6) so it does not move on flip;\n   furigana hangs above the glyphs out of flow, in the leading + top margin */\n.front-word-ruby { position: relative; margin: 24px 0 -10px; line-height: 1.6; }\n.front-word-ruby .fw-base, .front-word-ruby .fk { position: relative; display: inline-block; line-height: 1; }\n.front-word-ruby .fw-read, .front-word-ruby .fr { position: absolute; left: 50%; bottom: 100%; transform: translateX(-50%); margin-bottom: 3px; font-size: 0.4em; font-weight: 500; color: #d63964; line-height: 1.2; letter-spacing: 0.02em; white-space: nowrap; }\n.word-block .meaning { margin-bottom: 0; }\n.word-block .meaning { margin-top: 4px; }\n.card.prod .front-english { margin-bottom: 0; }\n.card.prod .front-word-ruby { margin-top: 14px; }\n\n/* --- word info: part of speech + Nihongo word link; fades up behind the meaning --- */\n.wordinfo { position: relative; margin: -48px 0 0; padding: 62px 16px 10px; background: linear-gradient(to bottom, rgba(245,245,245,0) 0%, #f5f5f5 70%); border-radius: 10px; text-align: left; display: flex; align-items: center; justify-content: space-between; gap: 12px; overflow: hidden; }\n.card.prod .wordinfo { margin-top: -30px; padding-top: 44px; }\n.wordinfo-pos { font-size: 14px; font-weight: 600; color: #8c8c8c; letter-spacing: 0.01em; }\n.card a.wordinfo-nih { font-weight: 800; font-size: 20px; line-height: 1; color: #8c8c8c; text-decoration: none; padding: 0 0 2px; border-bottom: 2px dotted #8c8c8c; flex: none; -webkit-tap-highlight-color: transparent; }\n.card a.wordinfo-nih:active { background: rgba(0,0,0,0.08); }\n\n/* --- example card: the whole card taps to play the sentence --- */\n.example { margin-top: 12px; }\n.kanji-breakdown { margin-top: 12px; }\n.example.tap-play-ex { cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.example.tap-play-ex:active { opacity: 0.55; }\n.example .audio.example-audio { display: none; margin: 0; }\n\n/* --- example list (.ex-v2 is added by the template script): one .ex-item per sentence, split like the kanji entries.\n   The card itself has no padding - each item carries it, so the whole row (edge to edge) is the tap target --- */\n.example.ex-v2 { padding: 0; overflow: hidden; }\n.ex-v2 .ex-item { position: relative; padding: 10px 16px 12px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.ex-v2 .ex-item + .ex-item::before { content: \"\"; position: absolute; top: 0; left: 16px; right: 16px; border-top: 1px solid rgba(128,128,128,0.13); }\n.ex-v2 .ex-item:active { opacity: 0.55; }\n.ex-v2 .ex-item audio { display: none; }\n/* no-JS fallback: the separator stored in the fields still reads as a rule */\n.example hr.ex-sep { border: none; border-top: 1px solid rgba(128,128,128,0.13); margin: 8px 0; }\n.nightMode .ex-v2 .ex-item + .ex-item::before, .nightMode .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .ex-v2 .ex-item + .ex-item::before, .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); } }\n\n/* --- kanji entries (re-laid out by the template script; .kb-v2 is added once that has run) --- */\n.kb-v2 .k-brk { line-height: 1.45; }\n.kb-v2 .k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kb-v2 .k-head2 { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 5px; }\n.kb-v2 .k-readings { flex: 1 1 auto; min-width: 0; display: block; font-size: 0.95em; line-height: 1.4; }\n.kb-v2 .k-reading2 { display: flex; align-items: baseline; gap: 6px; color: #222; font-size: 1.02em; line-height: 1.5; }\n.kb-v2 .k-lab { flex: none; min-width: 2.4em; font-size: 0.68em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.kb-v2 .k-vals { color: #222; }\n.kb-v2 .k-r { white-space: nowrap; }\n.kb-v2 .k-mean2 { font-weight: 500; font-size: 1em; color: #222; line-height: 1.35; margin: 0; }\n.kb-v2 .k-stats2 { float: right; display: flex; flex-direction: column; align-items: flex-end; gap: 7px; margin-left: 12px; min-width: 2.2em; }\n.kb-v2 .k-sv { font-weight: 700; font-size: 0.8em; color: #8c8c8c; line-height: 1; letter-spacing: 0.02em; white-space: nowrap; }\n.kb-v2 .k-unit { font-size: 0.9em; font-weight: 600; margin-left: 1px; }\n.kb-v2 .k-brk a.k-nih { font-weight: 800; font-size: 1.35em; line-height: 1; color: #1f665b !important; text-decoration: none !important; padding: 0 0 2px; margin: -2px 0 2px; border-bottom: 2px dotted #1f665b; -webkit-tap-highlight-color: transparent; }\n.kb-v2 .k-brk a.k-nih:active { background: rgba(31,102,91,0.15); }\n\n/* --- on/kun readings tap to play their clip (class added by the template script); dotted underline = tappable --- */\n.kb-v2 .k-r.k-r-tap { cursor: pointer; text-decoration: underline dotted #a9a9a9; text-decoration-thickness: 1.5px; text-underline-offset: 4px; padding: 5px 2px; margin: 0 -2px; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.kb-v2 .k-r.k-r-tap:active { opacity: 0.55; }\n.kb-v2 .k-r.k-r-tap.playing { color: #1f665b; text-decoration-color: #1f665b; }\n.nightMode .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; }\n.nightMode .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; }\n@media (prefers-color-scheme: dark) { .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; } .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; } }\n\n/* --- every tap target: no double-tap zoom / 300 ms click delay on iOS --- */\n.word-block, .ex-v2 .ex-item, .kb-v2 .k-box, .kb-v2 .k-r.k-r-tap, .kb-v2 .k-head2, .card a.wordinfo-nih, .kb-v2 .k-brk a.k-nih { touch-action: manipulation; }\n\n/* --- the kanji grid box --- */\n.kb-v2 .k-box { position: relative; flex: none; width: 66px; height: 66px; box-sizing: border-box; border: 1.5px dotted #d2d2d2; border-radius: 4px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; --k-ink: #1f1f1f; --k-ghost: #bdbdbd; --k-grid: #c4c4c4; --k-dot: #49c248; }\n.kb-v2 .k-box:active { background: rgba(31,102,91,0.06); }\n.kb-v2 .k-fallback { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 40px; line-height: 1; color: #1f1f1f; }\n.kb-v2 .k-box.has-svg .k-fallback { display: none; }\n.kb-v2 .k-svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }\n.kb-v2 .k-grid line { stroke: var(--k-grid); stroke-width: 1.2; stroke-dasharray: 2 3; vector-effect: non-scaling-stroke; }\n.kb-v2 .k-ghost path { fill: none; stroke: var(--k-ghost); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; opacity: 0; transition: opacity 0.15s; }\n.kb-v2 .k-box.animating .k-ghost path { opacity: 1; }\n.kb-v2 .k-ink path { fill: none; stroke: var(--k-ink); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; }\n.kb-v2 .k-dot { fill: var(--k-dot); opacity: 0; transition: opacity 0.25s; }\n.kb-v2 .k-box.animating .k-dot, .kb-v2 .k-box.done .k-dot { opacity: 1; }\n.kb-v2 .k-play { position: absolute; right: -8px; bottom: -8px; width: 18px; height: 18px; border-radius: 50%; background: #efefef; color: #5a5a5a; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 0 2px #f5f5f5; cursor: pointer; z-index: 1; }\n.kb-v2 .k-play svg { width: 12px; height: 12px; margin-left: 2px; }\n.kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #dcdcdc; }\n.kb-v2 .k-box.animating .k-play { opacity: 0.55; }\n\n/* --- tap guard, answer side only (templates/tap_guard.js): taps on the card never reach AnkiMobile's tap zones.\n   The shield is a transparent full-screen layer behind the card, so the empty space around a short card is covered too --- */\n.tap-shield { position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 0; background: transparent; -webkit-tap-highlight-color: transparent; }\n.card[data-notap] { position: relative; z-index: 1; -webkit-tap-highlight-color: transparent; }\n\n/* --- narrow screens (iPhone): trim the side margins; wider screens keep max-width 600 + 20px padding --- */\n@media (max-width: 480px) {\n  body { margin-left: 0; margin-right: 0; }\n  .card { padding: 14px 12px 24px; }\n}\n\n/* dark (Anki .nightMode) */\n.nightMode .front-word-ruby .fw-read, .nightMode .front-word-ruby .fr { color: #f0826e; }\n.nightMode .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n.nightMode .wordinfo-pos { color: #8f8f8f; }\n.nightMode .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n.nightMode .kb-v2 .k-reading2, .nightMode .kb-v2 .k-vals { color: #e6e6e6; }\n.nightMode .kb-v2 .k-lab { color: #8a8a8a; }\n.nightMode .kb-v2 .k-mean2 { color: #e6e6e6; }\n.nightMode .kb-v2 .k-sv { color: #8f8f8f; }\n.nightMode .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n.nightMode .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n.nightMode .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n.nightMode .kb-v2 .k-fallback { color: #f2f2f2; }\n.nightMode .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n.nightMode .kb-v2 .k-box:active .k-play, .nightMode .kb-v2 .k-play:active { background: #4a4a4a; }\n\n/* dark (system) */\n@media (prefers-color-scheme: dark) {\n  .front-word-ruby .fw-read, .front-word-ruby .fr { color: #f0826e; }\n  .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n  .wordinfo-pos { color: #8f8f8f; }\n  .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n  .kb-v2 .k-reading2, .kb-v2 .k-vals { color: #e6e6e6; }\n  .kb-v2 .k-lab { color: #8a8a8a; }\n  .kb-v2 .k-mean2 { color: #e6e6e6; }\n  .kb-v2 .k-sv { color: #8f8f8f; }\n  .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n  .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n  .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n  .kb-v2 .k-fallback { color: #f2f2f2; }\n  .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n  .kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #4a4a4a; }\n}\n\n/* Answer-only compact reveal. Fronts and unillustrated cards keep their layout. */\n/* Anki can paint inserted HTML before evaluating its template scripts.\n   Suppress that intermediate layout, but automatically show it after 700ms\n   even if scripts fail. Never depend on JavaScript to make a card readable. */\n.card[data-notap]:has(.vocab-visual):not(.visual-ready) {\n  animation: visual-prepare-fallback 700ms step-end both;\n}\n@keyframes visual-prepare-fallback { from { opacity: 0; } to { opacity: 1; } }\n.vocab-visual { margin: 0; text-align: center; }\n.card.has-vocab-visual > .vocab-visual {\n  margin: -24px 0 0;\n  /* Reserve the final banner height; animate the artwork, not a clipping mask. */\n  overflow: visible;\n}\n.vocab-visual img {\n  display: block;\n  width: 100%;\n  max-width: 480px;\n  height: auto;\n  aspect-ratio: 3 / 1;\n  object-fit: contain;\n  box-sizing: border-box;\n  padding: 4% 6%;\n  margin: 0 auto;\n  border-radius: 0;\n  transform-origin: center center;\n\n}\n.card.visual-ready .vocab-visual img {\n  animation: visual-entrance 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.has-vocab-visual .front-word-ruby {\n  font-size: 32px;\n  line-height: 1.35;\n  /* Furigana occupies the gap; image padding already supplies breathing room. */\n  margin: 14px 0 0;\n  text-align: center;\n  transform-origin: center center;\n\n}\n.card.has-vocab-visual .meaning { font-size: 18px; line-height: 1.35; margin: 2px 0 0; }\n/* Keep the shared light/dark gradient behind the compact meaning and POS. */\n.card.has-vocab-visual .wordinfo { margin: -32px 0 0; padding: 38px 16px 10px; }\n.card.has-vocab-visual.prod .front-english { font-size: 22px; line-height: 1.3; margin: 6px 0 0; }\n.card.has-vocab-visual.prod .front-word-ruby { margin-top: 16px; }\n.card.has-vocab-visual .example { margin-top: 6px; }\n/* One moving answer block preserves every internal spacing relationship. */\n.visual-content { display: flow-root; }\n.card.visual-ready .visual-content {\n  animation: visual-content-slide 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready:not(.prod) .front-word-ruby {\n  animation: visual-word 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready .meaning,\n.card.visual-ready .wordinfo,\n.card.visual-ready .example,\n.card.visual-ready .kanji-breakdown,\n.card.visual-ready .fw-read,\n.card.visual-ready .fr {\n  animation: visual-details 400ms ease-out 100ms both;\n}\n.card.visual-ready.prod .front-english {\n  animation: visual-english 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n@keyframes visual-english { from { font-size: 34px; line-height: 1.6; color: var(--visual-cue-start, #111); } to { font-size: 22px; line-height: 1.3; color: var(--visual-cue-end, #8c8c8c); } }\n@keyframes visual-details { from { opacity: 0; } to { opacity: 1; } }\n@keyframes visual-content-slide {\n  from { transform: translateY(var(--visual-content-start, -100px)); }\n  to { transform: translateY(0); }\n}\n@keyframes visual-entrance {\n  from { opacity: 0; transform: translateY(-100%) scale(.94); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n@keyframes visual-word { from { transform: scale(1.4375); } to { transform: scale(1); } }\n@media (max-width: 480px) {\n  .card.has-vocab-visual > .vocab-visual { margin: -14px 0 0; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .card.has-vocab-visual > .vocab-visual,\n  .card.has-vocab-visual .vocab-visual img,\n  .card.visual-ready .visual-content,\n  .card.has-vocab-visual .fr,\n  .card.has-vocab-visual .fw-read,\n  .card.visual-ready:not(.prod) .front-word-ruby,\n  .card.visual-ready.prod .front-english,\n  .card.has-vocab-visual .meaning,\n  .card.has-vocab-visual .wordinfo,\n  .card.has-vocab-visual .example,\n  .card.has-vocab-visual .kanji-breakdown,\n  .card.has-vocab-visual.prod .front-english { animation: none; }\n}\n\n/* De-emphasize the English cue only after revealing a Production answer. */\n.card.prod:has(.wordinfo) .front-english { color: #8c8c8c; }\n.nightMode .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n}\n\n/* Carry the question color through the shrink instead of swapping it on reveal. */\n.nightMode .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n}\n.card.visual-ready.prod .word-block { animation: visual-details 400ms ease-out 100ms both; }\n@media (prefers-reduced-motion: reduce) {\n  .card.visual-ready.prod .word-block { animation: none; }\n}\n\nhtml,body{margin:0;padding:0;background:transparent}.card{padding-top:0;padding-bottom:16px;display:flow-root}.tap-shield{display:none}.word-block{cursor:pointer}\n</style></head><body><script src=\"_kanji_strokes.js\"></script>\n<div class=\"tap-shield tappable\" onclick=\"void 0\"></div>\n<div class=\"card tappable has-vocab-visual\" data-notap onclick=\"void 0\">\n<div class=\"word-block tap-play\" onclick=\"event.stopPropagation();var b=this.parentNode.querySelector('.word-audio-hidden a');if(b)b.click();\">\n<div class=\"front-word front-word-ruby\"><span class=\"fw-base\">時計</span><span class=\"fw-read\">とけい</span></div>\n<div class=\"meaning\">watch; clock</div>\n</div>\n<div class=\"word-audio-hidden\"><a href=\"#\" onclick=\"event.preventDefault();this.nextElementSibling.currentTime=0;this.nextElementSibling.play()\">Play</a><audio src=\"n5_wd_0065385ff4b92ab3.mp3\"></audio></div>\n<div class=\"wordinfo\">\n<div class=\"wordinfo-pos\">Noun</div>\n<a class=\"wordinfo-nih\" href=\"https://nihongo-app.com/dictionary/word/時計\">語</a>\n</div>\n<div class=\"example tap-play-ex\" onclick=\"event.stopPropagation();var a=this.querySelector('audio');if(a){a.currentTime=0;a.play();}\">\n<div class=\"example-ja\"><ruby>時計<rt>とけい</rt></ruby>を <ruby>見<rt>み</rt></ruby>てください。<hr class=\"ex-sep\"><ruby>部屋<rt>へや</rt></ruby>の <ruby>時計<rt>とけい</rt></ruby>が <ruby>止<rt>と</rt></ruby>まっています。</div>\n<div class=\"example-en\">Please look at the clock.<hr class=\"ex-sep\">The clock in my room has stopped.</div>\n<div class=\"audio example-audio\"><audio src=\"n5_ex_36f59f7aea98ee07.mp3\" preload=\"none\"></audio><audio src=\"n5_ex_81204e9f4565c936.mp3\" preload=\"none\"></audio></div>\n</div>\n\n<div class=\"kanji-breakdown\">\n<div class=\"kb-content\"><div class=\"k-brk\">\n  <div class=\"k-head\"><a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji/時\"><span class=\"k-char\">時</span></a><span class=\"k-stats\"><span class=\"k-stat\"><span class=\"k-stat-v\">10</span><span class=\"k-stat-l\">Strokes</span></span><span class=\"k-stat\"><span class=\"k-stat-v\">N4</span><span class=\"k-stat-l\">JLPT</span></span></span></div>\n  <div class=\"k-mean\">time, hour</div>\n  <div class=\"k-reading\"><span class=\"k-label\">On:</span> <span class=\"k-r\">ジ</span></div>\n  <div class=\"k-reading\"><span class=\"k-label\">Kun:</span> <span class=\"k-r\">とき</span>, <span class=\"k-r\">どき</span></div>\n  <div class=\"k-radical\"><span class=\"k-label\">Radical:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/日\">日</a> (nichi, sun)</div>\n  <div class=\"k-components\"><span class=\"k-label\">Components:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/寸\">寸</a> measurement, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/土\">土</a> soil, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/日\">日</a> day</div>\n</div>\n<div class=\"k-brk\">\n  <div class=\"k-head\"><a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji/計\"><span class=\"k-char\">計</span></a><span class=\"k-stats\"><span class=\"k-stat\"><span class=\"k-stat-v\">9</span><span class=\"k-stat-l\">Strokes</span></span><span class=\"k-stat\"><span class=\"k-stat-v\">N3</span><span class=\"k-stat-l\">JLPT</span></span></span></div>\n  <div class=\"k-mean\">plot, plan, scheme</div>\n  <div class=\"k-reading\"><span class=\"k-label\">On:</span> <span class=\"k-r\">ケイ</span></div>\n  <div class=\"k-reading\"><span class=\"k-label\">Kun:</span> <span class=\"k-r\">はか(る)</span>, <span class=\"k-r\">はか(らう)</span></div>\n  <div class=\"k-radical\"><span class=\"k-label\">Radical:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/言\">言</a> (kotoba, speech)</div>\n  <div class=\"k-components\"><span class=\"k-label\">Components:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/言\">言</a> say, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/十\">十</a> ten</div>\n</div></div>\n</div>\n\n<span class=\"visual-key\" hidden>時計|とけい</span>\n<span class=\"dictionary-key\" hidden>時計|とけい|watch; clock</span>\n<script>\n(function(){\n  var NS = 'http://www.w3.org/2000/svg';\n  var KANJI_RE = /[㐀-鿿豈-﫿々]/;\n  function el(tag, attrs){ var e = document.createElementNS(NS, tag); for (var k in attrs) e.setAttribute(k, attrs[k]); return e; }\n  function txt(n){ return n ? (n.textContent || '').replace(/\\s+/g, ' ').trim() : ''; }\n  function stop(e){ e.stopPropagation(); }\n  function guard(node){ node.addEventListener('click', stop, false); node.addEventListener('touchend', stop, false); }\n  /* run fn on a tap. iOS drops the click after a touch that stops a momentum scroll or that it takes for a double-tap,\n     so on touch devices we act on touchend of an unmoved touch and suppress the synthetic click; mouse/desktop use click */\n  function tap(node, fn){\n    var sx = 0, sy = 0, moved = true, handled = false;\n    node.addEventListener('touchstart', function(e){ var t = e.touches[0]; if (!t || e.touches.length > 1) { moved = true; return; } sx = t.clientX; sy = t.clientY; moved = false; handled = false; }, {passive: true});\n    node.addEventListener('touchmove', function(e){ var t = e.touches[0]; if (!t || Math.abs(t.clientX - sx) > 12 || Math.abs(t.clientY - sy) > 12) moved = true; }, {passive: true});\n    node.addEventListener('touchend', function(e){ if (moved) return; moved = true; handled = true; if (e.cancelable) e.preventDefault(); fn(); }, {passive: false});\n    node.addEventListener('touchcancel', function(){ moved = true; }, {passive: true});\n    node.addEventListener('click', function(){ if (handled) { handled = false; return; } fn(); }, false);\n  }\n  // scope everything to the card this script lives in (falls back to the last card on the page)\n  var root = null, cs = document.currentScript;\n  if (cs && cs.closest) root = cs.closest('.card');\n  if (!root) { var cards = document.querySelectorAll('.card'); root = cards.length ? cards[cards.length - 1] : document; }\n\n  /* ---- align a kana reading to the kanji runs of a word: お願いします + おねがいします -> お<ruby>願<rt>ねが</rt></ruby>います ---- */\n  function toHira(s){ return s.replace(/[ァ-ヶ]/g, function(c){ return String.fromCharCode(c.charCodeAt(0) - 0x60); }); }\n  function isKanji(c){ return KANJI_RE.test(c); }\n  function isKana(c){ return /[ぁ-ゟ゠-ヿ]/.test(c); }\n  function esc(s){ return s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&'); }\n  function alignFurigana(word, reading){\n    reading = (reading || '').replace(/\\s+/g, '');\n    if (word.indexOf('(') < 0) reading = reading.replace(/[（(][^)）]*[)）]/g, '');\n    if (word.indexOf('/') < 0 && reading.indexOf('/') >= 0) reading = reading.split('/')[0];\n    var hira = toHira(reading);\n    // split the word into runs: kanji / kana / other\n    var runs = [], i, c, t, cur = null;\n    for (i = 0; i < word.length; i++) {\n      c = word.charAt(i); t = isKanji(c) ? 'k' : (isKana(c) ? 'a' : 'o');\n      if (c === '々' && cur && cur.t === 'k') t = 'k';\n      if (cur && cur.t === t) cur.s += c; else { cur = {t:t, s:c}; runs.push(cur); }\n    }\n    var kanjiRuns = 0; for (i = 0; i < runs.length; i++) if (runs[i].t === 'k') kanjiRuns++;\n    if (!kanjiRuns) return null;\n    var pat = '^';\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') pat += '(.+?)';\n      else if (runs[i].t === 'a') pat += esc(toHira(runs[i].s));\n      else pat += '(?:' + esc(runs[i].s) + ')?';\n    }\n    pat += '$';\n    var m = hira.match(new RegExp(pat));\n    if (!m) return null;\n    var out = [], gi = 1, pos = 0;\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') {\n        // take the kana slice from the original reading (keeps katakana if it was katakana)\n        var idx = hira.indexOf(m[gi], pos); if (idx < 0) return null;\n        out.push({kanji: runs[i].s, kana: reading.substr(idx, m[gi].length)});\n        pos = idx + m[gi].length; gi++;\n      } else { out.push({text: runs[i].s}); if (runs[i].t === 'a') pos += runs[i].s.length; }\n    }\n    return out;\n  }\n  function fk(kanji, kana){\n    var s = document.createElement('span'); s.className = 'fk'; s.appendChild(document.createTextNode(kanji));\n    var r = document.createElement('span'); r.className = 'fr'; r.textContent = kana; s.appendChild(r);\n    return s;\n  }\n  function renderFurigana(container, word, reading){\n    var parts = alignFurigana(word, reading);\n    if (!parts) return false;\n    while (container.firstChild) container.removeChild(container.firstChild);\n    for (var i = 0; i < parts.length; i++) {\n      if (parts[i].kanji) container.appendChild(fk(parts[i].kanji, parts[i].kana));\n      else container.appendChild(document.createTextNode(parts[i].text));\n    }\n    return true;\n  }\n  function renderWhole(container, word, reading){\n    while (container.firstChild) container.removeChild(container.firstChild);\n    if (reading) container.appendChild(fk(word, reading)); else container.appendChild(document.createTextNode(word));\n  }\n\n  /* ---- 1. furigana over the word: only over the kanji, hung above the glyphs so the word sits exactly where it does on the front ---- */\n  var fw = root.querySelector('.front-word-ruby');\n  if (fw) {\n    var baseEl = fw.querySelector('.fw-base'), readEl = fw.querySelector('.fw-read');\n    var base = txt(baseEl), reading = txt(readEl);\n    if (!KANJI_RE.test(base) || reading === base || !reading) renderWhole(fw, base, '');\n    else if (!renderFurigana(fw, base, reading)) renderWhole(fw, base, reading);\n  }\n\n  /* ---- 2. audio tap targets must never reach the card's tap gestures ---- */\n  var taps = root.querySelectorAll('.tap-play, .tap-play-ex, .wordinfo-nih');\n  for (var i = 0; i < taps.length; i++) guard(taps[i]);\n\n  /* ---- 2b. example sentences: the fields may hold two sentences separated by <hr class=\"ex-sep\">.\n     Re-lay them out as list items (.ex-item = Japanese + English + its own clip); the WHOLE item,\n     padding included, is the tap target, and nothing inside the red card ever reaches Anki's tap gestures ---- */\n  var ex = root.querySelector('.example');\n  if (ex && !ex.classList.contains('ex-v2')) {\n    var splitAtHr = function(node){\n      var groups = [[]]; if (!node) return groups;\n      var n = node.firstChild;\n      while (n) { var nx = n.nextSibling; if (n.nodeType === 1 && n.tagName === 'HR') groups.push([]); else groups[groups.length - 1].push(n); n = nx; }\n      return groups;\n    };\n    var jaG = splitAtHr(ex.querySelector('.example-ja')), enG = splitAtHr(ex.querySelector('.example-en'));\n    var auds = ex.querySelectorAll('audio'), items = [], g, k;\n    for (g = 0; g < jaG.length; g++) {\n      var item = document.createElement('div'); item.className = 'ex-item'; item.setAttribute('role', 'button');\n      var ja = document.createElement('div'); ja.className = 'example-ja';\n      for (k = 0; k < jaG[g].length; k++) ja.appendChild(jaG[g][k]);\n      item.appendChild(ja);\n      if (enG[g]) { var en = document.createElement('div'); en.className = 'example-en'; for (k = 0; k < enG[g].length; k++) en.appendChild(enG[g][k]); item.appendChild(en); }\n      if (auds[g]) item.appendChild(auds[g]);\n      items.push(item);\n    }\n    while (ex.firstChild) ex.removeChild(ex.firstChild);\n    ex.removeAttribute('onclick'); ex.onclick = null;\n    ex.classList.remove('tap-play-ex'); ex.classList.add('ex-v2');\n    var playItem = function(item){\n      var all = ex.querySelectorAll('audio'), mine = item.querySelector('audio');\n      for (var a = 0; a < all.length; a++) if (all[a] !== mine) { try { all[a].pause(); all[a].currentTime = 0; } catch (e) {} }\n      if (mine) { try { mine.currentTime = 0; } catch (e) {} var pr = mine.play(); if (pr && pr.catch) pr.catch(function(){}); }\n    };\n    for (g = 0; g < items.length; g++) {\n      ex.appendChild(items[g]); guard(items[g]);\n      (function(it){ tap(it, function(){ playItem(it); }); })(items[g]);\n    }\n  }\n\n  /* ---- 3. re-lay out each kanji breakdown entry (field markup stays unchanged) ---- */\n  var kb = root.querySelector('.kanji-breakdown');\n  if (kb && !kb.classList.contains('kb-v2')) {\n    var brks = kb.querySelectorAll('.k-brk');\n    for (var b = 0; b < brks.length; b++) relayout(brks[b]);\n    kb.classList.add('kb-v2');\n\n    /* ---- 3b. tappable on/kun readings: each .k-r plays `_kr_<hex of the hiragana reading>.mp3`\n       (a _-prefixed template media file; okurigana marks, dots and hyphens are dropped, katakana -> hiragana).\n       The whole head row swallows taps so a near miss never flips the card. ---- */\n    var krAudio = null;\n    var krFile = function(t){\n      var sp = toHira(t.replace(/[-.()（）\\s‐－]/g, '')), hex = '';\n      if (!sp || !/^[ぁ-ゖー]+$/.test(sp)) return null;\n      for (var i = 0; i < sp.length; i++) hex += ('0000' + sp.charCodeAt(i).toString(16)).slice(-4);\n      return '_kr_' + hex + '.mp3';\n    };\n    var playKr = function(node, file){\n      if (!krAudio) { krAudio = document.createElement('audio'); krAudio.setAttribute('preload', 'none'); krAudio.style.display = 'none'; root.appendChild(krAudio); }\n      var others = root.querySelectorAll('.example audio');\n      for (var o = 0; o < others.length; o++) { try { others[o].pause(); } catch (e) {} }\n      var on = kb.querySelectorAll('.k-r.playing'); for (var q = 0; q < on.length; q++) on[q].classList.remove('playing');\n      node.classList.add('playing'); setTimeout(function(){ node.classList.remove('playing'); }, 700);\n      try { krAudio.pause(); krAudio.src = file; krAudio.currentTime = 0; } catch (e) {}\n      var pr = krAudio.play(); if (pr && pr.catch) pr.catch(function(){});\n    };\n    var krs = kb.querySelectorAll('.k-r');\n    for (var r2 = 0; r2 < krs.length; r2++) (function(node){\n      var file = krFile(txt(node)); if (!file) return;\n      node.classList.add('k-r-tap'); node.setAttribute('role', 'button');\n      guard(node); tap(node, function(){ playKr(node, file); });\n    })(krs[r2]);\n    var heads = kb.querySelectorAll('.k-head2'); for (var h2 = 0; h2 < heads.length; h2++) guard(heads[h2]);\n  }\n\n  function relayout(brk){\n    var ch = txt(brk.querySelector('.k-char'));\n    if (!ch) return;\n    var link = brk.querySelector('.k-head a');\n    var href = (link && link.getAttribute('href')) || ('https://nihongo-app.com/dictionary/kanji/' + ch);\n    var strokes = '', jlpt = '';\n    var stats = brk.querySelectorAll('.k-stat');\n    for (var s = 0; s < stats.length; s++) {\n      var lab = txt(stats[s].querySelector('.k-stat-l')).toLowerCase(), v = txt(stats[s].querySelector('.k-stat-v'));\n      if (lab.indexOf('stroke') === 0) strokes = v; else if (lab.indexOf('jlpt') === 0) jlpt = v;\n    }\n    var meanText = txt(brk.querySelector('.k-mean'));\n    var readings = brk.querySelectorAll('.k-reading');\n\n    var head = document.createElement('div'); head.className = 'k-head2';\n    var box = document.createElement('div'); box.className = 'k-box'; box.setAttribute('data-kanji', ch); box.setAttribute('role', 'button');\n    var fb = document.createElement('span'); fb.className = 'k-fallback'; fb.textContent = ch; box.appendChild(fb);\n    var play = document.createElement('span'); play.className = 'k-play';\n    play.innerHTML = '<svg viewBox=\"0 0 12 12\"><path d=\"M3.6 2.2 L10 6 L3.6 9.8 Z\" fill=\"currentColor\"/></svg>';\n    box.appendChild(play);\n    head.appendChild(box);\n\n    var col = document.createElement('div'); col.className = 'k-readings';\n    var st = document.createElement('span'); st.className = 'k-stats2';\n    var nih = document.createElement('a'); nih.className = 'k-nih'; nih.href = href; nih.textContent = '語'; st.appendChild(nih);\n    if (strokes) { var sv = document.createElement('span'); sv.className = 'k-sv'; sv.innerHTML = strokes + '<span class=\"k-unit\">画</span>'; st.appendChild(sv); }\n    if (jlpt) { var jv = document.createElement('span'); jv.className = 'k-sv'; jv.textContent = jlpt; st.appendChild(jv); }\n    col.appendChild(st);\n    for (var r = 0; r < readings.length; r++) {\n      var src = readings[r], label = src.querySelector('.k-label');\n      var row = document.createElement('div'); row.className = 'k-reading2';\n      var lab2 = document.createElement('span'); lab2.className = 'k-lab'; lab2.textContent = txt(label).replace(/:$/, ''); row.appendChild(lab2);\n      var vals = document.createElement('span'); vals.className = 'k-vals';\n      var n = src.firstChild;\n      while (n) { var next = n.nextSibling; if (n !== label) vals.appendChild(n); n = next; }\n      row.appendChild(vals); col.appendChild(row);\n    }\n    head.appendChild(col);\n\n    var mean = document.createElement('div'); mean.className = 'k-mean2'; mean.textContent = meanText;\n\n    while (brk.firstChild) brk.removeChild(brk.firstChild);\n    brk.appendChild(head); brk.appendChild(mean);\n    guard(box); guard(nih);\n    tap(box, function(){ animate(box); });\n  }\n\n  /* ---- 4. stroke-order boxes (KanjiVG paths from _kanji_strokes.js) ---- */\n  function buildBox(box){\n    var strokes = window.KANJI_STROKES[box.getAttribute('data-kanji')];\n    if (!strokes || !strokes.length) return;\n    var svg = el('svg', {viewBox:'-7 -7 123 123', 'class':'k-svg', 'aria-hidden':'true'});\n    var grid = el('g', {'class':'k-grid'});\n    grid.appendChild(el('line', {x1:54.5, y1:-5, x2:54.5, y2:114}));\n    grid.appendChild(el('line', {x1:-5, y1:54.5, x2:114, y2:54.5}));\n    svg.appendChild(grid);\n    var ghost = el('g', {'class':'k-ghost'}), ink = el('g', {'class':'k-ink'}), paths = [];\n    for (var i = 0; i < strokes.length; i++) {\n      ghost.appendChild(el('path', {d:strokes[i]}));\n      var p = el('path', {d:strokes[i]}); ink.appendChild(p); paths.push(p);\n    }\n    svg.appendChild(ghost); svg.appendChild(ink);\n    var dot = el('circle', {'class':'k-dot', r:5.2, cx:-20, cy:-20});\n    svg.appendChild(dot);\n    box.insertBefore(svg, box.firstChild);\n    box.classList.add('has-svg');\n    box._k = {paths:paths, dot:dot, raf:0, timer:0};\n  }\n  function cancel(box){\n    var s = box._k; if (!s) return;\n    if (s.raf) cancelAnimationFrame(s.raf); s.raf = 0;\n    if (s.timer) clearTimeout(s.timer); s.timer = 0;\n    box.classList.remove('animating'); box.classList.remove('done');\n  }\n  function animate(box){\n    if (!box._k && window.KANJI_STROKES) buildBox(box);   // asset arrived after this box was laid out\n    var s = box._k; if (!s) return;\n    cancel(box);\n    var lens = [], i, p;\n    for (i = 0; i < s.paths.length; i++) { lens.push(s.paths[i].getTotalLength()); }\n    for (i = 0; i < s.paths.length; i++) { p = s.paths[i]; p.style.strokeDasharray = lens[i] + ' ' + lens[i]; p.style.strokeDashoffset = lens[i]; }\n    box.classList.add('animating');\n    var idx = 0, t0 = 0, GAP = 70;\n    function dur(len){ return Math.max(170, 90 + len * 4.6); }\n    function ease(t){ return 1 - Math.pow(1 - t, 1.5); }\n    function step(ts){\n      if (!t0) t0 = ts;\n      var q = s.paths[idx], len = lens[idx], t = Math.min(1, (ts - t0) / dur(len)), e = ease(t);\n      q.style.strokeDashoffset = len * (1 - e);\n      var pt = q.getPointAtLength(len * e);\n      s.dot.setAttribute('cx', pt.x); s.dot.setAttribute('cy', pt.y);\n      if (t < 1) { s.raf = requestAnimationFrame(step); return; }\n      idx++; t0 = 0;\n      if (idx < s.paths.length) {\n        s.timer = setTimeout(function(){ s.timer = 0; s.raf = requestAnimationFrame(step); }, GAP);\n      } else {\n        box.classList.remove('animating'); box.classList.add('done');\n        s.timer = setTimeout(function(){ s.timer = 0; box.classList.remove('done'); }, 650);\n      }\n    }\n    var p0 = s.paths[0].getPointAtLength(0); s.dot.setAttribute('cx', p0.x); s.dot.setAttribute('cy', p0.y);\n    s.raf = requestAnimationFrame(step);\n  }\n  var tries = 0;\n  function fill(){\n    if (window.KANJI_STROKES) {\n      var boxes = root.querySelectorAll('.k-box:not(.has-svg)');\n      for (var i = 0; i < boxes.length; i++) buildBox(boxes[i]);\n    } else if (tries++ < 150) { setTimeout(fill, tries < 20 ? 50 : 200); }   // external asset may still be loading (waits up to ~27 s)\n  }\n  fill();\n  // if the asset script is still in flight, fill as soon as it lands (covers WebViews that load it asynchronously)\n  var ks = document.querySelectorAll('script[src*=\"_kanji_strokes\"]');\n  for (var si = 0; si < ks.length; si++) ks[si].addEventListener('load', fill, false);\n})();\n\n</script>\n<script>\n\n</script>\n</div>\n</body></html>"}, {"word": "自転車", "reading": "じてんしゃ", "image": "media/vocab-7d4ecf553485.webp", "audio": "media/n5_wd_b052e808f33626b1.mp3", "doc": "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><base href=\"media/\"><style>/* ===== BASE / LIGHT MODE ===== */\n.card {\n  font-family: 'SF Pro Display', 'SF Pro Text', -apple-system, BlinkMacSystemFont,\n               'Hiragino Sans', 'Hiragino Kaku Gothic ProN', system-ui, sans-serif;\n  text-align: center;\n  padding: 24px 20px;\n  line-height: 1.6;\n  background: #ffffff;\n  color: #1a1a1a;\n  max-width: 600px;\n  margin: 0 auto;\n}\n.front-word {\n  font-size: 46px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n  letter-spacing: 0.02em;\n}\n.front-english {\n  font-size: 34px;\n  font-weight: 700;\n  margin: 24px 0 16px;\n  color: #111;\n}\n.reading {\n  font-size: 26px;\n  color: #d63964;\n  margin: 8px 0;\n  font-weight: 500;\n}\n.meaning {\n  font-size: 22px;\n  color: #1a5276;\n  margin: 8px 0;\n  font-weight: 600;\n}\n.pos-tag {\n  display: inline-block;\n  background-color: #2c3e50;\n  color: #fff;\n  padding: 4px 14px;\n  border-radius: 14px;\n  font-size: 13px;\n  margin: 6px 0;\n  letter-spacing: 0.03em;\n}\n.example {\n  margin: 18px 0 8px;\n  padding: 14px 16px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #d63964;\n}\n.example-ja {\n  font-size: 19px;\n  color: #222;\n  margin-bottom: 6px;\n  line-height: 1.7;\n}\n.example-ja ruby rt {\n  line-height: 1;\n  font-size: 0.55em;\n  color: #888;\n  font-weight: 400;\n}\n.example-en {\n  font-size: 15px;\n  color: #555;\n  font-style: italic;\n  line-height: 1.45;\n}\n.divider {\n  border: none;\n  border-top: 1px solid #e0e0e0;\n  margin: 16px 0;\n}\n.hint {\n  font-size: 14px;\n  color: #999;\n  margin-top: 12px;\n  letter-spacing: 0.02em;\n}\n.audio {\n  margin: 8px 0;\n}\n\n/* --- Example card: even out top/bottom (furigana rides in the 1.7 line-height leading; hidden <audio> wrapper added 8px) --- */\n.example { padding-top: 10px; padding-bottom: 12px; }\n.example .example-ja { margin-bottom: 0; }\n.example .audio.example-audio { margin: 0; }\n\n/* --- Kanji breakdown (always open, matches .example card, blue accent) --- */\n.kanji-breakdown {\n  margin: 14px 0 8px;\n  padding: 14px 16px 12px;\n  background: #f5f5f5;\n  border-radius: 10px;\n  text-align: left;\n  border-left: 3px solid #1fa77c;\n}\n.kanji-breakdown .kb-content {\n  font-size: 15px;\n  line-height: 1.9;\n  color: #444;\n}\n\n/* ===== DARK MODE: Anki .nightMode class ===== */\n.nightMode .card,\n.nightMode.card {\n  background: #1e1e1e;\n  color: #e0e0e0;\n}\n.nightMode .front-word { color: #f0f0f0; }\n.nightMode .front-english { color: #f0f0f0; }\n.nightMode .reading { color: #f0826e; }\n.nightMode .meaning { color: #6cb4ee; }\n.nightMode .pos-tag { background-color: #3a3f4b; color: #ccc; }\n.nightMode .example { background: #2a2a2a; border-left-color: #f0826e; }\n.nightMode .example-ja { color: #ddd; }\n.nightMode .example-ja ruby rt { color: #aaa; }\n.nightMode .example-en { color: #b0b0b0; }\n.nightMode .divider { border-top-color: #3a3a3a; }\n.nightMode .hint { color: #777; }\n.nightMode .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n.nightMode .kanji-breakdown .kb-content { color: #bbb; }\n\n/* ===== DARK MODE: prefers-color-scheme ===== */\n@media (prefers-color-scheme: dark) {\n  .card { background: #1e1e1e; color: #e0e0e0; }\n  .front-word { color: #f0f0f0; }\n  .front-english { color: #f0f0f0; }\n  .reading { color: #f0826e; }\n  .meaning { color: #6cb4ee; }\n  .pos-tag { background-color: #3a3f4b; color: #ccc; }\n  .example { background: #2a2a2a; border-left-color: #f0826e; }\n  .example-ja { color: #ddd; }\n  .example-ja ruby rt { color: #aaa; }\n  .example-en { color: #b0b0b0; }\n  .divider { border-top-color: #3a3a3a; }\n  .hint { color: #777; }\n  .kanji-breakdown { background: #2a2a2a; border-left-color: #3ed3a4; }\n  .kanji-breakdown .kb-content { color: #bbb; }\n}\n\n\n/* --- Audio replay button (matches kanji-breakdown pill) --- */\n.audio.player {\n  margin-top: 14px;\n}\n\n.replay-button {\n  display: flex;\n  justify-content: center;\n  align-items: center; \n  margin: 12px auto;\n  padding: 8px 18px;\n  min-width: 44px;\n  min-height: 44px;\n  box-sizing: border-box;\n  background: #F0F8EA;\n  border: 1px solid #C2E9C3;\n  border-radius: 8px;\n  color: #3E8C40;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n  transition: background 0.15s;\n  text-decoration: none;\n  line-height: 1;\n  text-align: center;\n}\n.replay-button svg {\n  width: 20px;\n  height: 20px;\n  vertical-align: middle;\n  fill: currentColor;\n}\n.replay-button svg circle {\n  fill: none;\n  stroke: none;\n}\n.replay-button svg path {\n  fill: currentColor;\n  stroke: none;\n}\n.replay-button:hover { background: #F0F8EA; }\n.replay-button:active { background: #C2E1C8; }\n\n.nightMode .replay-button {\n  background: #2B3A2A;\n  border-color: #3A503D;\n  color: #73EA8B;\n}\n.nightMode .replay-button:hover { background: #2B3A2A; }\n.nightMode .replay-button:active { background: #273827; }\n\n@media (prefers-color-scheme: dark) {\n  .replay-button {\n    background: #334633;\n    border-color: #3A503D;\n    color: #73EA8B;\n  }\n  .replay-button:hover { background: #2B3A2A; }\n  .replay-button:active { background: #334633; }\n}\n\n\n/* --- Example sentence: tap the Japanese text to play the sentence audio --- */\n.example .example-ja.tap-play-ex {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.example .example-ja.tap-play-ex:active { opacity: 0.55; }\n\n/* --- Word audio: hidden auto-generated button; tap the reading to replay --- */\n.word-audio-hidden { display: none; }\n.reading.tap-play {\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n  user-select: none;\n}\n.reading.tap-play:active { opacity: 0.55; }\n\n\n/* --- kanji breakdown (k-brk) --- */\n.k-brk { padding: 0; margin: 0; font-family: -apple-system, \"Hiragino Sans\", sans-serif; }\n.k-brk + .k-brk { border-top: 1px solid rgba(128,128,128,0.13); margin-top: 14px; padding-top: 14px; }\n.k-brk .k-mean { font-weight: 500; margin-bottom: 8px; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; }\n.k-brk .k-head .k-char { margin-right: 0; }\n.k-brk .k-stats { display: flex; gap: 18px; align-items: flex-start; margin-left: auto; }\n.k-brk .k-stat { display: flex; flex-direction: column; align-items: center; line-height: 1.25; }\n.k-brk .k-stat-v { font-weight: 700; font-size: 1em; color: #222; line-height: 1.2; height: 1.2em; display: block; }\n.k-brk .k-stat-l { margin-top: 3px; line-height: 1; font-size: 0.48em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.nightMode .k-brk .k-stat-v { color: #ddd; }\n.k-brk .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-meta { font-size: 0.9em; color: #888; }\n.k-brk .k-radical, .k-brk .k-components, .k-brk .k-mean { font-size: 0.95em; margin-top: 3px; }\n.nightMode .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .k-brk + .k-brk { border-top-color: rgba(200,200,200,0.13); } .k-brk .k-meta { color: #aaa; } .k-brk .k-stat-v { color: #ddd; } }\n\n/* --- kanji breakdown enhancements (readings) --- */\n.k-brk { line-height: 1.7; }\n.k-brk .k-head { display: flex; align-items: center; gap: 26px; margin-bottom: 6px; line-height: 1.1; }\n.k-brk .k-head .k-char { font-size: 2em; margin-right: 8px; vertical-align: middle; }\n.k-brk .k-head .k-meta { font-size: 0.9em; color: #888; vertical-align: middle; }\n.k-brk .k-mean, .k-brk .k-reading, .k-brk .k-radical, .k-brk .k-components { margin-top: 1px; line-height: 1.45; }\n.k-brk .k-reading { font-size: 0.95em; }\n.k-brk .k-label { display: inline-block; min-width: 2.6em; color: #666; font-weight: 600; font-size: 0.85em; margin-right: 4px; letter-spacing: 0.02em; }\n.nightMode .k-brk .k-head .k-meta { color: #aaa; }\n.nightMode .k-brk .k-label { color: #bbb; }\n@media (prefers-color-scheme: dark) {\n  .k-brk .k-head .k-meta { color: #aaa; }\n  .k-brk .k-label { color: #bbb; }\n}\n\n/* --- compact kanji entries: no components line, On/Kun readings inline --- */\n.k-brk .k-components { display: none; }\n.k-brk .k-reading { display: inline; word-break: keep-all; }\n.k-brk .k-reading + .k-reading { margin-left: 14px; }\n.k-brk .k-reading .k-label { min-width: 0; }\n.k-brk .k-reading + .k-radical { margin-top: 3px; }\n.k-brk .k-reading .k-r { white-space: nowrap; }\n\n/* --- tight vertical rhythm for kanji entries --- */\n.k-brk { line-height: 1.45; }\n.k-brk .k-head { margin-bottom: 4px; }\n.k-brk .k-mean { margin-bottom: 2px; }\n.k-brk .k-reading + .k-radical { margin-top: 1px; }\n.k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kanji-breakdown .kb-content { line-height: 1.5; }\n\n/* --- Nihongo deep-link styling (assertive) --- */\n.k-brk a, .k-brk .k-link { color: #1f665b !important; text-decoration: underline dotted !important; text-underline-offset: 2px; text-decoration-thickness: 1.5px; padding-bottom: 1px; }\n.k-brk .k-head a, .k-brk .k-head .k-link { text-decoration: none !important; padding-bottom: 0; }\n.k-brk .k-head .k-char { color: inherit; }\n.k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #222 !important; border-bottom: 2px dotted #1f665b !important; padding-bottom: 2px; }\n.k-brk a:active, .k-brk .k-link:active { background: rgba(31, 102, 91, 0.15); }\n.k-brk .k-head a:active .k-char, .k-brk .k-head .k-link:active .k-char { background: rgba(31, 102, 91, 0.15); }\n.nightMode .k-brk a, .nightMode .k-brk .k-link { color: #63c2b1 !important; }\n.nightMode .k-brk .k-head a .k-char, .nightMode .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n@media (prefers-color-scheme: dark) {\n  .k-brk a, .k-brk .k-link { color: #63c2b1 !important; }\n  .k-brk .k-head a .k-char, .k-brk .k-head .k-link .k-char { color: #ddd !important; border-bottom-color: #63c2b1 !important; }\n}\n\n/* --- POS pill tap target (wraps .pos-tag in Nihongo word link) --- */\n.pos-tag-link { text-decoration: none; color: inherit; display: inline-block; }\n.pos-tag-link:active .pos-tag { opacity: 0.7; }\n\n/* === v2: stroke-order layout (Sep 2026) === */\n/* --- word block: furigana over the word, meaning below; whole block taps to play word audio --- */\n.word-block { position: relative; z-index: 1; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.word-block:active { opacity: 0.55; }\n/* the back word keeps the front word's exact box (margin 24px/16px, line-height 1.6) so it does not move on flip;\n   furigana hangs above the glyphs out of flow, in the leading + top margin */\n.front-word-ruby { position: relative; margin: 24px 0 -10px; line-height: 1.6; }\n.front-word-ruby .fw-base, .front-word-ruby .fk { position: relative; display: inline-block; line-height: 1; }\n.front-word-ruby .fw-read, .front-word-ruby .fr { position: absolute; left: 50%; bottom: 100%; transform: translateX(-50%); margin-bottom: 3px; font-size: 0.4em; font-weight: 500; color: #d63964; line-height: 1.2; letter-spacing: 0.02em; white-space: nowrap; }\n.word-block .meaning { margin-bottom: 0; }\n.word-block .meaning { margin-top: 4px; }\n.card.prod .front-english { margin-bottom: 0; }\n.card.prod .front-word-ruby { margin-top: 14px; }\n\n/* --- word info: part of speech + Nihongo word link; fades up behind the meaning --- */\n.wordinfo { position: relative; margin: -48px 0 0; padding: 62px 16px 10px; background: linear-gradient(to bottom, rgba(245,245,245,0) 0%, #f5f5f5 70%); border-radius: 10px; text-align: left; display: flex; align-items: center; justify-content: space-between; gap: 12px; overflow: hidden; }\n.card.prod .wordinfo { margin-top: -30px; padding-top: 44px; }\n.wordinfo-pos { font-size: 14px; font-weight: 600; color: #8c8c8c; letter-spacing: 0.01em; }\n.card a.wordinfo-nih { font-weight: 800; font-size: 20px; line-height: 1; color: #8c8c8c; text-decoration: none; padding: 0 0 2px; border-bottom: 2px dotted #8c8c8c; flex: none; -webkit-tap-highlight-color: transparent; }\n.card a.wordinfo-nih:active { background: rgba(0,0,0,0.08); }\n\n/* --- example card: the whole card taps to play the sentence --- */\n.example { margin-top: 12px; }\n.kanji-breakdown { margin-top: 12px; }\n.example.tap-play-ex { cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.example.tap-play-ex:active { opacity: 0.55; }\n.example .audio.example-audio { display: none; margin: 0; }\n\n/* --- example list (.ex-v2 is added by the template script): one .ex-item per sentence, split like the kanji entries.\n   The card itself has no padding - each item carries it, so the whole row (edge to edge) is the tap target --- */\n.example.ex-v2 { padding: 0; overflow: hidden; }\n.ex-v2 .ex-item { position: relative; padding: 10px 16px 12px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.ex-v2 .ex-item + .ex-item::before { content: \"\"; position: absolute; top: 0; left: 16px; right: 16px; border-top: 1px solid rgba(128,128,128,0.13); }\n.ex-v2 .ex-item:active { opacity: 0.55; }\n.ex-v2 .ex-item audio { display: none; }\n/* no-JS fallback: the separator stored in the fields still reads as a rule */\n.example hr.ex-sep { border: none; border-top: 1px solid rgba(128,128,128,0.13); margin: 8px 0; }\n.nightMode .ex-v2 .ex-item + .ex-item::before, .nightMode .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); }\n@media (prefers-color-scheme: dark) { .ex-v2 .ex-item + .ex-item::before, .example hr.ex-sep { border-top-color: rgba(200,200,200,0.13); } }\n\n/* --- kanji entries (re-laid out by the template script; .kb-v2 is added once that has run) --- */\n.kb-v2 .k-brk { line-height: 1.45; }\n.kb-v2 .k-brk + .k-brk { margin-top: 10px; padding-top: 10px; }\n.kb-v2 .k-head2 { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 5px; }\n.kb-v2 .k-readings { flex: 1 1 auto; min-width: 0; display: block; font-size: 0.95em; line-height: 1.4; }\n.kb-v2 .k-reading2 { display: flex; align-items: baseline; gap: 6px; color: #222; font-size: 1.02em; line-height: 1.5; }\n.kb-v2 .k-lab { flex: none; min-width: 2.4em; font-size: 0.68em; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: #9a9a9a; }\n.kb-v2 .k-vals { color: #222; }\n.kb-v2 .k-r { white-space: nowrap; }\n.kb-v2 .k-mean2 { font-weight: 500; font-size: 1em; color: #222; line-height: 1.35; margin: 0; }\n.kb-v2 .k-stats2 { float: right; display: flex; flex-direction: column; align-items: flex-end; gap: 7px; margin-left: 12px; min-width: 2.2em; }\n.kb-v2 .k-sv { font-weight: 700; font-size: 0.8em; color: #8c8c8c; line-height: 1; letter-spacing: 0.02em; white-space: nowrap; }\n.kb-v2 .k-unit { font-size: 0.9em; font-weight: 600; margin-left: 1px; }\n.kb-v2 .k-brk a.k-nih { font-weight: 800; font-size: 1.35em; line-height: 1; color: #1f665b !important; text-decoration: none !important; padding: 0 0 2px; margin: -2px 0 2px; border-bottom: 2px dotted #1f665b; -webkit-tap-highlight-color: transparent; }\n.kb-v2 .k-brk a.k-nih:active { background: rgba(31,102,91,0.15); }\n\n/* --- on/kun readings tap to play their clip (class added by the template script); dotted underline = tappable --- */\n.kb-v2 .k-r.k-r-tap { cursor: pointer; text-decoration: underline dotted #a9a9a9; text-decoration-thickness: 1.5px; text-underline-offset: 4px; padding: 5px 2px; margin: 0 -2px; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }\n.kb-v2 .k-r.k-r-tap:active { opacity: 0.55; }\n.kb-v2 .k-r.k-r-tap.playing { color: #1f665b; text-decoration-color: #1f665b; }\n.nightMode .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; }\n.nightMode .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; }\n@media (prefers-color-scheme: dark) { .kb-v2 .k-r.k-r-tap { text-decoration-color: #6a6a6a; } .kb-v2 .k-r.k-r-tap.playing { color: #63c2b1; text-decoration-color: #63c2b1; } }\n\n/* --- every tap target: no double-tap zoom / 300 ms click delay on iOS --- */\n.word-block, .ex-v2 .ex-item, .kb-v2 .k-box, .kb-v2 .k-r.k-r-tap, .kb-v2 .k-head2, .card a.wordinfo-nih, .kb-v2 .k-brk a.k-nih { touch-action: manipulation; }\n\n/* --- the kanji grid box --- */\n.kb-v2 .k-box { position: relative; flex: none; width: 66px; height: 66px; box-sizing: border-box; border: 1.5px dotted #d2d2d2; border-radius: 4px; cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; --k-ink: #1f1f1f; --k-ghost: #bdbdbd; --k-grid: #c4c4c4; --k-dot: #49c248; }\n.kb-v2 .k-box:active { background: rgba(31,102,91,0.06); }\n.kb-v2 .k-fallback { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 40px; line-height: 1; color: #1f1f1f; }\n.kb-v2 .k-box.has-svg .k-fallback { display: none; }\n.kb-v2 .k-svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }\n.kb-v2 .k-grid line { stroke: var(--k-grid); stroke-width: 1.2; stroke-dasharray: 2 3; vector-effect: non-scaling-stroke; }\n.kb-v2 .k-ghost path { fill: none; stroke: var(--k-ghost); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; opacity: 0; transition: opacity 0.15s; }\n.kb-v2 .k-box.animating .k-ghost path { opacity: 1; }\n.kb-v2 .k-ink path { fill: none; stroke: var(--k-ink); stroke-width: 5.5; stroke-linecap: round; stroke-linejoin: round; }\n.kb-v2 .k-dot { fill: var(--k-dot); opacity: 0; transition: opacity 0.25s; }\n.kb-v2 .k-box.animating .k-dot, .kb-v2 .k-box.done .k-dot { opacity: 1; }\n.kb-v2 .k-play { position: absolute; right: -8px; bottom: -8px; width: 18px; height: 18px; border-radius: 50%; background: #efefef; color: #5a5a5a; display: flex; align-items: center; justify-content: center; box-shadow: 0 0 0 2px #f5f5f5; cursor: pointer; z-index: 1; }\n.kb-v2 .k-play svg { width: 12px; height: 12px; margin-left: 2px; }\n.kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #dcdcdc; }\n.kb-v2 .k-box.animating .k-play { opacity: 0.55; }\n\n/* --- tap guard, answer side only (templates/tap_guard.js): taps on the card never reach AnkiMobile's tap zones.\n   The shield is a transparent full-screen layer behind the card, so the empty space around a short card is covered too --- */\n.tap-shield { position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 0; background: transparent; -webkit-tap-highlight-color: transparent; }\n.card[data-notap] { position: relative; z-index: 1; -webkit-tap-highlight-color: transparent; }\n\n/* --- narrow screens (iPhone): trim the side margins; wider screens keep max-width 600 + 20px padding --- */\n@media (max-width: 480px) {\n  body { margin-left: 0; margin-right: 0; }\n  .card { padding: 14px 12px 24px; }\n}\n\n/* dark (Anki .nightMode) */\n.nightMode .front-word-ruby .fw-read, .nightMode .front-word-ruby .fr { color: #f0826e; }\n.nightMode .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n.nightMode .wordinfo-pos { color: #8f8f8f; }\n.nightMode .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n.nightMode .kb-v2 .k-reading2, .nightMode .kb-v2 .k-vals { color: #e6e6e6; }\n.nightMode .kb-v2 .k-lab { color: #8a8a8a; }\n.nightMode .kb-v2 .k-mean2 { color: #e6e6e6; }\n.nightMode .kb-v2 .k-sv { color: #8f8f8f; }\n.nightMode .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n.nightMode .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n.nightMode .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n.nightMode .kb-v2 .k-fallback { color: #f2f2f2; }\n.nightMode .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n.nightMode .kb-v2 .k-box:active .k-play, .nightMode .kb-v2 .k-play:active { background: #4a4a4a; }\n\n/* dark (system) */\n@media (prefers-color-scheme: dark) {\n  .front-word-ruby .fw-read, .front-word-ruby .fr { color: #f0826e; }\n  .wordinfo { background: linear-gradient(to bottom, rgba(42,42,42,0) 0%, #2a2a2a 70%); }\n  .wordinfo-pos { color: #8f8f8f; }\n  .card a.wordinfo-nih { color: #8f8f8f; border-bottom-color: #8f8f8f; }\n  .kb-v2 .k-reading2, .kb-v2 .k-vals { color: #e6e6e6; }\n  .kb-v2 .k-lab { color: #8a8a8a; }\n  .kb-v2 .k-mean2 { color: #e6e6e6; }\n  .kb-v2 .k-sv { color: #8f8f8f; }\n  .kb-v2 .k-brk a.k-nih { color: #63c2b1 !important; border-bottom-color: #63c2b1; }\n  .kb-v2 .k-box { border-color: #4a4a4a; --k-ink: #f2f2f2; --k-ghost: #555; --k-grid: #5a5a5a; --k-dot: #49c248; }\n  .kb-v2 .k-box:active { background: rgba(99,194,177,0.1); }\n  .kb-v2 .k-fallback { color: #f2f2f2; }\n  .kb-v2 .k-play { background: #3a3a3a; color: #cfcfcf; box-shadow: 0 0 0 2px #2a2a2a; }\n  .kb-v2 .k-box:active .k-play, .kb-v2 .k-play:active { background: #4a4a4a; }\n}\n\n/* Answer-only compact reveal. Fronts and unillustrated cards keep their layout. */\n/* Anki can paint inserted HTML before evaluating its template scripts.\n   Suppress that intermediate layout, but automatically show it after 700ms\n   even if scripts fail. Never depend on JavaScript to make a card readable. */\n.card[data-notap]:has(.vocab-visual):not(.visual-ready) {\n  animation: visual-prepare-fallback 700ms step-end both;\n}\n@keyframes visual-prepare-fallback { from { opacity: 0; } to { opacity: 1; } }\n.vocab-visual { margin: 0; text-align: center; }\n.card.has-vocab-visual > .vocab-visual {\n  margin: -24px 0 0;\n  /* Reserve the final banner height; animate the artwork, not a clipping mask. */\n  overflow: visible;\n}\n.vocab-visual img {\n  display: block;\n  width: 100%;\n  max-width: 480px;\n  height: auto;\n  aspect-ratio: 3 / 1;\n  object-fit: contain;\n  box-sizing: border-box;\n  padding: 4% 6%;\n  margin: 0 auto;\n  border-radius: 0;\n  transform-origin: center center;\n\n}\n.card.visual-ready .vocab-visual img {\n  animation: visual-entrance 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.has-vocab-visual .front-word-ruby {\n  font-size: 32px;\n  line-height: 1.35;\n  /* Furigana occupies the gap; image padding already supplies breathing room. */\n  margin: 14px 0 0;\n  text-align: center;\n  transform-origin: center center;\n\n}\n.card.has-vocab-visual .meaning { font-size: 18px; line-height: 1.35; margin: 2px 0 0; }\n/* Keep the shared light/dark gradient behind the compact meaning and POS. */\n.card.has-vocab-visual .wordinfo { margin: -32px 0 0; padding: 38px 16px 10px; }\n.card.has-vocab-visual.prod .front-english { font-size: 22px; line-height: 1.3; margin: 6px 0 0; }\n.card.has-vocab-visual.prod .front-word-ruby { margin-top: 16px; }\n.card.has-vocab-visual .example { margin-top: 6px; }\n/* One moving answer block preserves every internal spacing relationship. */\n.visual-content { display: flow-root; }\n.card.visual-ready .visual-content {\n  animation: visual-content-slide 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready:not(.prod) .front-word-ruby {\n  animation: visual-word 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n.card.visual-ready .meaning,\n.card.visual-ready .wordinfo,\n.card.visual-ready .example,\n.card.visual-ready .kanji-breakdown,\n.card.visual-ready .fw-read,\n.card.visual-ready .fr {\n  animation: visual-details 400ms ease-out 100ms both;\n}\n.card.visual-ready.prod .front-english {\n  animation: visual-english 560ms cubic-bezier(.4, 0, .2, 1) both;\n}\n@keyframes visual-english { from { font-size: 34px; line-height: 1.6; color: var(--visual-cue-start, #111); } to { font-size: 22px; line-height: 1.3; color: var(--visual-cue-end, #8c8c8c); } }\n@keyframes visual-details { from { opacity: 0; } to { opacity: 1; } }\n@keyframes visual-content-slide {\n  from { transform: translateY(var(--visual-content-start, -100px)); }\n  to { transform: translateY(0); }\n}\n@keyframes visual-entrance {\n  from { opacity: 0; transform: translateY(-100%) scale(.94); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n@keyframes visual-word { from { transform: scale(1.4375); } to { transform: scale(1); } }\n@media (max-width: 480px) {\n  .card.has-vocab-visual > .vocab-visual { margin: -14px 0 0; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .card.has-vocab-visual > .vocab-visual,\n  .card.has-vocab-visual .vocab-visual img,\n  .card.visual-ready .visual-content,\n  .card.has-vocab-visual .fr,\n  .card.has-vocab-visual .fw-read,\n  .card.visual-ready:not(.prod) .front-word-ruby,\n  .card.visual-ready.prod .front-english,\n  .card.has-vocab-visual .meaning,\n  .card.has-vocab-visual .wordinfo,\n  .card.has-vocab-visual .example,\n  .card.has-vocab-visual .kanji-breakdown,\n  .card.has-vocab-visual.prod .front-english { animation: none; }\n}\n\n/* De-emphasize the English cue only after revealing a Production answer. */\n.card.prod:has(.wordinfo) .front-english { color: #8c8c8c; }\n.nightMode .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod:has(.wordinfo) .front-english { color: #8f8f8f; }\n}\n\n/* Carry the question color through the shrink instead of swapping it on reveal. */\n.nightMode .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n@media (prefers-color-scheme: dark) {\n  .card.prod { --visual-cue-start: #f0f0f0; --visual-cue-end: #8f8f8f; }\n}\n.card.visual-ready.prod .word-block { animation: visual-details 400ms ease-out 100ms both; }\n@media (prefers-reduced-motion: reduce) {\n  .card.visual-ready.prod .word-block { animation: none; }\n}\n\nhtml,body{margin:0;padding:0;background:transparent}.card{padding-top:0;padding-bottom:16px;display:flow-root}.tap-shield{display:none}.word-block{cursor:pointer}\n</style></head><body><script src=\"_kanji_strokes.js\"></script>\n<div class=\"tap-shield tappable\" onclick=\"void 0\"></div>\n<div class=\"card tappable has-vocab-visual\" data-notap onclick=\"void 0\">\n<div class=\"word-block tap-play\" onclick=\"event.stopPropagation();var b=this.parentNode.querySelector('.word-audio-hidden a');if(b)b.click();\">\n<div class=\"front-word front-word-ruby\"><span class=\"fw-base\">自転車</span><span class=\"fw-read\">じてんしゃ</span></div>\n<div class=\"meaning\">bicycle</div>\n</div>\n<div class=\"word-audio-hidden\"><a href=\"#\" onclick=\"event.preventDefault();this.nextElementSibling.currentTime=0;this.nextElementSibling.play()\">Play</a><audio src=\"n5_wd_b052e808f33626b1.mp3\"></audio></div>\n<div class=\"wordinfo\">\n<div class=\"wordinfo-pos\">Noun</div>\n<a class=\"wordinfo-nih\" href=\"https://nihongo-app.com/dictionary/word/自転車\">語</a>\n</div>\n<div class=\"example tap-play-ex\" onclick=\"event.stopPropagation();var a=this.querySelector('audio');if(a){a.currentTime=0;a.play();}\">\n<div class=\"example-ja\"><ruby>自転車<rt>じてんしゃ</rt></ruby>で <ruby>学校<rt>がっこう</rt></ruby>に <ruby>行<rt>い</rt></ruby>きます。<hr class=\"ex-sep\"><ruby>弟<rt>おとうと</rt></ruby>は <ruby>新<rt>あたら</rt></ruby>しい <ruby>自転車<rt>じてんしゃ</rt></ruby>に <ruby>乗<rt>の</rt></ruby>っています。</div>\n<div class=\"example-en\">I go to school by bicycle.<hr class=\"ex-sep\">My little brother is riding a new bicycle.</div>\n<div class=\"audio example-audio\"><audio src=\"n5_ex_659762a3994b77f4.mp3\" preload=\"none\"></audio><audio src=\"n5_ex_f5db95626c1351a2.mp3\" preload=\"none\"></audio></div>\n</div>\n\n<div class=\"kanji-breakdown\">\n<div class=\"kb-content\"><div class=\"k-brk\">\n  <div class=\"k-head\"><a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji/自\"><span class=\"k-char\">自</span></a><span class=\"k-stats\"><span class=\"k-stat\"><span class=\"k-stat-v\">6</span><span class=\"k-stat-l\">Strokes</span></span><span class=\"k-stat\"><span class=\"k-stat-v\">N3</span><span class=\"k-stat-l\">JLPT</span></span></span></div>\n  <div class=\"k-mean\">oneself</div>\n  <div class=\"k-reading\"><span class=\"k-label\">On:</span> <span class=\"k-r\">ジ</span>, <span class=\"k-r\">シ</span></div>\n  <div class=\"k-reading\"><span class=\"k-label\">Kun:</span> <span class=\"k-r\">みずか(ら)</span>, <span class=\"k-r\">おの(ずから)</span>, <span class=\"k-r\">おの(ずと)</span></div>\n  <div class=\"k-radical\"><span class=\"k-label\">Radical:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/自\">自</a> (mizukara, self)</div>\n</div>\n<div class=\"k-brk\">\n  <div class=\"k-head\"><a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji/転\"><span class=\"k-char\">転</span></a><span class=\"k-stats\"><span class=\"k-stat\"><span class=\"k-stat-v\">11</span><span class=\"k-stat-l\">Strokes</span></span><span class=\"k-stat\"><span class=\"k-stat-v\">N3</span><span class=\"k-stat-l\">JLPT</span></span></span></div>\n  <div class=\"k-mean\">revolve, turn around, change</div>\n  <div class=\"k-reading\"><span class=\"k-label\">On:</span> <span class=\"k-r\">テン</span></div>\n  <div class=\"k-reading\"><span class=\"k-label\">Kun:</span> <span class=\"k-r\">ころ(がる)</span>, <span class=\"k-r\">ころ(げる)</span>, <span class=\"k-r\">ころ(がす)</span>, <span class=\"k-r\">ころ(ぶ)</span>, <span class=\"k-r\">まろ(ぶ)</span>, <span class=\"k-r\">うたた</span>, <span class=\"k-r\">うつ(る)</span>, <span class=\"k-r\">くる(めく)</span></div>\n  <div class=\"k-radical\"><span class=\"k-label\">Radical:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/車\">車</a> (kuruma, cart)</div>\n  <div class=\"k-components\"><span class=\"k-label\">Components:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/車\">車</a> car, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/二\">二</a> two, <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/厶\">厶</a> I</div>\n</div>\n<div class=\"k-brk\">\n  <div class=\"k-head\"><a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji/車\"><span class=\"k-char\">車</span></a><span class=\"k-stats\"><span class=\"k-stat\"><span class=\"k-stat-v\">7</span><span class=\"k-stat-l\">Strokes</span></span><span class=\"k-stat\"><span class=\"k-stat-v\">N4</span><span class=\"k-stat-l\">JLPT</span></span></span></div>\n  <div class=\"k-mean\">car</div>\n  <div class=\"k-reading\"><span class=\"k-label\">On:</span> <span class=\"k-r\">シャ</span></div>\n  <div class=\"k-reading\"><span class=\"k-label\">Kun:</span> <span class=\"k-r\">くるま</span></div>\n  <div class=\"k-radical\"><span class=\"k-label\">Radical:</span> <a class=\"k-link\" href=\"https://nihongo-app.com/dictionary/kanji-element/車\">車</a> (kuruma, cart)</div>\n</div></div>\n</div>\n\n<span class=\"visual-key\" hidden>自転車|じてんしゃ</span>\n<span class=\"dictionary-key\" hidden>自転車|じてんしゃ|bicycle</span>\n<script>\n(function(){\n  var NS = 'http://www.w3.org/2000/svg';\n  var KANJI_RE = /[㐀-鿿豈-﫿々]/;\n  function el(tag, attrs){ var e = document.createElementNS(NS, tag); for (var k in attrs) e.setAttribute(k, attrs[k]); return e; }\n  function txt(n){ return n ? (n.textContent || '').replace(/\\s+/g, ' ').trim() : ''; }\n  function stop(e){ e.stopPropagation(); }\n  function guard(node){ node.addEventListener('click', stop, false); node.addEventListener('touchend', stop, false); }\n  /* run fn on a tap. iOS drops the click after a touch that stops a momentum scroll or that it takes for a double-tap,\n     so on touch devices we act on touchend of an unmoved touch and suppress the synthetic click; mouse/desktop use click */\n  function tap(node, fn){\n    var sx = 0, sy = 0, moved = true, handled = false;\n    node.addEventListener('touchstart', function(e){ var t = e.touches[0]; if (!t || e.touches.length > 1) { moved = true; return; } sx = t.clientX; sy = t.clientY; moved = false; handled = false; }, {passive: true});\n    node.addEventListener('touchmove', function(e){ var t = e.touches[0]; if (!t || Math.abs(t.clientX - sx) > 12 || Math.abs(t.clientY - sy) > 12) moved = true; }, {passive: true});\n    node.addEventListener('touchend', function(e){ if (moved) return; moved = true; handled = true; if (e.cancelable) e.preventDefault(); fn(); }, {passive: false});\n    node.addEventListener('touchcancel', function(){ moved = true; }, {passive: true});\n    node.addEventListener('click', function(){ if (handled) { handled = false; return; } fn(); }, false);\n  }\n  // scope everything to the card this script lives in (falls back to the last card on the page)\n  var root = null, cs = document.currentScript;\n  if (cs && cs.closest) root = cs.closest('.card');\n  if (!root) { var cards = document.querySelectorAll('.card'); root = cards.length ? cards[cards.length - 1] : document; }\n\n  /* ---- align a kana reading to the kanji runs of a word: お願いします + おねがいします -> お<ruby>願<rt>ねが</rt></ruby>います ---- */\n  function toHira(s){ return s.replace(/[ァ-ヶ]/g, function(c){ return String.fromCharCode(c.charCodeAt(0) - 0x60); }); }\n  function isKanji(c){ return KANJI_RE.test(c); }\n  function isKana(c){ return /[ぁ-ゟ゠-ヿ]/.test(c); }\n  function esc(s){ return s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&'); }\n  function alignFurigana(word, reading){\n    reading = (reading || '').replace(/\\s+/g, '');\n    if (word.indexOf('(') < 0) reading = reading.replace(/[（(][^)）]*[)）]/g, '');\n    if (word.indexOf('/') < 0 && reading.indexOf('/') >= 0) reading = reading.split('/')[0];\n    var hira = toHira(reading);\n    // split the word into runs: kanji / kana / other\n    var runs = [], i, c, t, cur = null;\n    for (i = 0; i < word.length; i++) {\n      c = word.charAt(i); t = isKanji(c) ? 'k' : (isKana(c) ? 'a' : 'o');\n      if (c === '々' && cur && cur.t === 'k') t = 'k';\n      if (cur && cur.t === t) cur.s += c; else { cur = {t:t, s:c}; runs.push(cur); }\n    }\n    var kanjiRuns = 0; for (i = 0; i < runs.length; i++) if (runs[i].t === 'k') kanjiRuns++;\n    if (!kanjiRuns) return null;\n    var pat = '^';\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') pat += '(.+?)';\n      else if (runs[i].t === 'a') pat += esc(toHira(runs[i].s));\n      else pat += '(?:' + esc(runs[i].s) + ')?';\n    }\n    pat += '$';\n    var m = hira.match(new RegExp(pat));\n    if (!m) return null;\n    var out = [], gi = 1, pos = 0;\n    for (i = 0; i < runs.length; i++) {\n      if (runs[i].t === 'k') {\n        // take the kana slice from the original reading (keeps katakana if it was katakana)\n        var idx = hira.indexOf(m[gi], pos); if (idx < 0) return null;\n        out.push({kanji: runs[i].s, kana: reading.substr(idx, m[gi].length)});\n        pos = idx + m[gi].length; gi++;\n      } else { out.push({text: runs[i].s}); if (runs[i].t === 'a') pos += runs[i].s.length; }\n    }\n    return out;\n  }\n  function fk(kanji, kana){\n    var s = document.createElement('span'); s.className = 'fk'; s.appendChild(document.createTextNode(kanji));\n    var r = document.createElement('span'); r.className = 'fr'; r.textContent = kana; s.appendChild(r);\n    return s;\n  }\n  function renderFurigana(container, word, reading){\n    var parts = alignFurigana(word, reading);\n    if (!parts) return false;\n    while (container.firstChild) container.removeChild(container.firstChild);\n    for (var i = 0; i < parts.length; i++) {\n      if (parts[i].kanji) container.appendChild(fk(parts[i].kanji, parts[i].kana));\n      else container.appendChild(document.createTextNode(parts[i].text));\n    }\n    return true;\n  }\n  function renderWhole(container, word, reading){\n    while (container.firstChild) container.removeChild(container.firstChild);\n    if (reading) container.appendChild(fk(word, reading)); else container.appendChild(document.createTextNode(word));\n  }\n\n  /* ---- 1. furigana over the word: only over the kanji, hung above the glyphs so the word sits exactly where it does on the front ---- */\n  var fw = root.querySelector('.front-word-ruby');\n  if (fw) {\n    var baseEl = fw.querySelector('.fw-base'), readEl = fw.querySelector('.fw-read');\n    var base = txt(baseEl), reading = txt(readEl);\n    if (!KANJI_RE.test(base) || reading === base || !reading) renderWhole(fw, base, '');\n    else if (!renderFurigana(fw, base, reading)) renderWhole(fw, base, reading);\n  }\n\n  /* ---- 2. audio tap targets must never reach the card's tap gestures ---- */\n  var taps = root.querySelectorAll('.tap-play, .tap-play-ex, .wordinfo-nih');\n  for (var i = 0; i < taps.length; i++) guard(taps[i]);\n\n  /* ---- 2b. example sentences: the fields may hold two sentences separated by <hr class=\"ex-sep\">.\n     Re-lay them out as list items (.ex-item = Japanese + English + its own clip); the WHOLE item,\n     padding included, is the tap target, and nothing inside the red card ever reaches Anki's tap gestures ---- */\n  var ex = root.querySelector('.example');\n  if (ex && !ex.classList.contains('ex-v2')) {\n    var splitAtHr = function(node){\n      var groups = [[]]; if (!node) return groups;\n      var n = node.firstChild;\n      while (n) { var nx = n.nextSibling; if (n.nodeType === 1 && n.tagName === 'HR') groups.push([]); else groups[groups.length - 1].push(n); n = nx; }\n      return groups;\n    };\n    var jaG = splitAtHr(ex.querySelector('.example-ja')), enG = splitAtHr(ex.querySelector('.example-en'));\n    var auds = ex.querySelectorAll('audio'), items = [], g, k;\n    for (g = 0; g < jaG.length; g++) {\n      var item = document.createElement('div'); item.className = 'ex-item'; item.setAttribute('role', 'button');\n      var ja = document.createElement('div'); ja.className = 'example-ja';\n      for (k = 0; k < jaG[g].length; k++) ja.appendChild(jaG[g][k]);\n      item.appendChild(ja);\n      if (enG[g]) { var en = document.createElement('div'); en.className = 'example-en'; for (k = 0; k < enG[g].length; k++) en.appendChild(enG[g][k]); item.appendChild(en); }\n      if (auds[g]) item.appendChild(auds[g]);\n      items.push(item);\n    }\n    while (ex.firstChild) ex.removeChild(ex.firstChild);\n    ex.removeAttribute('onclick'); ex.onclick = null;\n    ex.classList.remove('tap-play-ex'); ex.classList.add('ex-v2');\n    var playItem = function(item){\n      var all = ex.querySelectorAll('audio'), mine = item.querySelector('audio');\n      for (var a = 0; a < all.length; a++) if (all[a] !== mine) { try { all[a].pause(); all[a].currentTime = 0; } catch (e) {} }\n      if (mine) { try { mine.currentTime = 0; } catch (e) {} var pr = mine.play(); if (pr && pr.catch) pr.catch(function(){}); }\n    };\n    for (g = 0; g < items.length; g++) {\n      ex.appendChild(items[g]); guard(items[g]);\n      (function(it){ tap(it, function(){ playItem(it); }); })(items[g]);\n    }\n  }\n\n  /* ---- 3. re-lay out each kanji breakdown entry (field markup stays unchanged) ---- */\n  var kb = root.querySelector('.kanji-breakdown');\n  if (kb && !kb.classList.contains('kb-v2')) {\n    var brks = kb.querySelectorAll('.k-brk');\n    for (var b = 0; b < brks.length; b++) relayout(brks[b]);\n    kb.classList.add('kb-v2');\n\n    /* ---- 3b. tappable on/kun readings: each .k-r plays `_kr_<hex of the hiragana reading>.mp3`\n       (a _-prefixed template media file; okurigana marks, dots and hyphens are dropped, katakana -> hiragana).\n       The whole head row swallows taps so a near miss never flips the card. ---- */\n    var krAudio = null;\n    var krFile = function(t){\n      var sp = toHira(t.replace(/[-.()（）\\s‐－]/g, '')), hex = '';\n      if (!sp || !/^[ぁ-ゖー]+$/.test(sp)) return null;\n      for (var i = 0; i < sp.length; i++) hex += ('0000' + sp.charCodeAt(i).toString(16)).slice(-4);\n      return '_kr_' + hex + '.mp3';\n    };\n    var playKr = function(node, file){\n      if (!krAudio) { krAudio = document.createElement('audio'); krAudio.setAttribute('preload', 'none'); krAudio.style.display = 'none'; root.appendChild(krAudio); }\n      var others = root.querySelectorAll('.example audio');\n      for (var o = 0; o < others.length; o++) { try { others[o].pause(); } catch (e) {} }\n      var on = kb.querySelectorAll('.k-r.playing'); for (var q = 0; q < on.length; q++) on[q].classList.remove('playing');\n      node.classList.add('playing'); setTimeout(function(){ node.classList.remove('playing'); }, 700);\n      try { krAudio.pause(); krAudio.src = file; krAudio.currentTime = 0; } catch (e) {}\n      var pr = krAudio.play(); if (pr && pr.catch) pr.catch(function(){});\n    };\n    var krs = kb.querySelectorAll('.k-r');\n    for (var r2 = 0; r2 < krs.length; r2++) (function(node){\n      var file = krFile(txt(node)); if (!file) return;\n      node.classList.add('k-r-tap'); node.setAttribute('role', 'button');\n      guard(node); tap(node, function(){ playKr(node, file); });\n    })(krs[r2]);\n    var heads = kb.querySelectorAll('.k-head2'); for (var h2 = 0; h2 < heads.length; h2++) guard(heads[h2]);\n  }\n\n  function relayout(brk){\n    var ch = txt(brk.querySelector('.k-char'));\n    if (!ch) return;\n    var link = brk.querySelector('.k-head a');\n    var href = (link && link.getAttribute('href')) || ('https://nihongo-app.com/dictionary/kanji/' + ch);\n    var strokes = '', jlpt = '';\n    var stats = brk.querySelectorAll('.k-stat');\n    for (var s = 0; s < stats.length; s++) {\n      var lab = txt(stats[s].querySelector('.k-stat-l')).toLowerCase(), v = txt(stats[s].querySelector('.k-stat-v'));\n      if (lab.indexOf('stroke') === 0) strokes = v; else if (lab.indexOf('jlpt') === 0) jlpt = v;\n    }\n    var meanText = txt(brk.querySelector('.k-mean'));\n    var readings = brk.querySelectorAll('.k-reading');\n\n    var head = document.createElement('div'); head.className = 'k-head2';\n    var box = document.createElement('div'); box.className = 'k-box'; box.setAttribute('data-kanji', ch); box.setAttribute('role', 'button');\n    var fb = document.createElement('span'); fb.className = 'k-fallback'; fb.textContent = ch; box.appendChild(fb);\n    var play = document.createElement('span'); play.className = 'k-play';\n    play.innerHTML = '<svg viewBox=\"0 0 12 12\"><path d=\"M3.6 2.2 L10 6 L3.6 9.8 Z\" fill=\"currentColor\"/></svg>';\n    box.appendChild(play);\n    head.appendChild(box);\n\n    var col = document.createElement('div'); col.className = 'k-readings';\n    var st = document.createElement('span'); st.className = 'k-stats2';\n    var nih = document.createElement('a'); nih.className = 'k-nih'; nih.href = href; nih.textContent = '語'; st.appendChild(nih);\n    if (strokes) { var sv = document.createElement('span'); sv.className = 'k-sv'; sv.innerHTML = strokes + '<span class=\"k-unit\">画</span>'; st.appendChild(sv); }\n    if (jlpt) { var jv = document.createElement('span'); jv.className = 'k-sv'; jv.textContent = jlpt; st.appendChild(jv); }\n    col.appendChild(st);\n    for (var r = 0; r < readings.length; r++) {\n      var src = readings[r], label = src.querySelector('.k-label');\n      var row = document.createElement('div'); row.className = 'k-reading2';\n      var lab2 = document.createElement('span'); lab2.className = 'k-lab'; lab2.textContent = txt(label).replace(/:$/, ''); row.appendChild(lab2);\n      var vals = document.createElement('span'); vals.className = 'k-vals';\n      var n = src.firstChild;\n      while (n) { var next = n.nextSibling; if (n !== label) vals.appendChild(n); n = next; }\n      row.appendChild(vals); col.appendChild(row);\n    }\n    head.appendChild(col);\n\n    var mean = document.createElement('div'); mean.className = 'k-mean2'; mean.textContent = meanText;\n\n    while (brk.firstChild) brk.removeChild(brk.firstChild);\n    brk.appendChild(head); brk.appendChild(mean);\n    guard(box); guard(nih);\n    tap(box, function(){ animate(box); });\n  }\n\n  /* ---- 4. stroke-order boxes (KanjiVG paths from _kanji_strokes.js) ---- */\n  function buildBox(box){\n    var strokes = window.KANJI_STROKES[box.getAttribute('data-kanji')];\n    if (!strokes || !strokes.length) return;\n    var svg = el('svg', {viewBox:'-7 -7 123 123', 'class':'k-svg', 'aria-hidden':'true'});\n    var grid = el('g', {'class':'k-grid'});\n    grid.appendChild(el('line', {x1:54.5, y1:-5, x2:54.5, y2:114}));\n    grid.appendChild(el('line', {x1:-5, y1:54.5, x2:114, y2:54.5}));\n    svg.appendChild(grid);\n    var ghost = el('g', {'class':'k-ghost'}), ink = el('g', {'class':'k-ink'}), paths = [];\n    for (var i = 0; i < strokes.length; i++) {\n      ghost.appendChild(el('path', {d:strokes[i]}));\n      var p = el('path', {d:strokes[i]}); ink.appendChild(p); paths.push(p);\n    }\n    svg.appendChild(ghost); svg.appendChild(ink);\n    var dot = el('circle', {'class':'k-dot', r:5.2, cx:-20, cy:-20});\n    svg.appendChild(dot);\n    box.insertBefore(svg, box.firstChild);\n    box.classList.add('has-svg');\n    box._k = {paths:paths, dot:dot, raf:0, timer:0};\n  }\n  function cancel(box){\n    var s = box._k; if (!s) return;\n    if (s.raf) cancelAnimationFrame(s.raf); s.raf = 0;\n    if (s.timer) clearTimeout(s.timer); s.timer = 0;\n    box.classList.remove('animating'); box.classList.remove('done');\n  }\n  function animate(box){\n    if (!box._k && window.KANJI_STROKES) buildBox(box);   // asset arrived after this box was laid out\n    var s = box._k; if (!s) return;\n    cancel(box);\n    var lens = [], i, p;\n    for (i = 0; i < s.paths.length; i++) { lens.push(s.paths[i].getTotalLength()); }\n    for (i = 0; i < s.paths.length; i++) { p = s.paths[i]; p.style.strokeDasharray = lens[i] + ' ' + lens[i]; p.style.strokeDashoffset = lens[i]; }\n    box.classList.add('animating');\n    var idx = 0, t0 = 0, GAP = 70;\n    function dur(len){ return Math.max(170, 90 + len * 4.6); }\n    function ease(t){ return 1 - Math.pow(1 - t, 1.5); }\n    function step(ts){\n      if (!t0) t0 = ts;\n      var q = s.paths[idx], len = lens[idx], t = Math.min(1, (ts - t0) / dur(len)), e = ease(t);\n      q.style.strokeDashoffset = len * (1 - e);\n      var pt = q.getPointAtLength(len * e);\n      s.dot.setAttribute('cx', pt.x); s.dot.setAttribute('cy', pt.y);\n      if (t < 1) { s.raf = requestAnimationFrame(step); return; }\n      idx++; t0 = 0;\n      if (idx < s.paths.length) {\n        s.timer = setTimeout(function(){ s.timer = 0; s.raf = requestAnimationFrame(step); }, GAP);\n      } else {\n        box.classList.remove('animating'); box.classList.add('done');\n        s.timer = setTimeout(function(){ s.timer = 0; box.classList.remove('done'); }, 650);\n      }\n    }\n    var p0 = s.paths[0].getPointAtLength(0); s.dot.setAttribute('cx', p0.x); s.dot.setAttribute('cy', p0.y);\n    s.raf = requestAnimationFrame(step);\n  }\n  var tries = 0;\n  function fill(){\n    if (window.KANJI_STROKES) {\n      var boxes = root.querySelectorAll('.k-box:not(.has-svg)');\n      for (var i = 0; i < boxes.length; i++) buildBox(boxes[i]);\n    } else if (tries++ < 150) { setTimeout(fill, tries < 20 ? 50 : 200); }   // external asset may still be loading (waits up to ~27 s)\n  }\n  fill();\n  // if the asset script is still in flight, fill as soon as it lands (covers WebViews that load it asynchronously)\n  var ks = document.querySelectorAll('script[src*=\"_kanji_strokes\"]');\n  for (var si = 0; si < ks.length; si++) ks[si].addEventListener('load', fill, false);\n})();\n\n</script>\n<script>\n\n</script>\n</div>\n</body></html>"}];
